    n = len(items)
    sp = (4.4 / (n - 1)) if n > 1 else 1
    r = min(.45, sp * .42)
    for k, (part, l) in enumerate(items):
        by = 2.2 - k * sp if n > 1 else 0
        ax_, ay_ = anc[part]
        ax.plot([ax_, 4.6], [ay_, by], color="#94a3b8", lw=1.2, ls=(0, (3, 2)), zorder=8)
        ax.add_patch(Circle((ax_, ay_), .09, fc="#ea580c", ec="none", zorder=9))
