        ax.add_patch(FancyBboxPatch((cx - .34, cy - .7), .68, .95, boxstyle="round,pad=0,rounding_size=.15", fc="#86efac", ec=INK, lw=1.8, zorder=3))
        ax.add_patch(Rectangle((cx - .13, cy + .25), .26, .42, fc="#86efac", ec=INK, lw=1.8, zorder=3))
