        ax.add_patch(Rectangle((cx - .12, cy + .25), .24, .38, fc="#bae6fd", ec=INK, lw=1.8, zorder=3))
        ax.add_patch(Rectangle((cx - .15, cy + .6), .3, .12, fc="#2563eb", ec=INK, lw=1.4, zorder=4))
