_UZ_R = {"gunes": 1.9, "dunya": .95, "ay": .38}


def _uz_buyukluk(ax, d):
    ps = d.get("panels", [])
    x = 0.0
    for p in ps:
        kd = {"g1": "gunes", "g2": "dunya", "g3": "ay"}.get(p["kind"], p["kind"])
        r = _UZ_R[kd]
        x += r + .6
        _uz_cisim(ax, kd, x, 0, r)
        if p.get("label"):
            _bio_bubble(ax, x, -(r + .7), p["label"], fs=12, r=.36)
        x += r + .6
    ax.set_xlim(-.2, x + .2)
    ax.set_ylim(-3.4, 2.9)


