    ax.text(3.4, -1.55, d["m"], ha="center", va="center", fontsize=20, fontweight="bold", color=ORANGE)
    ax.text(3.9, -2.75, "Oklar kanın akış yönünü gösterir.", ha="center", va="center", fontsize=10.5, color=INK)
