# ---- tekrarsızlık için son soru gövdeleri
def recent_stems():
    """Son soru gövdeleri (rakamlar maskeli: yalnızca sayıları değişen sorular da 'görülmüş' sayılır)."""
    import re
    d = _load("stems.json", {})
    return {k: [re.sub(r"\W+", " ", re.sub(r"\d+", "0", str(x))).strip()[:70] for x in v] for k, v in d.items()}


def _sig_tokens(q):
    import re
    t = (str(q.get("question", "")) + " " + str(q.get("passage", ""))).replace("İ", "i").replace("I", "ı").lower()
    tk = {w[:5] for w in re.findall(r"[a-zçğıöşü]{4,}", t)}
    if q.get("tpl"):  # hazır kalıp: kök aynı olsa da doğru cevabın içeriği farklıysa farklı soru sayılır (yalnızca şıkları karışan "aynı" soru olmasın)
        try:
            at = str((q.get("options") or {}).get(q.get("answer"), "")).replace("İ", "i").replace("I", "ı").lower()
            tk |= {"@" + w[:5] for w in re.findall(r"[a-zçğıöşü]{4,}", at)}
        except Exception:
            pass
    return sorted(tk)


def _num_tokens(q):
    import re, json
    sh = q.get("shape")
    blob = " ".join([str(q.get("question", "")), str(q.get("passage", "")), " ".join(str(v) for v in (q.get("options") or {}).values()), json.dumps(sh, ensure_ascii=False) if isinstance(sh, dict) else ""])
    return sorted({"#" + n for n in re.findall(r"\d+(?:[.,]\d+)?", blob)})[:12]


def recent_sigs():
    return _load("qsigs.json", {})


def recent_styles():
    """Son 3 sınavın soru-tarzı anahtarları: {ders: {anahtar}} (arka arkaya aynı tarz gelmesin)."""
    d = _load("styles.json", {})
    return {k: {x for b in v[-3:] for x in b} for k, v in d.items()}


def add_styles(questions):
    d = _load("styles.json", {})
    by = {}
    for q in questions:
        k = q.get("_sty")
        if k:
            by.setdefault(q.get("subject", "Genel"), []).append(k)
    for sj, ks in by.items():
        d.setdefault(sj, []).append(sorted(set(ks)))
        d[sj] = d[sj][-6:]
    _save("styles.json", d)


def add_stems(questions):
    import re
    d = _load("stems.json", {})
    sg = recent_sigs()
    for q in questions:
        s = re.sub(r"\W+", " ", re.sub(r"\d+", "0", str(q.get("question", "")).lower())).strip()[:70]
        d.setdefault(q.get("subject", "Genel"), []).append(s)
        tk = _sig_tokens(q)
        if len(tk) >= 4 and q.get("tpl"):  # hazır kalıp (sayıları kodla seçilir): sayı belirteçleri de saklanır; yalnız sayısı farklı olan soru "aynı" sayılmaz
            tk = tk + _num_tokens(q)
        if len(tk) >= 4:
            sg.setdefault(q.get("subject", "Genel"), []).append(" ".join(tk))
    for k in d:
        d[k] = d[k][-400:]
    for k in sg:
        sg[k] = sg[k][-800:]
    _save("stems.json", d)
    _save("qsigs.json", sg)


# ---- hatalı bildirilen sorular: bankadan ve yanlış arşivinden çıkar, bir daha üretilirse elenir
def qstats_record(rows):
    """Çözülen soruların sonucunu (soru gövdesi bazında) birikimli kaydeder. rows: {stem, subject, topic, src, key, chosen}"""
    try:
        d = _load("qstats.json", {})
        for r in rows:
            if not r.get("stem"):
                continue
            e = d.setdefault(r["stem"], {"n": 0, "c": 0, "e": 0, "o": {}, "s": r.get("subject", ""), "t": r.get("topic", ""), "src": r.get("src", "ai"), "k": r.get("key")})
            if r.get("chosen") in (None, ""):
                e["e"] += 1
                continue
            e["n"] += 1
            if r["chosen"] == r.get("key"):
                e["c"] += 1
            else:
                e["o"][r["chosen"]] = e["o"].get(r["chosen"], 0) + 1
        if len(d) > 6000:
            d = dict(list(d.items())[-6000:])
        _save("qstats.json", d)
    except Exception:
        pass


def suspects(min_n=2, share=0.75):
    """Şüpheli sorular: en az min_n kez çözülmüş, hiç doğru yapılmamış ve yanlışların çoğu AYNI şıkta toplanmış (cevap anahtarı hatalı olabilir).
    Kodla üretilen (fabrika) sorular dışlanır: kalıpları sayı-bağımsız tek gövdede toplandığından yasaklanmaz."""
    out = []
    for stem, e in _load("qstats.json", {}).items():
        if e.get("src") in ("fabrika", "seed") or e.get("n", 0) < min_n or e.get("c", 0) > 0:
            continue
        o = e.get("o") or {}
        if o and max(o.values()) / max(1, sum(o.values())) >= share:
            out.append(stem)
    return out


def update_quarantine():
    """Şüpheli soruları karantinaya alır (seçimden çıkar; gece betiği havuzdan siler). -> karantinadaki toplam"""
    try:
        q = set(_load("quarantine.json", []))
        q |= set(suspects())
        _save("quarantine.json", sorted(q)[-2000:])
        return len(q)
    except Exception:
        return 0


def unit_health(min_n=10, max_rate=0.3):
    """Ünite/kaynak bazında doğru oranı çok düşük olanlar -> [(ders, konu, kaynak, çözüm, doğru oranı)]"""
    g = {}
    for e in _load("qstats.json", {}).values():
        k = (e.get("s", ""), e.get("t", ""), e.get("src", "ai"))
        a = g.setdefault(k, [0, 0])
        a[0] += e.get("n", 0)
        a[1] += e.get("c", 0)
    return sorted([(k[0], k[1], k[2], n, c / n) for k, (n, c) in g.items() if n >= min_n and c / n <= max_rate], key=lambda t: t[4])


