    out = set()
    for s_ in list(_load("bad.json", [])) + list(_load("quarantine.json", [])):
        out.add(s_)
        out.add(_r.sub(r"\W+", " ", _r.sub(r"\d+", "0", s_)).strip())  # sayı-maskeli _stem biçimi
