# ---- SORU BANKASI: kapsam başına önceden üretilmiş, doğrulanmış sorular (tek kullanımlık, tüketilir)
import hashlib
import re
import threading

_BANK_LOCK = threading.Lock()
BANK_VER = "v3"  # soru kalitesi/zorluk kuralları değişince artırılır: eski bankadaki sorular kullanılmaz
BANK_PER_KEY = 150
BANK_TOTAL = 6000


def bank_key(grade_label, subject, difficulty, topics):
    return hashlib.sha1(f"{BANK_VER}|{grade_label}|{subject}|{difficulty}|{topics}".encode("utf-8")).hexdigest()[:16]


def _bstem(q):
    return re.sub(r"\W+", " ", re.sub(r"\d+", "0", str(q.get("question", "")).lower()))[:70].strip()


def _bank():
    return _load("bank.json", {})


def bank_count(key):
    e = _bank().get(key)
    return len(e["qs"]) if e else 0


def bank_peek(key, limit=20):
    with _BANK_LOCK:
        e = _bank().get(key)
        return [dict(q) for q in e["qs"][:limit]] if e else []


def bank_peek_similar(grade_label, subject, difficulty, topics, limit=20, exclude_key=""):
    """Aynı sınıf/ders/zorlukta, konusu örtüşen diğer banka kapsamlarından hazır sorular -> [(anahtar, soru)]"""
    tl = str(topics or "").lower()
    chunks = [c.strip()[:40] for c in re.split(r"[|;]", tl) if len(c.strip()) >= 6]
    out = []
    for k, e in _bank().items():
        m = e.get("meta", {})
        if k == exclude_key or m.get("grade_label") != grade_label or m.get("subject") != subject:
            continue
        if m.get("difficulty") != difficulty:  # komşu zorluk kademesindeki (±1) banka soruları da uygundur
            try:
                from . import curriculum as _cu
                _L = list(_cu.DIFFICULTIES)
                if abs(_L.index(m.get("difficulty")) - _L.index(difficulty)) > 1:
                    continue
            except Exception:
                continue
        et = str(m.get("topics", "")).lower()
        if not tl or not et or et[:40] in tl or any(c in et for c in chunks):
            for q in e["qs"]:
                out.append((k, q))
                if len(out) >= limit:
                    return out
    return out


_QLOCK = _pth.Lock()


def quality_add(delta):
    """Kalite sayaçları (ortak dosya): {ders: {olay: adet}} değerlerini toplayarak birleştirir."""
    with _QLOCK:
        q = _load("quality.json", {})
        for sj, ev in delta.items():
            e = q.setdefault(sj, {})
            for k, v in ev.items():
                e[k] = e.get(k, 0) + v
        _save("quality.json", q)


def quality():
    return _load("quality.json", {})


def budget_take(name, limit):
    """Günlük arka plan işi hakkı (kota koruması). -> hak alındı mı"""
    d = _load("budgets.json", {})
    k = str(_today())
    e = d.get(name) or {}
    n = int(e.get("n", 0)) if e.get("d") == k else 0
    if n >= limit:
        return False
    d[name] = {"d": k, "n": n + 1}
    _save("budgets.json", d)
    return True


def bank_remove(key, stems):
    stems = set(stems)
    if not stems:
        return
    with _BANK_LOCK:
        b = _bank()
        e = b.get(key)
        if not e:
            return
        e["qs"] = [q for q in e["qs"] if _bstem(q) not in stems]
        if e["qs"]:
            e["ts"] = int(time.time())
        else:
            b.pop(key)
        _save("bank.json", b)


def bank_put(key, meta, qs):
    clean = [{k: v for k, v in q.items() if k != "id"} for q in qs]
    clean = [c for c in clean if _bstem(c)]
    if not clean:
        return 0
    with _BANK_LOCK:
        b = _bank()
        e = b.setdefault(key, {"meta": meta, "qs": [], "ts": 0})
        have = {_bstem(q) for q in e["qs"]}
        added = 0
        for c in clean:
            st_ = _bstem(c)
            if st_ in have:
                continue
            e["qs"].append(c)
            have.add(st_)
            added += 1
        e["qs"] = e["qs"][-BANK_PER_KEY:]
        e["ts"] = int(time.time())
        total = sum(len(x["qs"]) for x in b.values())
        if total > BANK_TOTAL:  # en eski kullanılmayan kapsamlar önce silinir
            for k in sorted((k for k in b if k != key), key=lambda k: b[k].get("ts", 0)):
                total -= len(b[k]["qs"])
                b.pop(k)
                if total <= BANK_TOTAL:
                    break
        _save("bank.json", b)
        return added


def bank_all():
    return _bank()


def replace_bank(b):
    with _BANK_LOCK:
        _save("bank.json", b if isinstance(b, dict) else {})


def replace_stems(d):
    _save("stems.json", d if isinstance(d, dict) else {})


def bank_stats():
    per = {}
    for e in _bank().values():
        sj = (e.get("meta") or {}).get("subject", "?")
        per[sj] = per.get(sj, 0) + len(e["qs"])
    return {"total": sum(per.values()), "per": per}


# ---- takılma izleme: yavaş adımlar bellekte (son 400 kayıt) tutulur; yalnızca ?admin=1 ekranında görünür
import threading as _pth
_PERF = []
_PERF_LK = _pth.Lock()


def perf_add(name, secs, err=""):
    try:
        with _PERF_LK:
            _PERF.append((time.time(), str(name), float(secs), str(err)[:120]))
            if len(_PERF) > 400:
                del _PERF[:100]
    except Exception:
        pass


def perf_timed(name):
    import functools

    def deco(fn):
        @functools.wraps(fn)
        def w(*a, **k):
            t0 = time.time()
            try:
                return fn(*a, **k)
            except BaseException as e:
                perf_add(name, time.time() - t0, type(e).__name__)
                raise
            finally:
                dt = time.time() - t0
                if dt >= 0.15:  # küçük işleri kaydetme (kayıt şişmesin)
                    perf_add(name, dt)
        return w
    return deco


def perf_summary():
    """({ad: (adet, ort, en çok)}, en yavaş 8 kayıt, son 5 hata)"""
    with _PERF_LK:
        rows = list(_PERF)
    agg = {}
    for _t, n, d, _e in rows:
        c, tot, mx = agg.get(n, (0, 0.0, 0.0))
        agg[n] = (c + 1, tot + d, max(mx, d))
    agg = {n: (c, tot / c, mx) for n, (c, tot, mx) in agg.items()}
    slow = sorted(rows, key=lambda r: -r[2])[:8]
    errs = [r for r in rows if r[3]][-5:]
    return agg, slow, errs


for _pn in ("_save", "_load", "gh_pull_once"):
    if _pn in globals():
        globals()[_pn] = perf_timed("store." + _pn.strip("_"))(globals()[_pn])
