def _mf_inter(subject):
    """5. sınıf MAT.5.3.7: iki çemberin kesişimiyle oluşan ABC üçgeni (A, B merkez; C kesişim noktası). Şekilde verilen ölçüler metinle birebir."""
    import math as _m
    kind = random.choice(["type", "type", "perim", "missing", "perim_eq"])

    def valid():
        for _ in range(200):
            r1, r2, dd = random.randint(2, 9), random.randint(2, 9), random.randint(2, 9)
            if abs(r1 - r2) < dd < r1 + r2 and sorted([r1, r2, dd])[2] ** 2 != sorted([r1, r2, dd])[0] ** 2 + sorted([r1, r2, dd])[1] ** 2:
                return r1, r2, dd
        return 5, 5, 5
    base = {"type": "geo", "sub_type": "nested_circles", "mode": "intersect", "names": ["A", "B", "C"]}
    if kind == "type":
        pick = random.choice(["eskenar", "ikiz", "ikiz2", "cesit"])
        if pick == "eskenar":
            r = random.randint(2, 9)
            r1 = r2 = dd = r
        elif pick in ("ikiz", "ikiz2"):
            r = random.randint(2, 9)
            dd = random.choice([x for x in range(2, 2 * r) if x != r and x <= 12])
            r1 = r2 = r
            if pick == "ikiz2":
                r1 = dd
                r2 = random.choice([x for x in range(1, 2 * dd) if x != dd and x <= 12 and abs(r1 - x) < dd < r1 + x])
                r = None
        else:
            r1, r2, dd = valid()
            while len({r1, r2, dd}) < 3:
                r1, r2, dd = valid()
        kinds = {"eskenar": "Eşkenar üçgen", "ikiz": "İkizkenar üçgen", "ikiz2": "İkizkenar üçgen", "cesit": "Çeşitkenar üçgen"}
        cor = kinds[pick]
        ol = ["Eşkenar üçgen", "İkizkenar üçgen", "Çeşitkenar üçgen", "Dik üçgen"]
        random.shuffle(ol)
        sh = dict(base, r1=r1, r2=r2, d=dd, sides={"AC": f"{r1} cm", "BC": f"{r2} cm", "AB": f"{dd} cm"})
        q = ("Şekilde A ve B merkezli iki çember C noktasında kesişmektedir. Çemberlerin yarıçapları ve merkezleri arasındaki uzaklık şekilde verilmiştir. "
             "Buna göre ABC üçgeni aşağıdakilerden hangisidir?")
        sd = sorted([r1, r2, dd])
        ex = (f"|AC| = {r1} cm, |BC| = {r2} cm ve |AB| = {dd} cm. " + ("Üç kenar eşit: eşkenar." if pick == "eskenar" else "İki kenar eşit: ikizkenar." if pick != "cesit" else "Üç kenar da farklı: çeşitkenar."))
        return _mf_raw(subject, "Çember ve üçgen", q, (ol, cor), ex, shape=sh)
    if kind in ("perim", "perim_eq"):
        if kind == "perim_eq":
            r = random.randint(2, 8)
            dd = random.choice([x for x in range(2, 2 * r) if x <= 12])
            r1 = r2 = r
        else:
            r1, r2, dd = valid()
        c = r1 + r2 + dd
        sh = dict(base, r1=r1, r2=r2, d=dd, sides={"AC": f"{r1} cm", "BC": f"{r2} cm", "AB": f"{dd} cm"})
        q = ("Şekilde A ve B merkezli iki çember C noktasında kesişmektedir. Çemberlerin yarıçapları ve merkezleri arasındaki uzaklık şekilde verilmiştir. "
             "Buna göre ABC üçgeninin çevresi kaç cm’dir?")
        wr = [r1 + r2, 2 * (r1 + r2), c + dd, c - 1, c + 2, r1 * r2]
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
        return _mf_raw(subject, "Çember ve üçgen", q, o, f"|AC| + |BC| + |AB| = {r1} + {r2} + {dd} = {c} cm.", shape=sh) if o else None
    r = random.randint(3, 9)
    dd = random.choice([x for x in range(2, 2 * r) if x != r and x <= 14])
    c = 2 * r + dd
    sh = dict(base, r1=r, r2=r, d=dd, sides={"AC": f"{r} cm", "BC": f"{r} cm", "AB": "?"}, caption=f"ABC üçgeninin çevresi = {c} cm")
    q = (f"Şekilde A ve B merkezli, yarıçapları eşit iki çember C noktasında kesişmektedir. ABC üçgeninin çevresi {c} cm olduğuna göre merkezler arasındaki |AB| uzaklığı kaç cm’dir?")
    wr = [c - r, c // 2, 2 * r, c - dd, dd + 1, dd + 2]
    o = _mf_opts(dd, wr, lambda v: f"{v} cm")
    return _mf_raw(subject, "Çember ve üçgen", q, o, f"|AC| = |BC| = {r} cm. Çevre = {r} + {r} + |AB| = {c}, buradan |AB| = {c} − {2 * r} = {dd} cm.", shape=sh) if o else None


_MF_GENS += [(_mf_inter, ("çember", "kesişen çember", "iki çember"), (5,))]


# ---------------------------------------------------------------- 5-6. SINIF: OLASILIK ve VERİ (kodla hesaplanan, görselle birebir uyumlu)

_SKINS = [  # (kap, tek-kap-eki hali, tür-1, tür-2, tür-3, tür-4, nesne)  -> aynı olasılık problemi, farklı bağlam
    ("kutuda", "kutudan", ["kırmızı", "mavi", "yeşil", "sarı"], "bilye"),
    ("torbada", "torbadan", ["kırmızı", "beyaz", "siyah", "turuncu"], "top"),
    ("sepette", "sepetten", ["elma", "armut", "portakal", "muz"], "meyve"),
    ("çantada", "çantadan", ["mavi", "kırmızı", "yeşil", "mor"], "kalem"),
    ("poşette", "poşetten", ["çilekli", "vişneli", "limonlu", "portakallı"], "şeker"),
    ("kavanozda", "kavanozdan", ["kırmızı", "sarı", "mavi", "yeşil"], "düğme"),
]


def _skin_q(nm_kinds):
    cap, capn, kinds, obj = random.choice(_SKINS)
    return cap, capn, random.sample(kinds, nm_kinds), obj


def _mf_prob5(subject, kind=None):
    from fractions import Fraction as Fr
    show = lambda f: "0" if f == 0 else ("1" if f == 1 else f"{f.numerator}/{f.denominator}")
    kind = kind or random.choice(["zar", "cark", "bilye"])
    if kind == "zar":
        evs = [("7’den küçük", lambda x: x < 7), ("7", lambda x: x == 7), ("çift sayı", lambda x: x % 2 == 0), ("3’ten büyük", lambda x: x > 3),
               ("asal sayı", lambda x: x in (2, 3, 5)), ("6’nın çarpanı", lambda x: 6 % x == 0), ("5’ten küçük", lambda x: x < 5), ("1 veya 2", lambda x: x in (1, 2)),
               ("10’dan büyük", lambda x: x > 10), ("0’dan büyük", lambda x: x > 0)]
        nm, f = random.choice(evs)
        c = Fr(sum(1 for x in range(1, 7) if f(x)), 6)
        pool = [Fr(k, 6) for k in range(0, 7) if Fr(k, 6) != c]
        random.shuffle(pool)
        o = _mf_opts(show(c), [show(w) for w in pool], str, sort=False)
        ex = f"Zarın yüzlerinde 1, 2, 3, 4, 5, 6 vardır (6 eş olası durum). İstenen durum sayısı {c.numerator * 6 // c.denominator if c else 0}; olasılık = {show(c)}."
        return _mf_raw(subject, "Olasılık", f"Hilesiz bir zar atılıyor. Üst yüze gelen sayının {nm} olma olasılığı kaçtır? (Sonuç en sade biçimdedir.)", o, ex) if o else None
    if kind == "cark":  # numaralı kartlar (yalnızca metin; şekil gerekmez)
        N = random.choice([8, 10, 12, 15, 20])
        evs = [("çift sayı", lambda x: x % 2 == 0), ("3’ün katı", lambda x: x % 3 == 0), ("5’ten büyük", lambda x: x > 5), ("asal sayı", lambda x: x > 1 and all(x % d for d in range(2, x))),
               (f"{N}’den büyük", lambda x: x > N), ("5’in katı", lambda x: x % 5 == 0), ("tek sayı", lambda x: x % 2 == 1)]
        nm, f = random.choice(evs)
        cnt = sum(1 for x in range(1, N + 1) if f(x))
        c = Fr(cnt, N)
        pool = [Fr(x, N) for x in range(0, N + 1) if Fr(x, N) != c]
        random.shuffle(pool)
        o = _mf_opts(show(c), [show(w) for w in pool], str, sort=False)
        q = f"Bir kutuda 1’den {N}’e kadar numaralanmış {N} özdeş kart vardır. Kutudan rastgele çekilen bir kartın numarasının {nm} olma olasılığı kaçtır? (Sonuç en sade biçimdedir.)"
        return _mf_raw(subject, "Olasılık", q, o, f"1’den {N}’e kadar {nm} olan {cnt} kart vardır; toplam {N} kart → {show(c)}.") if o else None
    k, y, m = random.sample(range(1, 9), 3)
    n = k + y + m
    cap, capn, cols, obj = _skin_q(3)
    cnt = [k, y, m]
    pi = random.randrange(3)
    c = Fr(cnt[pi], n)
    wr = [Fr(cnt[pi], n - cnt[pi]), Fr(n - cnt[pi], n), Fr(cnt[pi] + 1, n), Fr(1, 3), Fr(cnt[(pi + 1) % 3], n)]
    wr = [w for w in wr if w != c]
    o = _mf_opts(show(c), [show(w) for w in wr], str, sort=False)
    ad = (lambda t: f"{t} {obj}") if obj != "meyve" else (lambda t: t)
    q = f"{cap.capitalize()} {k} {ad(cols[0])}, {y} {ad(cols[1])} ve {m} {ad(cols[2])} vardır. Rastgele seçilen birinin {cols[pi]}{' ' + obj if obj != 'meyve' else ''} olma olasılığı kaçtır? (Sonuç en sade biçimdedir.)"
    return _mf_raw(subject, "Olasılık", q, o, f"Toplam {n}; {cols[pi]} olan {cnt[pi]} tane → {show(c)}.") if o and len(set(o[0])) == 4 else None


def _mf_bar5(subject, kind=None):
    sets = [("Bir okulda öğrencilerin sevdiği meyveler", ["Elma", "Muz", "Çilek", "Kiraz"], "öğrenci"),
            ("Bir sınıfta öğrencilerin okuduğu kitap sayısı (aylara göre)", ["Ocak", "Şubat", "Mart", "Nisan"], "kitap"),
            ("Bir kütüphaneye gelen ziyaretçi sayısı (günlere göre)", ["Pzt", "Sal", "Çar", "Per"], "kişi"),
            ("Bir markette satılan ürün sayısı", ["Süt", "Ekmek", "Yumurta", "Peynir"], "adet"),
            ("Bir okulda spor kulüplerine kayıtlı öğrenciler", ["Futbol", "Voleybol", "Yüzme", "Satranç"], "öğrenci"),
            ("Bir çiftlikteki hayvan sayısı", ["İnek", "Koyun", "Tavuk", "At"], "adet"),
            ("Bir sınıfta hafta içi günlük okunan sayfa sayısı", ["Pzt", "Sal", "Çar", "Per"], "sayfa"),
            ("Bir parkta toplanan atık kâğıt miktarı (haftalara göre)", ["1. hafta", "2. hafta", "3. hafta", "4. hafta"], "kg"),
            ("Bir kantinde satılan içecekler", ["Su", "Süt", "Meyve suyu", "Ayran"], "adet")]
    ttl, labs, unit = random.choice(sets)
    vals = random.sample(range(4, 31), 4)
    kind = kind or random.choice(["toplam", "fark", "enaz", "iki"])
    mx, mn = max(vals), min(vals)
    imx, imn = vals.index(mx), vals.index(mn)
    if kind == "toplam":
        c = sum(vals)
        wr = [c - mn, c + 5, c - 10, sum(vals[:3]), c + 10]
        q, ex = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. Buna göre dört sütunun toplamı kaç {unit}dir?".replace("kaç adetdir", "kaç adettir").replace("kaç kitapdır", "kaç kitaptır").replace("kaç sayfadir", "kaç sayfadır").replace("kaç kgdir", "kaç kg’dır"), f"{' + '.join(map(str, vals))} = {c}."
    elif kind == "fark":
        c = mx - mn
        wr = [mx + mn, c + 2, c - 2, mx - sorted(vals)[1], c + 5]
        q, ex = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. En yüksek sütun ile en düşük sütun arasındaki fark kaçtır?", f"{mx} − {mn} = {c}."
    elif kind == "enaz":
        c = labs[imn]
        wr = [x for x in labs if x != c]
        q, ex = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. Değeri en küçük olan sütun hangisidir?", f"En küçük değer {mn}; bu sütun {c}."
        o = _mf_opts(c, wr, str, sort=False)
        shape = {"type": "bar_chart", "labels": labs, "values": vals, "title": ttl}
        return _mf_raw(subject, "Sütun Grafiği", q, o, ex, shape=shape) if o else None
    elif kind == "enok":
        c = labs[imx]
        wr = [x for x in labs if x != c]
        q, ex = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. Bu verilere göre karar verilirken değeri en büyük olan sütun esas alınacaktır. Hangi sütun esas alınmalıdır?", f"En büyük değer {mx}; bu sütun {c}."
        o = _mf_opts(c, wr, str, sort=False)
        shape = {"type": "bar_chart", "labels": labs, "values": vals, "title": ttl}
        return _mf_raw(subject, "Sütun Grafiği", q, o, ex, shape=shape) if o else None
    elif kind == "yorum":
        cand = []
        for a_ in range(4):
            for b_ in range(4):
                if a_ == b_:
                    continue
                cand.append((f"{labs[a_]} sütunu, {labs[b_]} sütunundan daha yüksektir.", vals[a_] > vals[b_]))
                cand.append((f"{labs[a_]} sütunu, {labs[b_]} sütununun iki katıdır.", vals[a_] == 2 * vals[b_]))
                cand.append((f"{labs[a_]} sütunu ile {labs[b_]} sütununun değerleri eşittir.", vals[a_] == vals[b_]))
        cand.append((f"En yüksek sütun {labs[imx]} sütunudur.", True))
        cand.append((f"En düşük sütun {labs[imx]} sütunudur.", False))
        good = [x for x in cand if x[1]]
        bad = [x for x in cand if not x[1]]
        good = [g_ for g_ in good if g_[0].endswith("daha yüksektir.") or g_[0].startswith("En yüksek")]
        if not good or len(bad) < 3:
            return None
        cg = random.choice(good)
        wb = random.sample(bad, 3)
        ol = [cg[0]] + [w_[0] for w_ in wb]
        if len(set(ol)) < 4:
            return None
        random.shuffle(ol)
        q = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. Bu grafikle ilgili aşağıdaki yorumlardan hangisi doğrudur?"
        shape = {"type": "bar_chart", "labels": labs, "values": vals, "title": ttl}
        return _mf_raw(subject, "Sütun Grafiği", q, (ol, cg[0]), f"Grafikteki değerler: " + ", ".join(f"{a_} = {b_}" for a_, b_ in zip(labs, vals)) + f". “{cg[0]}” yorumu verilere uygundur.", shape=shape)
    else:
        i, j = random.sample(range(4), 2)
        c = vals[i] + vals[j]
        wr = [abs(vals[i] - vals[j]), c + 4, c - 4, sum(vals) - c, c + 10]
        q, ex = f"Şekildeki sütun grafiği “{ttl}” verisini göstermektedir. {labs[i]} ve {labs[j]} sütunlarının değerleri toplamı kaçtır?", f"{vals[i]} + {vals[j]} = {c}."
    o = _mf_opts(c, [w for w in wr if w > 0], str)
    shape = {"type": "bar_chart", "labels": labs, "values": vals, "title": ttl}
    return _mf_raw(subject, "Sütun Grafiği", q, o, ex, shape=shape) if o else None


def _mf_probdeg(subject):
    """Olasılık değeri 0 / 1 / 1/2 olan olayı bulma (olumlu kök; olaylar kodla hesaplanır, tam bir doğru)."""
    from fractions import Fraction as Fr
    ev = [("Üst yüze gelen sayı 7’den küçüktür.", Fr(1)), ("Üst yüze gelen sayı 7’dir.", Fr(0)), ("Üst yüze gelen sayı çifttir.", Fr(1, 2)),
          ("Üst yüze gelen sayı 6’dan küçüktür.", Fr(5, 6)), ("Üst yüze gelen sayı 1’dir.", Fr(1, 6)), ("Üst yüze gelen sayı 10’dan büyüktür.", Fr(0)),
          ("Üst yüze gelen sayı 1’den büyük ya da 1’e eşittir.", Fr(1)), ("Üst yüze gelen sayı asaldır.", Fr(1, 2)), ("Üst yüze gelen sayı 4’ten büyüktür.", Fr(1, 3))]
    tgt = random.choice([Fr(0), Fr(1), Fr(1, 2)])
    good = [e for e in ev if e[1] == tgt]
    bad = [e for e in ev if e[1] != tgt]
    if not good or len(bad) < 3:
        return None
    c = random.choice(good)
    ws = random.sample(bad, 3)
    names = {Fr(0): "0 (imkânsız)", Fr(1): "1 (kesin)", Fr(1, 2): "1/2"}
    allv = [c] + ws
    random.shuffle(allv)
    ol = [a[0] for a in allv]
    if len(set(ol)) < 4:
        return None
    o = (ol, c[0])
    qd = {Fr(0): "0 olan (imkânsız)", Fr(1): "1 olan (kesin)", Fr(1, 2): "1/2 olan"}[tgt]
    return _mf_raw(subject, "Olasılık", f"Hilesiz bir zar atılıyor. Aşağıdaki olaylardan hangisinin olasılığı {qd} bir olaydır?", o,
                   f"Zarda 1, 2, 3, 4, 5, 6 vardır. “{c[0]}” olayının olasılığı {names[tgt]}.")


def _mf_probmost(subject):
    """Hangi tür seçilme olasılığı en yüksek/en düşük (tek doğru; farklı bağlamlar)."""
    cap, capn, cols, obj = _skin_q(4)
    cnt = random.sample(range(1, 13), 4)
    hi = random.choice([True, False])
    t = max(cnt) if hi else min(cnt)
    i = cnt.index(t)
    n = sum(cnt)
    ad = (lambda t_: f"{t_} {obj}") if obj != "meyve" else (lambda t_: t_)
    lst = ", ".join(f"{k_} {ad(c_)}" for c_, k_ in zip(cols[:-1], cnt[:-1])) + f" ve {cnt[-1]} {ad(cols[-1])}"
    o = _mf_opts(cols[i], [c_ for j_, c_ in enumerate(cols) if j_ != i], str, sort=False)
    return _mf_raw(subject, "Olasılık", f"{cap.capitalize()} {lst} vardır. Rastgele seçilen birinin hangi türden olma olasılığı {'en yüksektir' if hi else 'en düşüktür'}?", o,
                   f"Olasılık, sayıyla orantılıdır; {'en çok' if hi else 'en az'} olan {cols[i]} ({t} tane, toplam {n}).") if o else None


def _mk_kind(fn, kind, name):
    def g(subject):
        return fn(subject, kind)
    g.__name__ = name
    return g


_mf_prob_zar = _mk_kind(_mf_prob5, "zar", "_mf_prob_zar")
_mf_prob_kart = _mk_kind(_mf_prob5, "cark", "_mf_prob_kart")
_mf_prob_bilye = _mk_kind(_mf_prob5, "bilye", "_mf_prob_bilye")
_mf_bar_top = _mk_kind(_mf_bar5, "toplam", "_mf_bar_top")
_mf_bar_fark = _mk_kind(_mf_bar5, "fark", "_mf_bar_fark")
_mf_bar_enaz = _mk_kind(_mf_bar5, "enaz", "_mf_bar_enaz")
_mf_bar_iki = _mk_kind(_mf_bar5, "iki", "_mf_bar_iki")
_mf_bar_enok = _mk_kind(_mf_bar5, "enok", "_mf_bar_enok")
_mf_bar_yorum = _mk_kind(_mf_bar5, "yorum", "_mf_bar_yorum")
_PRB = ("olasılık",)
_BARK = ("sütun grafi", "veri", "grafik", "tablo")
_MF_GENS += [(_mf_prob_zar, _PRB, (5, 6)), (_mf_prob_kart, _PRB, (5, 6)), (_mf_prob_bilye, _PRB, (5, 6)), (_mf_probdeg, _PRB, (5, 6)), (_mf_probmost, _PRB, (5, 6)),
             (_mf_bar_top, _BARK, (5,)), (_mf_bar_fark, _BARK, (5,)), (_mf_bar_enaz, _BARK, (5,)), (_mf_bar_iki, _BARK, (5,)), (_mf_bar_enok, _BARK, (5,)), (_mf_bar_yorum, _BARK, (5,))]


def _tally(v):
    return " ".join(["||||/"] * (v // 5) + (["|" * (v % 5)] if v % 5 else []))


def _mf_tablo5(subject, kind):
    """Kategorik veri: tablo okuma / veriye dayalı karar / yorum değerlendirme (tüm sayılar tabloda; yanıtlar kodla hesaplanır)."""
    title, hdr, unit, cats, lo, hi, step, ctx = random.choice(_LQ_THEMES)
    n = random.choice([4, 5])
    cs = random.sample(cats, n)
    vals = _lq_vals(n, lo, hi, step)
    if not vals or len(set(vals)) < n:
        return None
    shape = {"type": "table", "title": title, "headers": [hdr, unit.capitalize()], "rows": [[c, v] for c, v in zip(cs, vals)]}
    lead = f"Tabloda “{title}” verisi gösterilmiştir."
    imx, imn = vals.index(max(vals)), vals.index(min(vals))
    if kind == "toplam":
        i, j = random.sample(range(n), 2)
        c = vals[i] + vals[j]
        wr = [abs(vals[i] - vals[j]), c + step, c - step, sum(vals) - c, c + 2 * step]
        q, ex = f"{lead} {cs[i]} ve {cs[j]} için verilen sayıların toplamı kaçtır?", f"{vals[i]} + {vals[j]} = {c}."
    elif kind == "tum":
        c = sum(vals)
        wr = [c - vals[imn], c + vals[imn], c - step, c + step, c + 2 * step]
        q, ex = f"{lead} Tablodaki tüm sayıların toplamı kaçtır?", " + ".join(map(str, vals)) + f" = {c}."
    elif kind == "fark":
        c = max(vals) - min(vals)
        wr = [max(vals) + min(vals), c + step, abs(c - step), max(vals), c + 2 * step]
        q, ex = f"{lead} En büyük sayı ile en küçük sayı arasındaki fark kaçtır?", f"{max(vals)} − {min(vals)} = {c}."
    elif kind == "karar":
        ws = [cs[k] for k in range(n) if k != imx]
        o = _mf_opts(cs[imx], ws, str, sort=False)
        if not o:
            return None
        return _mf_raw(subject, "İstatistik", f"{lead} Bu verilere göre sayısı en fazla olan hangisidir?", o,
                       f"En büyük sayı {max(vals)} ile {cs[imx]} satırındadır.", shape=shape)
    else:  # yorum
        i, j = random.sample(range(n), 2)
        if vals[i] < vals[j]:
            i, j = j, i
        d = vals[i] - vals[j]
        good = f"{cs[i]} için verilen sayı, {cs[j]} için verilen sayıdan {d} fazladır."
        bad = [f"{cs[i]} için verilen sayı, {cs[j]} için verilen sayıdan {d + step} fazladır.",
               f"{cs[j]} için verilen sayı, {cs[i]} için verilen sayıdan {d} fazladır.",
               f"{cs[imn]} için verilen sayı en fazladır." if imn != imx else f"{cs[(imx + 1) % n]} için verilen sayı en fazladır.",
               f"Tablodaki sayıların toplamı {sum(vals) + step} olarak bulunur."]
        bad = [b for b in dict.fromkeys(bad) if b != good]
        if len(bad) < 3:
            return None
        ol = [good] + random.sample(bad, 3)
        random.shuffle(ol)
        return _mf_raw(subject, "İstatistik", f"{lead} Bu tabloya göre aşağıdaki yorumlardan hangisi doğrudur?", (ol, good),
                       f"{cs[i]}: {vals[i]}, {cs[j]}: {vals[j]}; fark {d}. “{good}” yorumu verilere uygundur.", shape=shape)
    o = _mf_opts(c, [w for w in wr if w > 0 and w != c], str)
    return _mf_raw(subject, "İstatistik", q, o, ex, shape=shape) if o else None


def _mf_cetele5(subject, kind):
    """Çetele tablosu okuma: her '||||/' grubu 5'i gösterir (sayı yalnız çetelede; yanıt kodla hesaplanır)."""
    title, hdr, unit, cats, _lo, _hi, _st, ctx = random.choice(_LQ_THEMES)
    n = random.choice([3, 4])
    cs = random.sample(cats, n)
    vals = random.sample(range(3, 15), n)
    shape = {"type": "table", "title": title + " (çetele)", "headers": [hdr, "Çetele"], "rows": [[c, _tally(v)] for c, v in zip(cs, vals)]}
    lead = f"Çetele tablosunda her “||||/” grubu 5 {unit}yi göstermektedir." if False else "Çetele tablosunda her “||||/” grubu 5 birimi gösterir."
    if kind == "say":
        i = random.randrange(n)
        c = vals[i]
        wr = [c + 1, c - 1, c + 5, c - 5, c + 2]
        q, ex = f"{lead} {cs[i]} için kaç birim çetele tutulmuştur?", f"{vals[i] // 5} grup × 5 + {vals[i] % 5} = {vals[i]}."
    else:
        i, j = random.sample(range(n), 2)
        c = vals[i] + vals[j]
        wr = [abs(vals[i] - vals[j]), c + 1, c - 1, c + 5, sum(vals)]
        q, ex = f"{lead} {cs[i]} ve {cs[j]} için tutulan çetelelerin toplamı kaç birimdir?", f"{vals[i]} + {vals[j]} = {c}."
    o = _mf_opts(c, [w for w in wr if w > 0 and w != c], str)
    return _mf_raw(subject, "İstatistik", q, o, ex, shape=shape) if o else None


_mf_tab_top = _mk_kind(_mf_tablo5, "toplam", "_mf_tab_top")
_mf_tab_tum = _mk_kind(_mf_tablo5, "tum", "_mf_tab_tum")
_mf_tab_fark = _mk_kind(_mf_tablo5, "fark", "_mf_tab_fark")
_mf_tab_karar = _mk_kind(_mf_tablo5, "karar", "_mf_tab_karar")
_mf_tab_yorum = _mk_kind(_mf_tablo5, "yorum", "_mf_tab_yorum")
_mf_cetele_say = _mk_kind(_mf_cetele5, "say", "_mf_cetele_say")
_mf_cetele_top = _mk_kind(_mf_cetele5, "top", "_mf_cetele_top")
_BARK2 = ("sütun grafi", "veri", "grafik", "tablo", "çetele", "kategorik", "istatistik")
_MF_GENS += [(_mf_tab_top, _BARK2, (5,)), (_mf_tab_tum, _BARK2, (5,)), (_mf_tab_fark, _BARK2, (5,)), (_mf_tab_karar, _BARK2, (5,)), (_mf_tab_yorum, _BARK2, (5,)),
             (_mf_cetele_say, _BARK2, (5,)), (_mf_cetele_top, _BARK2, (5,))]


# ---------------------------------------------------------------- 5. SINIF: KESİR / ONDALIK / CEBİR (kodla hesaplanan)
def _fr_s(n, d):
    return f"{n}/{d}"


def _mf_fr_addsub(subject):
    d = random.choice([5, 6, 7, 8, 9, 10, 12])
    a, b = random.sample(range(1, d - 1), 2)
    add = random.random() < .5
    if add and a + b >= d:
        return None
    if not add and a < b:
        a, b = b, a
    c = a + b if add else a - b
    if c <= 0 or c >= d:
        return None
    nm = random.choice(["Elif", "Mert", "Zeynep", "Can"])
    if add:
        q = f"{nm} bir pizzanın {_fr_s(a, d)} kadarını, kardeşi ise aynı pizzanın {_fr_s(b, d)} kadarını yedi. İkisi birlikte pizzanın kaçını yemiştir?"
        ex, wr = f"{a}/{d} + {b}/{d} = {c}/{d}.", [a - b if a > b else b - a, c + 1, c - 1, a + b + d]
    else:
        q = f"{nm}’in kurdelesinin {_fr_s(a, d)}’si kırmızı boyanmıştır. Boyalı kısmın {_fr_s(b, d)}’i (bütünün {b}/{d}’i) solmuştur; solmayan boyalı kısım kurdelenin kaçıdır?"
        q = f"Bir su deposunun {_fr_s(a, d)} kadarı doludur. Depodan bütünün {_fr_s(b, d)} kadar su kullanılırsa depoda bütünün kaçı kalır?"
        ex, wr = f"{a}/{d} − {b}/{d} = {c}/{d}.", [a + b, c + 1, c - 1 if c > 1 else c + 2, b]
    o = _mf_opts(c, [w for w in wr if 0 < w], lambda v: _fr_s(v, d), sort=False)
    return _mf_raw(subject, "Kesirler", q, o, ex) if o else None


def _mf_fr_whole(subject):
    d = random.choice([4, 5, 6, 8, 9, 10, 12])
    n = random.randint(1, d - 1)
    kind = random.choice(["tamamla", "bilesik", "tamsayili"])
    if kind == "tamamla":
        c = d - n
        wr = [n, d + n, c + 1, c - 1 if c > 1 else c + 2, d]
        o = _mf_opts(c, [w for w in wr if w > 0], lambda v: _fr_s(v, d), sort=False)
        return _mf_raw(subject, "Kesirler", f"Bir kitabın {_fr_s(n, d)} kadarı okunmuştur. Kitabın okunmayan kısmı bütünün kaçıdır?", o, f"1 = {d}/{d}; {d}/{d} − {n}/{d} = {c}/{d}.") if o else None
    t = random.randint(1, 5)
    if kind == "bilesik":
        num = t * d + n
        c = f"{t} {n}/{d}"
        wr = [f"{t + 1} {n}/{d}", f"{t} {d - n}/{d}", f"{t - 1 if t > 1 else t + 2} {n}/{d}", f"{n} {t}/{d}"]
        o = _mf_opts(c, wr, str, sort=False)
        return _mf_raw(subject, "Kesirler", f"{num}/{d} bileşik kesri hangi tam sayılı kesre eşittir?", o, f"{num} ÷ {d} = {t} kalan {n}; {t} tam {n}/{d}.") if o else None
    num = t * d + n
    c = f"{num}/{d}"
    wr = [f"{t * d - n}/{d}", f"{t + n}/{d}", f"{num + d}/{d}", f"{t * n}/{d}"]
    o = _mf_opts(c, wr, str, sort=False)
    return _mf_raw(subject, "Kesirler", f"{t} {n}/{d} tam sayılı kesri hangi bileşik kesre eşittir?", o, f"{t} × {d} + {n} = {num}; {num}/{d}.") if o and len(set(o[0])) == 4 else None


def _mf_fr_of(subject):
    d = random.choice([3, 4, 5, 6, 8, 10])
    n = random.randint(1, d - 1)
    u = random.randint(2, 12)
    tot = d * u
    c = n * u
    wr = [tot - c, c + u, u, tot // 2 if tot // 2 != c else tot + 1, c * 2]
    o = _mf_opts(c, [w for w in wr if w > 0], str)
    nm = random.choice(["Bir sınıfta", "Bir koşuda", "Bir bahçede", "Bir kütüphanede", "Bir kantinde"])
    q = {"Bir sınıfta": f"Bir sınıfta {tot} öğrenci vardır. Öğrencilerin {_fr_s(n, d)} kadarı gözlüklüdür. Gözlüklü kaç öğrenci vardır?",
         "Bir koşuda": f"Bir koşu parkuru {tot} km’dir. Ece parkurun {_fr_s(n, d)} kadarını koştu. Ece kaç km koşmuştur?",
         "Bir bahçede": f"Bir bahçede {tot} ağaç vardır. Ağaçların {_fr_s(n, d)} kadarı meyve ağacıdır. Bahçede kaç meyve ağacı vardır?",
         "Bir kütüphanede": f"Bir kütüphanede {tot} kitap vardır. Kitapların {_fr_s(n, d)} kadarı hikâye kitabıdır. Kütüphanede kaç hikâye kitabı vardır?",
         "Bir kantinde": f"Bir kantinde gün boyunca {tot} sandviç hazırlanmıştır. Sandviçlerin {_fr_s(n, d)} kadarı satılmıştır. Kaç sandviç satılmıştır?"}[nm]
    return _mf_raw(subject, "Kesirler", q, o, f"{tot} ÷ {d} = {u}; {u} × {n} = {c}.") if o else None


def _mf_dec_addsub(subject):
    a = random.choice([v for v in range(11, 100) if v % 10]) / 10
    b = random.choice([v for v in range(11, 100) if v % 10]) / 10
    add = random.random() < .5
    if not add and a <= b:
        a, b = b, a + 0.0
        if a == b:
            return None
    c = round(a + b, 1) if add else round(a - b, 1)
    fm = lambda v: f"{v:.1f}".replace(".", ",")
    wr = [round(c + 1, 1), round(c - 1, 1), round(c + .1, 1), round(c * 10, 1) if c * 10 < 300 else round(c + 2, 1), round(abs(a - b) if add else a + b, 1)]
    o = _mf_opts(c, [w for w in wr if w > 0], fm, sort=False)
    nm, nmi = random.choice([("Ali", "Ali’nin"), ("Ayşe", "Ayşe’nin"), ("Deniz", "Deniz’in")])
    if add:
        q = f"{nm} markette {fm(a)} kg elma ve {fm(b)} kg armut aldı. {nm} toplam kaç kg meyve almıştır?"
        ex = f"{fm(a)} + {fm(b)} = {fm(c)}."
    else:
        q = f"{nmi} {fm(a)} metre uzunluğunda bir ipi vardır. {fm(b)} metresini kullanırsa geriye kaç metre ip kalır?"
        ex = f"{fm(a)} − {fm(b)} = {fm(c)}."
    return _mf_raw(subject, "Ondalık Gösterim", q, o, ex) if o and len(set(o[0])) == 4 else None


def _mf_dec_conv(subject):
    kind = random.choice(["dec2fr", "fr2dec", "yuzde"])
    if kind == "dec2fr":
        n = random.choice([1, 3, 7, 9, 11, 13, 17, 19, 21, 23, 27, 31, 37, 39, 41, 43, 47, 49])
        c = f"{n}/100"
        wr = [f"{n}/10", f"{n}/1000", f"{100 - n}/100", f"{n * 10}/100"]
        o = _mf_opts(c, wr, str, sort=False)
        return _mf_raw(subject, "Ondalık Gösterim", f"0,{n:02d} ondalık gösteriminin kesir karşılığı aşağıdakilerden hangisidir?", o, f"Yüzde birler basamağında son rakam var: 0,{n:02d} = {n}/100.") if o else None
    if kind == "fr2dec":
        n = random.choice([1, 2, 3, 4, 6, 7, 8, 9])
        c = f"{n / 10:.1f}".replace(".", ",")
        wr = [f"0,0{n}", f"{n},0", f"{n * 10},0", f"0,{n}0{n}".replace(f"0,{n}0{n}", f"{n / 100 + 0.1:.2f}".replace(".", ","))]
        o = _mf_opts(c, wr, str, sort=False)
        return _mf_raw(subject, "Ondalık Gösterim", f"{n}/10 kesri aşağıdaki ondalık gösterimlerden hangisine eşittir?", o, f"Paydası 10 olan kesir: {n}/10 = {c}.") if o and len(set(o[0])) == 4 else None
    p = random.choice([10, 20, 25, 30, 40, 50, 60, 70, 75, 80])
    c = f"{p / 100:.2f}".replace(".", ",")
    wr = [f"{p / 10:.1f}".replace(".", ","), f"{p / 1000:.3f}".replace(".", ","), f"{p}", f"{(100 - p) / 100:.2f}".replace(".", ",")]
    o = _mf_opts(c, wr, str, sort=False)
    return _mf_raw(subject, "Yüzdeler", f"%{p} yüzdesi hangi ondalık gösterime eşittir?", o, f"%{p} = {p}/100 = {c}.") if o and len(set(o[0])) == 4 else None


def _mf_eqlty(subject):
    kind = random.choice(["unk", "bal"])
    if kind == "unk":
        a, x, b = random.randint(2, 9), random.randint(3, 15), random.randint(3, 30)
        tot = a * x + b
        o = _mf_opts(x, [w for w in [x + 1, x - 1, tot - b, tot, x + 2] if w > 0], str)
        return _mf_raw(subject, "Cebirsel İfadeler", f"Bir sayının {a} katının {b} fazlası {tot} ise bu sayı kaçtır?", o, f"{a}n + {b} = {tot}; {a}n = {tot - b}; n = {x}.") if o else None
    w, m = random.randint(3, 20), random.randint(2, 9)
    r = w + m
    o = _mf_opts(w, [v for v in [r, m, w + 1, w - 1, r + m] if v > 0], str)
    return _mf_raw(subject, "Eşitlik", f"Eşit kollu bir terazinin sol kefesinde bir paket ile {m} g’lık bir kütle, sağ kefesinde {r} g’lık bir kütle vardır. Terazi dengede olduğuna göre paket kaç g’dır?", o, f"Paket + {m} = {r} → paket = {r} − {m} = {w}.") if o else None


_FR_K = ("kesir",)
_MF_GENS += [(_mf_fr_addsub, _FR_K, (5,)), (_mf_fr_whole, _FR_K, (5,)), (_mf_fr_of, _FR_K, (5,)),
             (_mf_dec_addsub, ("ondalık",), (5,)), (_mf_dec_conv, ("ondalık", "yüzde"), (5,)),
             (_mf_eqlty, ("cebir", "eşitlik", "denklem", "örüntü"), (5,))]




def math_questions(grade_label, n, topics="", seen=(), dl=0):
    """Cevabı kodla hesaplanan Matematik soruları (MEB 'Kazanım Kavrama' tarzı). API kullanmaz, hata içermez."""
    if n <= 0:
        return []
    gl = str(grade_label or "")
    g = int(next((c for c in gl if c.isdigit()), "0"))
    tl = str(topics or "").replace("İ", "i").replace("I", "ı").lower()
    g_key = str(g)
    pool = [(f, kw) for f, kw, gs in _MF_GENS if g in gs]
    if not pool:
        return []
    sel = [f for f, kw in pool if any(_kw_hit(tl, k) for k in kw)] or ([f for f, _ in pool] if not tl else [])
    if not sel:
        return []
    out, stems = [], set(seen)
    rkey = ("gen", "Matematik", g_key)
    byname = {f.__name__: f for f in sel if f.__name__ not in _bad_tpl_set()}
    _want_kz = set(re.findall(r"MAT\.\d\.\d\.\d", str(topics or "")))
    if _want_kz:  # kazanım kodu seçilmişse: başka kazanıma ait (kodu bilinen) kalıplar anahtar sözcükle sızmasın
        _f2 = {k: v for k, v in byname.items() if not _MF_ITEMCODE.get(k) or set(_MF_ITEMCODE[k]) & _want_kz}
        if _f2:
            byname = _f2
    byname = _dl_filter(byname, dl, "Matematik", grade_label, topics)
    _geo_nm = {f.__name__ for f, kw in pool if any(re.search(r"açı|çokgen|çember|geometri|çizim|çevre|alan|dörtgen|üçgen|ışın|inşa", k) for k in kw)}
    for _pass in range(2):  # her kalıptan sınav başına en çok 1 soru (2. tur yalnızca eksik kalırsa)
        for nm in _bal_order(rkey, byname, "Matematik", grade_label, topics, n):
            if len(out) >= n:
                break
            if _pass == 0 and any(x.get("tpl") == nm for x in out):
                continue
            for _t in range(4):
                try:
                    raw = byname[nm]("Matematik")
                    x = _norm_q(raw, "Matematik") if raw else None
                except Exception:
                    x = None
                if x and _pass == 0 and nm in _geo_nm and not x.get("shape"):
                    x = None  # geometri: önce şekilli (görsel) sorular; şekilsizler yalnızca 2. turda (eksik kalırsa)
                if x and not _on_topic(x, topics, "Matematik", grade_label):
                    x = None  # seçilen ünite dışı kalıp: atla
                if x and _stem(x) not in stems:
                    stems.add(_stem(x))
                    x["vfd"] = True
                    x["local"] = True
                    x["tpl"] = nm
                    _recent_mark(rkey, nm)
                    out.append(x)
                    break
        if len(out) >= n:
            break
    return out


# ---------------------------------------------------------------- FEN FABRİKASI (5. sınıf Ay evreleri; kodla hesaplanan)
_PH = ["Yeni ay", "İlk dördün", "Dolunay", "Son dördün"]


def _ff_shift(subject):
    i, k = random.randrange(4), random.randint(1, 3)
    after = random.choice([True, False])
    cor = _PH[(i + k) % 4] if after else _PH[(i - k) % 4]
    wr = [p for p in _PH if p != cor]
    random.shuffle(wr)
    q = f"Ay'ın {_PH[i].lower()} evresinden {k} hafta {'sonra' if after else 'önce'} gözlemlenen evre aşağıdakilerden hangisidir?"
    ex = f"Ay'ın ana evreleri sırasıyla Yeni ay, İlk dördün, Dolunay, Son dördün biçimindedir ve her biri yaklaşık 1 hafta arayla gözlenir."
    return _mf_raw(subject, "Ay'ın evreleri", q, ([cor] + wr, cor), ex)


def _ff_seq(subject):
    import itertools
    i = random.randrange(4)
    seq = [_PH[(i + j) % 4] for j in range(1, 4)]
    perms = [list(p) for p in itertools.permutations(seq) if list(p) != seq]
    rev = [_PH[(i - j) % 4] for j in range(1, 4)]
    wr = [p for p in perms if p != rev][:2] + [rev]
    random.shuffle(wr)
    f = lambda L: " – ".join(L)
    names = ["Cenk", "Elif", "Mert", "Ayşe", "Deniz"]
    q = f"{random.choice(names)}, fen projesi için Ay'ı her hafta gözlemleyerek defterine kaydedecektir. İlk kayıt {_PH[i].lower()} evresi olduğuna göre sonraki üç kayıt aşağıdakilerden hangisinde doğru sıralanmıştır?"
    return _mf_raw(subject, "Ay'ın evreleri", q, ([f(seq)] + [f(w) for w in wr], f(seq)), f"Evre sırası: {f([_PH[(i + j) % 4] for j in range(0, 4)])}…")


def _ff_quarter(subject):
    i = random.choice([0, 2])
    cor = _PH[(i + 1) % 4]
    wr = [p for p in _PH if p != cor]
    random.shuffle(wr)
    q = f"Ay'ın {_PH[i].lower()} evresinden çeyrek tur (yaklaşık 1 hafta) sonra gerçekleşen evre aşağıdakilerden hangisidir?"
    return _mf_raw(subject, "Ay'ın evreleri", q, ([cor] + wr, cor), f"{_PH[i]} evresinden sonra {cor.lower()} evresi gelir.")


def _ff_props(subject):
    P = {"Yeni ay": ["Ay, Dünya ile Güneş'in arasındadır.", "Ay Dünya'dan görülemez."],
         "Dolunay": ["Dünya'dan bakıldığında Ay'ın tamamı aydınlık görünür.", "Dünya'dan görülen aydınlık yüzey en fazladır."],
         "İlk dördün": ["Yeni ay evresinden çeyrek tur sonra gözlenir.", "Dünya'dan Ay'ın yarısı aydınlık görünür."],
         "Son dördün": ["Dolunay evresinden çeyrek tur sonra gözlenir.", "Dünya'dan Ay'ın yarısı aydınlık görünür."]}
    ph = random.choice(["Yeni ay", "Dolunay"])
    st = random.choice(P[ph])
    cor = ph
    wr = [p for p in ["Yeni ay", "Dolunay", "İlk dördün", "Son dördün"] if p != ph]
    random.shuffle(wr)
    q = f"“{st}” bilgisi Ay'ın hangi evresine aittir?"
    return _mf_raw(subject, "Ay'ın evreleri", q, ([cor] + wr, cor), f"{st} → {ph.lower()} evresi.")


def _ff_weight(subject):
    m = random.choice([6, 12, 18, 24, 30, 36, 42, 48, 60])
    wd, wa = m * 10, m * 10 // 6
    wr = [(m * 10, m * 10), (m, m // 6), (wa, wd), (m * 10, m), (wd, wa + 10)]
    wr = [w for w in wr if w != (wd, wa)]
    f = lambda p: f"Dünya'da {p[0]} N, Ay'da {p[1]} N"
    random.shuffle(wr)
    q = (f"Bir kutunun kütlesi Dünya ve Ay'da ayrı ayrı ölçülüyor. Dünya 1 kg'lık kütleye 10 N'luk çekim kuvveti uygular; Ay'da bu kuvvet Dünya'dakinin 1/6'sı kadardır.\n"
         f"Kütlesi {m} kg olan kutunun ağırlığı Dünya'da ve Ay'da ayrı ayrı dinamometreyle ölçüldüğünde okunan değerler aşağıdakilerden hangisinde doğru verilmiştir?")
    return _mf_raw(subject, "Kuvvet ve ağırlık", q, ([f((wd, wa))] + [f(w) for w in wr[:3]], f((wd, wa))), f"Dünya'da {m}×10 = {wd} N; Ay'da {wd} ÷ 6 = {wa} N. (Kütle her yerde aynıdır.)")


def _ff_spring(subject):
    k = random.choice([2, 3, 4, 5])
    f1 = random.choice([2, 4, 5])
    f2 = f1 * random.choice([2, 3, 4])
    x1, x2 = f1 * k, f2 * k
    wr = [x1 + f2 - f1, f2 + k, x1 * 2 if x1 * 2 != x2 else x2 + k, x2 + 2 * k]
    q = f"Bir yaya {f1} N'luk bir cisim asıldığında yay {x1} cm uzamaktadır.\nAynı yaya {f2} N'luk bir cisim asılırsa yay kaç cm uzar? (Yay esnekliğini yitirmemektedir.)"
    o = _mf_opts(x2, wr, lambda v: f"{v} cm")
    return _mf_raw(subject, "Kuvvetin ölçülmesi", q, o, f"{f1} N için {x1} cm uzuyorsa 1 N için {k} cm; {f2} N için {f2}×{k} = {x2} cm.") if o else None


_FF_GENS = [(_ff_shift, ("ay", "evre")), (_ff_seq, ("ay", "evre")), (_ff_quarter, ("ay", "evre")), (_ff_props, ("ay", "evre")),
            (_ff_weight, ("kuvvet", "ağırlık", "dinamometre")), (_ff_spring, ("kuvvet", "dinamometre", "ölçül"))]


def _ff_food(subject):
    chains = [("ot", "çekirge", "kurbağa", "yılan"), ("bitki", "tırtıl", "serçe", "şahin"), ("fitoplankton", "zooplankton", "küçük balık", "büyük balık"),
              ("ot", "fare", "yılan", "şahin"), ("yosun", "karides", "balık", "pelikan"), ("havuç", "tavşan", "tilki")]
    ch = random.choice(chains)
    chain = " → ".join(ch)
    mode = random.choice(["pred", "prey", "count"])
    lead = f"Bir ekosistemde canlılar arasındaki besin ilişkisi aşağıdaki besin zinciriyle gösterilmiştir (ok yönü, yenen canlıdan yiyen canlıya doğrudur).\n{chain}"
    if mode == "count":
        k = len(ch) - 1
        o = _mf_opts(k, [k - 1, k + 1, k + 2], lambda v: f"{v}")
        q = "Bu besin zincirinde kaç tane tüketici canlı vardır? (Üretici, tüketici sayılmaz.)"
        return _mf_raw(subject, "Besin zinciri", q, o, f"Zincirde {len(ch)} canlı vardır; ilki ({ch[0]}) üreticidir, geri kalan {k} canlı tüketicidir.", passage=lead) if o else None
    if mode == "pred":
        last, prev = ch[-1], ch[-2]
        q = f"Bu ekosistemde {last} sayısı kısa sürede çok azalırsa, diğer koşullar aynı kalmak şartıyla {prev} sayısı için ne söylenebilir?"
        opts = (["Artar", "Azalır", "Değişmez", "Tamamen yok olur"], "Artar")
        ex = f"{last}, {prev} ile beslenir. {last} azalınca {prev} daha az yenir ve sayısı başlangıçta artar."
    else:
        prey, nxt = ch[1], ch[2]
        q = f"Bu ekosistemde {prey} sayısı kısa sürede çok azalırsa, diğer koşullar aynı kalmak şartıyla {nxt} sayısı için ne söylenebilir?"
        opts = (["Azalır", "Artar", "Değişmez", "Hiç etkilenmez, çünkü doğrudan üreticiyle beslenir"], "Azalır")
        ex = f"{nxt}, {prey} ile beslenir. {prey} azalınca besini azalacağından {nxt} sayısı azalır."
    return _mf_raw(subject, "Besin zinciri", q, opts, ex, passage=lead)


def _ff_boil(subject):
    step = random.choice([10, 20])
    t0 = random.choice([x for x in range(20, 60, 10) if (100 - x) % step == 0])
    temps, t = [], t0
    while t < 100:
        temps.append(t)
        t += step
    first = len(temps)
    temps += [100] * random.choice([3, 4])
    rows = [[str(i), f"{v}"] for i, v in enumerate(temps)]
    shape = {"type": "table", "title": "Saf suyun ısıtılması", "headers": ["Süre (dk)", "Sıcaklık (°C)"], "rows": rows}
    lead = "Saf su bir ısıtıcı üzerinde sabit ısı verilerek ısıtılıyor ve her dakika sonunda sıcaklığı ölçülüp tabloya yazılıyor."
    if random.random() < .5:
        q = "Tablodaki verilere göre su kaçıncı dakikada kaynamaya başlamıştır? (Su kaynarken sıcaklığı sabit kalır.)"
        o = _mf_opts(first, [first - 1, first + 1, first + 2, len(temps) - 1], lambda v: f"{v}. dakika")
        ex = f"Sıcaklık {first}. dakikada 100 °C'ye ulaşmış ve sonra değişmemiştir; kaynama bu dakikada başlamıştır."
    else:
        k = len(temps) - 1 - first
        q = "Tablodaki verilere göre su kaynamaya başladıktan sonra ısıtma kaç dakika daha sürmüştür?"
        o = _mf_opts(k, [k - 1, k + 1, first], lambda v: f"{v} dakika")
        ex = f"Su {first}. dakikada kaynamaya başlamış, ölçüm {len(temps) - 1}. dakikaya kadar sürmüştür: {len(temps) - 1} − {first} = {k} dakika."
    return _mf_raw(subject, "Kaynama", q, o, ex, shape=shape, passage=lead) if o else None


def _ff_fric(subject):
    surf = random.sample([("cam", 2), ("sırlı fayans", 3), ("ahşap parke", 5), ("halı", 9), ("zımpara", 14), ("çim", 11)], 4)
    d = sorted(surf, key=lambda x: x[1])
    mn, mx = d[0], d[-1]
    diff = mx[1] - mn[1]
    rows = [[n, str(v)] for n, v in surf]
    shape = {"type": "table", "title": "Sabit hızla çekme kuvveti", "headers": ["Yüzey", "Dinamometre (N)"], "rows": rows}
    lead = ("Aynı tuğla farklı yüzeylerde dinamometreyle yatay doğrultuda sabit hızla çekiliyor. Sabit hızla çekilirken dinamometrenin gösterdiği değer, "
            "tuğlaya etki eden sürtünme kuvvetine eşittir.")
    q = "Tabloya göre sürtünme kuvvetinin en büyük olduğu yüzey ile en küçük olduğu yüzeydeki sürtünme kuvvetleri arasındaki fark kaç N'dur?"
    o = _mf_opts(diff, [diff + 2, diff - 2 if diff > 2 else diff + 4, mx[1], mx[1] + mn[1]], lambda v: f"{v} N")
    return _mf_raw(subject, "Sürtünme kuvveti", q, o, f"En büyük {mx[1]} N ({mx[0]}), en küçük {mn[1]} N ({mn[0]}): {mx[1]} − {mn[1]} = {diff} N.", shape=shape, passage=lead) if o else None


def _ff_shadow(subject):
    h = random.choice([10, 12, 15])
    ds = random.sample([20, 30, 40, 50, 60, 80], 4)
    ds.sort()
    sh = [h * 100 // d // 1 for d in ds]
    sh = [round(h * 100 / d) for d in ds]
    if len(set(sh)) < 4:
        return None
    rows = [[str(d), str(s)] for d, s in zip(ds, sh)]
    shape = {"type": "table", "title": "Gölge boyunun değişimi", "headers": ["Cismin ışık kaynağına uzaklığı (cm)", "Gölge boyu (cm)"], "rows": rows}
    lead = "Işık kaynağı sabit tutulup ışığı geçirmeyen bir cisim kaynağa farklı uzaklıklara konuyor ve perdedeki gölgenin boyu ölçülüyor."
    q = "Tablodaki verilere göre aşağıdaki yargılardan hangisi doğrudur?"
    o = (["Cisim ışık kaynağından uzaklaştıkça gölge boyu küçülür.", "Cisim ışık kaynağından uzaklaştıkça gölge boyu büyür.",
          "Gölge boyu cismin uzaklığından etkilenmez.", "Gölge boyu cismin uzaklığıyla önce artar sonra azalır."],
         "Cisim ışık kaynağından uzaklaştıkça gölge boyu küçülür.")
    return _mf_raw(subject, "Gölge", q, o, f"Uzaklık {ds[0]} cm iken gölge {sh[0]} cm, {ds[-1]} cm iken {sh[-1]} cm'dir; uzaklaştıkça gölge küçülmektedir.", shape=shape, passage=lead)


_FF_GENS += [(_ff_food, ("besin", "ekosistem", "zincir", "çevre", "biyoçeşit")), (_ff_boil, ("ısı", "sıcaklık", "kaynama", "erime", "madde", "değişim")),
             (_ff_fric, ("sürtünme", "kuvvet")), (_ff_shadow, ("gölge", "ışık"))]


# ---------------------------------------------------------------- 5. SINIF FEN: YENİ NESİL (beceri temelli) KALIPLAR
# Deney senaryosu + tablo + çıkarım/değişken/yorum. Metinde geçen her değer tabloda yazılıdır; cevap tablodan kodla hesaplanır.
def _yn_opts(correct, wrongs, ex_unused=None):
    o = _mf_opts(correct, wrongs, str, sort=False)
    if not o:
        return None
    ol, cor = o
    random.shuffle(ol)
    return ol, cor


def _ff_yn_yay(subject):
    k = random.choice([2, 3, 4, 5])
    ms = [50, 100, 150, 200]
    rows = [[str(m), str(k * m // 50)] for m in ms]
    shape = {"type": "table", "title": "Yaya asılan kütle ve yayın uzaması", "headers": ["Asılan kütle (g)", "Yayın uzaması (cm)"], "rows": rows}
    lead = "Ece, aynı yaya farklı kütleler asarak yayın uzamasını ölçüyor. Yay, bu kütlelerde esnekliğini yitirmemiştir. Ölçüm sonuçları tabloda verilmiştir."
    if random.random() < 0.5:
        q = "Tablodaki verilere göre aşağıdaki çıkarımlardan hangisi yapılabilir?"
        c = "Yaya asılan kütle arttıkça yayın uzaması artar."
        o = _yn_opts(c, ["Yaya asılan kütle arttıkça yayın uzaması azalır.", "Yayın uzaması asılan kütleden bağımsızdır.", "Yaya asılan kütle iki katına çıkınca yayın uzaması yarıya iner."])
        ex = f"Kütle 50 g’dan 200 g’a çıktıkça uzama {rows[0][1]} cm’den {rows[-1][1]} cm’ye çıkmıştır; kütle arttıkça uzama artar."
        return _mf_raw(subject, "Kuvvetin ölçülmesi", q, o, ex, shape=shape, passage=lead) if o else None
    m = random.choice([250, 300])
    v = k * m // 50
    q = f"Tablodaki değişim aynı şekilde sürdüğüne göre yaya {m} g’lık bir kütle asılırsa yayın uzaması kaç cm olur?"
    o = _mf_opts(v, [v + k, v - k, v + 2 * k, k * 4], lambda x: f"{x} cm")
    ex = f"Her 50 g için uzama {k} cm artmaktadır. {m} g için {m // 50} × {k} = {v} cm olur."
    return _mf_raw(subject, "Kuvvetin ölçülmesi", q, o, ex, shape=shape, passage=lead) if o else None


def _ff_yn_stop(subject):
    surf = random.sample([("cam", 5), ("sırlı fayans", 6), ("ahşap parke", 9), ("halı", 17), ("kum", 24), ("çim", 20), ("zımpara", 30)], 4)
