def din_questions(grade_label, n, topics="", seen=(), dl=0):
    """5. sınıf Din Kültürü: kodla kurulan, cevabı kesin sorular."""
    gl = str(grade_label or "")
    if n <= 0 or "5" not in gl[:2]:
        return []
    tl = str(topics or "").replace("İ", "i").replace("I", "ı").lower()
    sel = [f for f, kw in _DF_GENS if any(_kw_hit(tl, k) for k in kw)]
    if not sel:
        return []
    out, stems = [], set(seen)
    rkey = ("gen", "Din", "5")
    byname = {f.__name__: f for f in sel if f.__name__ not in _bad_tpl_set()}
    byname = _item_scope(byname, "Din Kültürü ve Ahlak Bilgisi", grade_label, topics)
    byname = _dl_filter(byname, dl, "Din Kültürü ve Ahlak Bilgisi", grade_label, topics)
    for nm in _bal_order(rkey, byname, "Din Kültürü ve Ahlak Bilgisi", grade_label, topics, n):
        if len(out) >= n:
            break
        for _t in range(4):
            try:
                raw = byname[nm](_DIN)
                x = _norm_q(raw, _DIN) if raw else None
            except Exception:
                x = None
            if x and _stem(x) not in stems:
                stems.add(_stem(x))
                x["vfd"] = True
                x["local"] = True
                x["tpl"] = nm
                _recent_mark(rkey, nm)
                out.append(x)
                break
    return out


