def _ff_cd_tab_ad(subject):
    ks = random.sample(["amip", "paramesyum", "öglena"], 3)
    lb = random.sample(_CD_L, 3)
    rows = [[lb[i], _CD_OZ[ks[i]], "Hayır"] for i in range(3)]
