    sh = {"type": "bio", "sub_type": "groups", "boxes": [{"title": b["title"], "items": b["items"]} for b in boxes], "per_row": 3}
    o = _yn_opts(_CD_GAD[gs[i]], [v for k, v in _CD_GAD.items() if k != gs[i]])
