    sh = {"type": "mad", "sub_type": "yon", "a": {"t": ta, "label": lb[0]}, "b": {"t": tb, "label": lb[1]}}
    hot, cold = (lb[0], lb[1]) if ta > tb else (lb[1], lb[0])
