# ---------------------------------------------------------------- ÖNCEDEN ÜRETİLMİŞ + DOĞRULANMIŞ HAVUZ (repodaki pool/ klasörü; API kotası harcamaz)
_POOL_CACHE = {}


def _pool_slug(t):
    t = str(t or "").replace("İ", "i").replace("I", "ı").lower()
    for a, b in zip("ıöüşçğ", "iouscg"):
        t = t.replace(a, b)
    return re.sub(r"[^a-z0-9]+", "_", t).strip("_")


def _pool_path(subject, grade_label):
    gl = str(grade_label or "")
    gd = "8" if "LGS" in gl.upper() else (next((c for c in gl if c.isdigit()), "x"))  # LGS = 8. sınıf havuzu
    root = os.environ.get("DENEMEMATIK_POOL_DIR")
    if not root:
        from . import store
        root = os.path.join(os.path.dirname(store.DATA), "pool")
    return os.path.join(root, gd, _pool_slug(subject) + ".json")


def _pool_tok(t):
    t = str(t or "").replace("İ", "i").replace("I", "ı").lower().replace("’", "").replace("'", "")  # Kur'an / Kur’an aynı sözcük
    return {w[:5] for w in re.findall(r"[a-zçğıöşü]{4,}", t)}


def _pool_read(path):
    try:
        mt = os.path.getmtime(path)
    except Exception:
        return []
    c = _POOL_CACHE.get(path)
    if c and c[0] == mt:
        return c[1]
    try:
        with open(path, encoding="utf-8") as f:
            qs = (json.load(f) or {}).get("qs", [])
    except Exception:
        qs = []
    _POOL_CACHE[path] = (mt, qs)
    return qs


def _pool_shard_name(unit):
    import hashlib
    u = str(unit or "")
    return (_pool_slug(u) or "x")[:60] + "_" + hashlib.md5(u.encode("utf-8")).hexdigest()[:4] + ".json"


def _pool_load(path, sel_u=None, subject="", grade_label=""):
    """Havuzu okur. <ders>/ klasörü varsa ünite parçalarından (yalnızca seçilen ünite/tema parçaları) yükler; yoksa eski tek dosya."""
    d = path[:-5] if path.endswith(".json") else path
    ip = os.path.join(d, "_index.json")
    if not os.path.isfile(ip):
        return _pool_read(path)
    idx = _pool_read_obj(ip)
    files = idx.get("units") or {}
    if sel_u is None:
        pick = list(files)
    else:
        pick = [f for f, u in files.items() if u in sel_u]
        if subject == "Matematik":
            try:
                from . import curriculum as _cu
                g = next((c for c in str(grade_label) if c.isdigit()), "")
                units = _cu.units(g, "Matematik")
                for f, kzs in (idx.get("kz") or {}).items():
                    if f in pick:
                        continue
                    th = {n for n, ks in units if any(str(k).startswith(c + ".") for k in ks for c in kzs)}
                    if th & set(sel_u):
                        pick.append(f)
            except Exception:
                pass
    out = []
    for f in pick:
        out.extend(_pool_read(os.path.join(d, f)))
    # bellek: en çok 14 parça önbellekte kalsın
    keys = [k for k in _POOL_CACHE if k.startswith(d + os.sep) and not k.endswith("_index.json")]
    for k in keys[:-14]:
        _POOL_CACHE.pop(k, None)
    return out


def _pool_read_obj(path):
    try:
        mt = os.path.getmtime(path)
    except Exception:
        return {}
    c = _POOL_CACHE.get(path)
    if c and c[0] == mt:
        return c[1]
    try:
        with open(path, encoding="utf-8") as f:
            o = json.load(f) or {}
    except Exception:
        o = {}
    _POOL_CACHE[path] = (mt, o)
    return o


STYLE_EXAMPLES = {}  # gece betiği doldurur: {ders: [beğenilen soru sözlükleri]}


def _style_block(subject, grade_label):
    """Beğenilen sorulardan en çok 2 örnek (yalnızca tarz/kalite örneği; kopyalama yasak)."""
    ex = list(STYLE_EXAMPLES.get(subject, []))
    if not ex:
        try:
            from . import store
            ex = [x.get("q") for x in store.liked() if (x.get("q") or {}).get("subject") == subject and x.get("grade_label") == grade_label]
        except Exception:
            ex = []
    ex = [q for q in ex if isinstance(q, dict) and isinstance(q.get("options"), dict) and q.get("question") and not q.get("shape")]
    if not ex:
        return ""
    random.shuffle(ex)
    lines = []
    for q in ex[:2]:
        o = " ".join(f"{k}) {v}" for k, v in q["options"].items())
        ps = f"Metin: {str(q.get('passage'))[:400]}\n" if q.get("passage") else ""
        lines.append(f"{ps}Soru: {q['question']}\n{o}\nDoğru: {q.get('answer')}")
    return ("\n👍 BEĞENİLEN ÖRNEKLER (yalnızca TARZ ve KALİTE örneğidir: bu soruları ya da konularını KOPYALAMA; farklı bağlam ve içerikle aynı titizlikte, aynı netlikte yaz):\n"
            + "\n---\n".join(lines))


def src_facts(subject, grade_label, topics="", limit=30):
    """sources/<sınıf>/<ders>.json içindeki onaylı bilgi kartlarından, konuya uyan ünitelerin bilgilerini döndürür."""
    try:
        gl = str(grade_label or "")
        gd = "8" if "LGS" in gl.upper() else (next((c for c in gl if c.isdigit()), "x"))  # LGS = 8. sınıf havuzu
        root = os.environ.get("DENEMEMATIK_SRC_DIR")
        if not root:
            from . import store
            root = os.path.join(os.path.dirname(store.DATA), "sources")
        path = os.path.join(root, gd, _pool_slug(subject) + ".json")
        c = _POOL_CACHE.get(path)
        mt = os.path.getmtime(path)
        if c and c[0] == mt:
            units = c[1]
        else:
            with open(path, encoding="utf-8") as f:
                units = (json.load(f) or {}).get("units", {})
            _POOL_CACHE[path] = (mt, units)
        want = _pool_tok(topics)
        out = []
        for un, facts in units.items():
            if not want or (want & _pool_tok(un)):
                out += list(facts)
        return out[:limit]
    except Exception:
        return []


def _src_block(subject, grade_label, topics):
    f = src_facts(subject, grade_label, topics)
    if not f:
        return ""
    return ("\n📚 KAYNAK BİLGİLER (MEB programına uygun, doğrulanmış). Sorular YALNIZCA bu bilgilere ve bunlarla çelişmeyen temel genel bilgiye dayansın; "
            "bu bilgilerle ÇELİŞEN ya da kaynakta olmayan ayrıntı, isim, tarih, sayı UYDURMA. Doğru şık mutlaka bu bilgilerle desteklensin:\n- " + "\n- ".join(f))


# ---------------------------------------------------------------- MATEMATİK ŞABLONLARI: model hikâyeyi yazar, KOD sayıları ve cevabı hesaplar
def _tpl_eval(expr, env):
    """Güvenli ifade değerlendirici: yalnızca sayı, değişken, + - * / // % **, karşılaştırma, and/or/not ve min/max/abs/round/gcd/lcm/int."""
    import ast as _ast
    import math as _m
    import operator as _op
    ex = str(expr).strip()
    if not ex or len(ex) > 200:
        raise ValueError("ifade")
    ops = {_ast.Add: _op.add, _ast.Sub: _op.sub, _ast.Mult: _op.mul, _ast.Div: _op.truediv, _ast.FloorDiv: _op.floordiv, _ast.Mod: _op.mod, _ast.Pow: _op.pow}
    cmps = {_ast.Lt: _op.lt, _ast.LtE: _op.le, _ast.Gt: _op.gt, _ast.GtE: _op.ge, _ast.Eq: _op.eq, _ast.NotEq: _op.ne}
    fns = {"min": min, "max": max, "abs": abs, "round": round, "int": int, "gcd": _m.gcd, "lcm": lambda a, b: a * b // _m.gcd(a, b) if a and b else 0}

    def ev(n):
        if isinstance(n, _ast.Expression):
            return ev(n.body)
        if isinstance(n, _ast.Constant) and isinstance(n.value, (int, float)) and not isinstance(n.value, bool):
            return n.value
        if isinstance(n, _ast.Name) and n.id in env:
            return env[n.id]
        if isinstance(n, _ast.BinOp) and type(n.op) in ops:
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, _ast.Pow) and (abs(b) > 6 or abs(a) > 1000):
                raise ValueError("üs")
            return ops[type(n.op)](a, b)
        if isinstance(n, _ast.UnaryOp) and isinstance(n.op, (_ast.USub, _ast.UAdd, _ast.Not)):
            v = ev(n.operand)
            return -v if isinstance(n.op, _ast.USub) else (v if isinstance(n.op, _ast.UAdd) else (not v))
        if isinstance(n, _ast.Compare) and all(type(o) in cmps for o in n.ops):
            left, ok = ev(n.left), True
            for o, c in zip(n.ops, n.comparators):
                right = ev(c)
                ok = ok and cmps[type(o)](left, right)
                left = right
            return ok
        if isinstance(n, _ast.BoolOp):
            vals = [ev(v) for v in n.values]
            return all(vals) if isinstance(n.op, _ast.And) else any(vals)
        if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Name) and n.func.id in fns and not n.keywords and len(n.args) <= 4:
            return fns[n.func.id](*[ev(a) for a in n.args])
        raise ValueError("izin verilmeyen ifade")
    return ev(_ast.parse(ex, mode="eval"))


def _tpl_fmt(v):
    if abs(v - round(v)) < 1e-9:
        return f"{int(round(v)):d}"
    return f"{round(v, 2):g}".replace(".", ",")


def tpl_instantiate(t, tries=200):
    """Şablondan bir soru örneği (ham sözlük) üretir; kural/şık koşulları sağlanmazsa None."""
    try:
        for _ in range(tries):
            env = {}
            for name, spec in (t.get("vars") or {}).items():
                if isinstance(spec, dict) and spec.get("choices"):
                    env[name] = random.choice(spec["choices"])
                elif isinstance(spec, dict) and "lo" in spec and "hi" in spec:
                    st_ = int(spec.get("step", 1) or 1)
                    env[name] = random.randrange(int(spec["lo"]), int(spec["hi"]) + 1, st_)
                else:
                    return None
            for name, ex in (t.get("derived") or {}).items():
                env[name] = _tpl_eval(ex, env)
            if not all(bool(_tpl_eval(c, env)) for c in (t.get("constraints") or [])):
                continue
            ans = float(_tpl_eval(t["answer"], env))
            wrong = [float(_tpl_eval(w, env)) for w in (t.get("wrong") or [])]
            allv = [ans] + wrong
            if len(allv) != 4 or any(abs(v) > 1e7 for v in allv):
                return None
            if any(abs(v * 100 - round(v * 100)) > 1e-6 for v in allv):
                continue  # en çok 2 ondalık
            if len({round(v, 6) for v in allv}) != 4:
                continue
            if bool(t.get("positive", True)) and any(v < 0 for v in allv):
                continue
            unit = str(t.get("unit") or "").strip()
            order = sorted(allv)
            opts = {"ABCD"[i]: (f"{_tpl_fmt(v)} {unit}".strip()) for i, v in enumerate(order)}
            right = "ABCD"[order.index(ans)]
            fmtenv = {k: _tpl_fmt(v) for k, v in env.items()}
            fmtenv["ans"] = _tpl_fmt(ans)
            text = str(t["text"]).format_map(fmtenv)
            expl = str(t.get("explanation") or "").format_map(fmtenv)
            return {"subject": "Matematik", "topic": str(t.get("topic") or "Matematik"), "passage": "", "question": text, "options": opts, "answer": right, "explanation": expl}
    except Exception:
        return None
    return None


def tpl_schema_ok(t):
    """Şablonun biçimsel denetimi (modelin yazdığı JSON güvenle kullanılabilir mi?)."""
    try:
        if not isinstance(t, dict) or not str(t.get("text") or "").strip() or not t.get("answer") or len(t.get("wrong") or []) != 3:
            return False
        if not isinstance(t.get("vars"), dict) or not t["vars"] or len(str(t["text"])) > 600:
            return False
        names = set(t["vars"]) | set((t.get("derived") or {}))
        import string as _s
        for _lit, field, _f, _c in _s.Formatter().parse(str(t["text"]) + " " + str(t.get("explanation") or "")):
            if field and field not in names and field != "ans":
                return False
        return True
    except Exception:
        return False


def tpl_questions(grade_label, n, topics="", seen=()):
    """templates/<sınıf>/matematik.json içindeki doğrulanmış şablonlardan, her çağrıda yeni sayılarla soru üretir (API'siz)."""
    if n <= 0 or demo_mode() or os.environ.get("DENEMEMATIK_NO_POOL") == "1":
        return []
    try:
        gl = str(grade_label or "")
        gd = "8" if "LGS" in gl.upper() else (next((c for c in gl if c.isdigit()), "x"))  # LGS = 8. sınıf havuzu
        root = os.environ.get("DENEMEMATIK_TPL_DIR")
        if not root:
            from . import store
            root = os.path.join(os.path.dirname(store.DATA), "templates")
        tps = _pool_read(os.path.join(root, gd, "matematik.json"))
    except Exception:
        return []
    want = _pool_tok(topics)
    sel_u = _selected_units(grade_label, "Matematik", topics)
    if sel_u is not None:
        cand = [t for t in tps if t.get("unit_name") in sel_u]  # yalnızca seçilen ünitenin şablonları
    else:
        cand = [t for t in tps if (not want or (want & _pool_tok(f"{t.get('topic', '')} {t.get('topics', '')}")))]
    if not cand:
        return []
    byid = {str(t.get("id")): t for t in cand}
    out, stems = [], set(seen)
    rkey = ("tpl", gd)
    for tid in _recent_order(rkey, list(byid)):
        if len(out) >= n:
            break
        t = byid[tid]
        for _t in range(3):
            raw = tpl_instantiate(t)
            try:
                x = _norm_q(raw, "Matematik") if raw else None
            except Exception:
                x = None
            if x and _stem(x) not in stems and not _is_bad(_stem(x)):
                stems.add(_stem(x))
                x["vfd"] = True
                x["tpl_id"] = tid
                _recent_mark(rkey, tid)
                out.append(x)
                break
    return out


def _pool_unit_ok(q, sel_u, grade_label, subject, topics=""):
    """Havuz sorusu seçilen ünite/tema (ve varsa seçilen kazanım kodları) içinde mi? Matematikte soru 'kz' kazanım kodlarıyla tema adına bağlanır."""
    kz = [str(x) for x in (q.get("kz") or [])]
    ok = q.get("unit") in sel_u
    if subject == "Matematik" and kz:
        try:
            from . import curriculum as _cu
            g = next((c for c in str(grade_label) if c.isdigit()), "")
            th = {n for n, ks in _cu.units(g, "Matematik") if any(str(k).startswith(c + ".") for k in ks for c in kz)}
            ok = ok or bool(th & set(sel_u))
        except Exception:
            pass
        want = set(re.findall(r"MAT\.\d\.\d\.\d", str(topics or "")))
        if ok and want and not (want & set(kz)):
            return False  # kazanımlar tek tek seçilmiş: soru bu kazanımlardan birine ait olmalı
    return ok


def pool_questions(subject, grade_label, topics="", n=1, seen=(), difficulty="", extra=0):
    """Gece/haftalık çalışan betiğin ürettiği, kural + çapraz model doğrulamasından geçmiş soruları döndürür.
    En az kullanılanlar önce gelir; görülmüş (geçmiş) sorular ve konu dışı sorular atlanır."""
    if n <= 0 or demo_mode() or os.environ.get("DENEMEMATIK_NO_POOL") == "1":
        return []
    sel_u = _selected_units(grade_label, subject, topics)
    qs = _pool_load(_pool_path(subject, grade_label), sel_u, subject, grade_label)
    if not qs:
        return []
    want = _pool_tok(topics)
    store = None
    use = {}
    try:
        from . import store
        use = store._load("pool_use.json", {})
    except Exception:
        pass
    dw = None
    try:
        from . import curriculum as _cu
        dw = _cu.DIFFICULTIES.index(difficulty)
    except Exception:
        pass
    cand = []
    try:
        _btp = set(_bad_tpl_set())
        _off = store.offtopic_pairs() if store else set()
    except Exception:
        _btp, _off = set(), set()
    for q in qs:
        s = _stem(q)
        if not s or s in seen or _is_bad(s):
            continue
        if q.get("fam") and (q["fam"] in _btp or (q["fam"], q.get("unit", "")) in _off):
            continue  # hatalı bildirilen kalıp / bu ünitede konu dışı bildirilen kalıp
        if sel_u is not None:
            if not _pool_unit_ok(q, sel_u, grade_label, subject, topics):
                continue  # havuz sorusu başka ünitenin/kazanımın: KESİN atla
            ov = 1
        else:
            ov = len(want & _pool_tok(f"{q.get('unit', '')} {q.get('topic', '')} {q.get('topics', '')}")) if want else 0
            if want and not ov:
                continue
        far = dw is not None and isinstance(q.get("d"), int) and abs(q["d"] - dw) > 1
        cand.append((far, use.get(s, 0), -ov, random.random(), q))
    cand.sort(key=lambda t: t[:4])
    # aynı kalıptan bir sınava en çok _fcap soru: fazlalar sona itilir (havuz yetmezse yine kullanılır)
    _fcap = max(2, -(-n // 8))
    _fr, _head, _tail = {}, [], []
    for t in cand:
        f = t[4].get("fam") or ""
        _fr[f] = _fr.get(f, 0) + 1
        (_head if (not f or _fr[f] <= _fcap) else _tail).append(t)
    cand = _head + _tail
    out, stems = [], set(seen)
    per_unit = {}
    for far, _u, _o, _r, q in cand:
        if len(out) >= n + extra:
            break
        un = q.get("unit", "")
        if per_unit.get(un, 0) >= max(2, -(-n // 2)):
            continue
        clean = {k: v for k, v in q.items() if k not in ("_sty", "unit", "topics", "d", "ts", "pool", "local", "seed", "vfd", "_gp", "id", "tpl", "pid", "listen")}
        try:
            x = _norm_q(clean, subject)
        except Exception:
            x = None
        if not x or _stem(x) in stems:
            continue
        stems.add(_stem(x))
        x["vfd"] = True
        x["pool"] = True
        if q.get("fam"):
            x["fam"] = q["fam"]  # bildirim/beğeni için kalıp izi (kullanıcıya gösterilmez)
            x["_pu"] = q.get("unit", "")
        if q.get("listen") and len(str(x.get("passage") or "").split()) >= 20:
            x["listen"] = True  # dinleme sorusu: metin ekranda gizlenir, sesli çalınır
        if len(out) < n:  # fazladan istenenler (yedek) kullanım sayacını artırmaz
            use[_stem(q)] = use.get(_stem(q), 0) + 1
        per_unit[un] = per_unit.get(un, 0) + 1
        out.append(x)
    if out and store is not None:
        try:
            store._save("pool_use.json", use)
        except Exception:
            pass
    return out


def _hist_sets(subjects):
    """Önceki sınavlardan soru imzaları -> {ders: [küme]} (yoksa boş)."""
    try:
        from . import store
        sg = store.recent_sigs()
        return {sj: [set(x.split()) for x in (sg.get(sj) or [])] for sj in subjects}
    except Exception:
        return {}


def _style_key(q):
    """Sorunun TARZI: kalıp adı ya da (şekil türü + kök cümlenin son kelimeleri). Aynı tarz arka arkaya gelmesin."""
    try:
        if q.get("tpl"):
            return "t:" + str(q["tpl"])
        if q.get("fam"):
            return "f:" + str(q["fam"])  # havuz sorusu: kalıp adı (aynı kalıptan çok soru aynı sınava girmesin)
        qq = str(q.get("question", "")).replace("İ", "i").replace("I", "ı").lower()
        qq = re.sub(r"\d+", "0", qq)
        w = re.findall(r"[a-zçğıöşü]{3,}", qq)[-4:]
        sh = q.get("shape")
        st_ = str(sh.get("type", "")) if isinstance(sh, dict) else ""
        return f"s:{st_}|" + " ".join(x[:6] for x in w)
    except Exception:
        return ""


def _hist_parts(q):
    t = (str(q.get("question", "")) + " " + str(q.get("passage", ""))).replace("İ", "i").replace("I", "ı").lower()
    w = {x[:5] for x in re.findall(r"[a-zçğıöşü]{4,}", t)}
    n = set()
    if q.get("tpl"):
        from . import store as _st
        n = set(_st._num_tokens(q))
        try:
            at = str((q.get("options") or {}).get(q.get("answer"), "")).replace("İ", "i").replace("I", "ı").lower()
            w |= {"@" + x[:5] for x in re.findall(r"[a-zçğıöşü]{4,}", at)}
        except Exception:
            pass
    return w, n


def _hist_sim1(w, n, h):
    """Tek geçmiş soruyla benzerlik: sözcük Jaccard'ı; ikisi de hazır kalıpsa ve sayıları farklıysa düşürülür (aynı kök, başka sayılar = başka soru)."""
    hw = {x for x in h if not x.startswith("#")}
    hn = {x for x in h if x.startswith("#")}
    if not hw:
        return 0.0
    s = len(w & hw) / len(w | hw)
    if n and hn:
        ov = len(n & hn) / len(n | hn)
        s *= (0.4 + 0.6 * ov)
    return s


def _hist_maxsim(q, sets):
    """Soru, geçmiş sınav sorularına en çok ne kadar benziyor (0-1)? Yedek sıralamasında en az benzeyen önce gelir."""
    try:
        w, n = _hist_parts(q)
        if not w or not sets:
            return 0.0
        return max((_hist_sim1(w, n, h) for h in sets if h), default=0.0)
    except Exception:
        return 0.0


# ---------------------------------------------------------------- KAZANIM/ALT KONU DAĞILIMI (tek konuya yığılmayı önler)
_TI_CACHE = {}


def _topic_items(subject, grade_label, topics):
    """Seçilen kapsamdaki alt konular/kazanımlar (müfredattaki ünite maddeleri, metinde aynen geçenler). 2'den azsa dağıtım yapılmaz."""
    try:
        from . import curriculum as _cu
        g = next((c for c in str(grade_label) if c.isdigit()), "")
        txt = str(topics or "")
        out = []
        for _u, items in _cu.units(g, subject):
            out += [it for it in items if it and it in txt]
        out = list(dict.fromkeys(out))
        return out if len(out) >= 2 else []
    except Exception:
        return []


def _pw(text):
    t = str(text).replace("İ", "i").replace("I", "ı").lower()
    return {x[:5] for x in re.findall(r"[a-zçğıöşü]{4,}", t)}


def _item_weights(items):
    key = tuple(items)
    r = _TI_CACHE.get(key)
    if r is None:
        sets = [_pw(it) for it in items]
        from collections import Counter as _C
        df = _C(w for s in sets for w in s)
        r = [{w: 1.0 / df[w] for w in s} for s in sets]
        _TI_CACHE[key] = r
    return r


def _text_item(text, items, minscore=0.9):
    """Metin hangi alt konuya/kazanıma en yakın? (-1: belirsiz)"""
    if not items:
        return -1
    W = _pw(text)
    sc = [sum(w for k, w in d.items() if k in W) for d in _item_weights(items)]
    b = max(range(len(sc)), key=lambda i: sc[i])
    return b if sc[b] >= minscore else -1


def _q_item(q, items):
    return _text_item(f"{q.get('topic', '')} {q.get('question', '')} {q.get('passage', '')} {q.get('explanation', '')}", items)


