def _mf_eqlty2(subject):
    kind = random.choice(["dag", "koru", "tersi", "degis"])
    if kind == "dag":
        a, b, c = random.randint(2, 9), random.randint(2, 9), random.randint(2, 9)
        o = _mf_opts(b + c, [b * c, a + b + c, b + c + a * 2, abs(b - c) or b + c + 3], str)
        return _mf_raw(subject, "İşlem Özellikleri", f"{a} × {b} + {a} × {c} = {a} × □ eşitliğinde □ yerine hangi sayı yazılmalıdır?", o, f"Çarpmanın toplama üzerine dağılma özelliği: {a} × {b} + {a} × {c} = {a} × ({b} + {c}) = {a} × {b + c}.") if o else None
    if kind == "koru":
        x, b, k = random.randint(3, 20), random.randint(2, 15), random.randint(2, 9)
        tot = x + b
        o = _mf_opts(tot + k, [tot, tot - k, tot + 2 * k, x + k], str)
        return _mf_raw(subject, "Eşitliğin Korunumu", f"x + {b} = {tot} eşitliğinin her iki tarafına {k} eklenirse sol ve sağ tarafın ortak değeri kaç olur?", o, f"Eşitliğin iki tarafına aynı sayı eklenince eşitlik bozulmaz: {tot} + {k} = {tot + k}.") if o else None
    if kind == "tersi":
        a, b = random.randint(3, 12), random.randint(3, 12)
        p = a * b
        o = _mf_opts(b, [a, p, p - a, a + b], str)
        return _mf_raw(subject, "İşlem Özellikleri", f"{a} × □ = {p} eşitliğinde □ yerine hangi sayı yazılmalıdır?", o, f"Çarpma işleminin tersi bölmedir: {p} : {a} = {b}.") if o else None
    a, b, c = random.randint(11, 40), random.randint(11, 40), random.randint(11, 40)
    o = _mf_opts(b, [a, c, a + b, b + 1], str)
    return _mf_raw(subject, "İşlem Özellikleri", f"{a} + {b} + {c} = {c} + {a} + □ eşitliğinde □ yerine hangi sayı yazılmalıdır?", o, f"Toplamada değişme özelliği vardır: {a} + {b} + {c} = {c} + {a} + {b}.") if o else None


def _mf_order2(subject):
    a, b, c = random.randint(2, 9), random.randint(10, 40), random.randint(10, 40)
    n1, n2, g1, g2 = random.choice([("kalem", "defter", "kalemin", "defterin"), ("kitap", "dergi", "kitabın", "derginin"), ("simit", "ayran", "simidin", "ayranın")])
    q = f"Bir {g1} fiyatı {b} TL, bir {g2} fiyatı {c} TL’dir. Her birinden {a} tane alan bir kişi toplam kaç TL öder?"
    q = q[0].upper() + q[1:]
