def _mf_ks_esd_denk(subject):
    n1, m = random.choice([(2, 2), (2, 3), (2, 4), (2, 5), (2, 6), (3, 2), (3, 3), (3, 4), (4, 2), (4, 3), (5, 2), (6, 2)])
