# ---- 6. SINIF MATEMATİK (4. aşama): Cebirsel ifadeler ile Açılar ve Dörtgenler genişletme
def _qx(a, b):
    """a·x + b biçiminde cebirsel ifade metni."""
    t = ("" if a == 1 else str(a)) + "x"
    return t + (f" + {b}" if b > 0 else f" − {-b}" if b < 0 else "")


def _mf6_ce_deger(subject):
    x = random.randint(2, 6)
    for _ in range(80):
        ex = [(random.randint(1, 5), random.randint(0, 9)) for _ in range(4)]
        vals = [a * x + b for a, b in ex]
        if len(set(vals)) == 4 and len({e for e in ex}) == 4:
            break
    else:
        return None
    en = random.choice([True, False])
    t = max(vals) if en else min(vals)
    pairs = _m6let([_qx(a, b) for a, b in ex])
    ans = None
    for (l, tx) in pairs:
        a, b = [e for e in ex if _qx(*e) == tx][0]
        if a * x + b == t:
            ans = l
    q = f"Tabloda dört cebirsel ifade harflerle gösterilmiştir. x = {x} için değeri en {'büyük' if en else 'küçük'} olan ifade hangi harfle gösterilmiştir?"
    ex_t = "x yerine " + str(x) + " yazılırsa: " + ", ".join(f"{l}: {[a * x + b for a, b in ex if _qx(a, b) == tx][0]}" for l, tx in sorted(pairs)) + f". En {'büyük' if en else 'küçük'} değer {ans} ifadesindedir."
    return _mf_raw(subject, "Cebirsel ifade", q, (sorted(l for l, _ in pairs), ans), ex_t, shape=_m6tab("Cebirsel ifadeler", "İfade", pairs))


def _mf6_ce_yaz(subject):
    p = random.randint(2, 9)
    n1 = random.randint(2, 5)
    n2 = random.randint(1, 4)
    pr = random.choice([4, 5, 6, 8, 10])
    sh = {"type": "table", "title": "Fiyat listesi", "headers": ["Ürün", "Fiyat"], "rows": [["Kalem", "x TL"], ["Defter", f"{pr} TL"]]}
    a, b = n1, n2 * pr
    c = _qx(a, b)
    wr = [_qx(a, pr), _qx(a + n2, b), _qx(n1 * n2, pr), _qx(a, n2 + pr), _qx(a + 1, b), f"{a + n2}x"]
    o = _m6o(c, wr, str)
    q = f"Tabloda bir kırtasiyedeki ürünlerin fiyatları verilmiştir. {n1} kalem ve {n2} defter için ödenecek toplam tutarı gösteren cebirsel ifade aşağıdakilerden hangisidir?"
    return _mf_raw(subject, "Cebirsel ifade", q, o, f"{n1} kalem {n1}x TL, {n2} defter {n2} × {pr} = {n2 * pr} TL; toplam {c} TL.", shape=sh) if o else None


def _mf6_ce_oruntu_kural(subject):
    a = random.randint(2, 6)
    b = random.randint(-2, 6)
    rows = [[str(k), str(a * k + b)] for k in (1, 2, 3, 4)]
    if any(int(r[1]) <= 0 for r in rows):
        return None
    sh = {"type": "table", "title": "Sayı örüntüsü", "headers": ["Sıra (n)", "Sayı"], "rows": rows}
    c = _qx(a, b).replace("x", "n")
    wr = [_qx(a, b + 1), _qx(a + 1, b), _qx(a, -b if b else 1), _qx(b if b > 0 else a + 2, a), _qx(a + 1, b - 1), _qx(a, b + 2)]
    wr = [w.replace("x", "n") for w in wr]
    o = _m6o(c, wr, str)
    q = "Tabloda bir sayı örüntüsünün ilk dört terimi sıra numaralarıyla verilmiştir. Bu örüntünün n. terimini veren cebirsel ifade aşağıdakilerden hangisidir?"
    return _mf_raw(subject, "Örüntüler", q, o, f"Terimler her adımda {a} artıyor; n = 1 için {a * 1 + b}. Kural {c}.", shape=sh) if o else None


def _mf6_ce_makine(subject):
    a = random.randint(2, 6)
    b = random.randint(1, 9)
    ops = random.choice([("çarpılıp", "eklenir", 1), ("çarpılıp", "çıkarılır", -1)])
    sg = ops[2]
    ins = random.sample(range(1, 9), 4)
    rows = [[str(i), str(a * i + sg * b)] for i in ins[:3]]
    if any(int(r[1]) <= 0 for r in rows):
        return None
    t = ins[3] + random.randint(2, 6)
    c = a * t + sg * b
    sh = {"type": "table", "title": "Makinenin girdi–çıktı tablosu", "headers": ["Girdi", "Çıktı"], "rows": rows}
    o = _m6o(c, [c + b, c - b if c - b > 0 else c + 2 * b, a * t, (a + 1) * t + sg * b, t + a + b, a * t + sg * 2 * b, c + a], str)
    q = f"Bir makine girdi sayısıyla aynı kuralı her seferinde uygulamaktadır. Tabloda makinenin üç girdisine karşılık çıktıları verilmiştir. Bu makineye girdi olarak {t} verilirse çıktı kaç olur?"
    return _mf_raw(subject, "Cebirsel ifade", q, o, f"Kural: girdi {a} ile {ops[0]} {b} {ops[1]}. {t} için {a} × {t} {'+' if sg > 0 else '−'} {b} = {c}.", shape=sh) if o and str(c) not in [r[1] for r in rows] else None


def _mf6_pl_denklem(subject):
    eq = random.choice([True, False])
    x = random.randint(10, 40)
    a = random.randint(1, 3)
    c1 = random.randint(0, 25)
    if eq:
        a2 = random.choice([v for v in (1, 2, 3) if v != a])
        c2 = a * x + c1 - a2 * x
        if c2 <= 0 or a * x + c1 >= 170:
            return None
        nm, prs, _e = random.choice([r for r in _PL_REL if r[2]])
        e1, e2 = _qx(a, c1), _qx(a2, c2)
        sumx = a * x + c1
    else:
        a2 = random.randint(1, 3)
        tot = a + a2
        rem = 180 - c1
        # a·x + c1 + a2·x + c2 = 180
        c2 = random.randint(5, 40)
        rem = 180 - c1 - c2
        if rem <= 0 or rem % tot:
            return None
        x = rem // tot
        nm, prs, _e = random.choice([r for r in _PL_REL if not r[2]])
        e1, e2 = _qx(a, c1), _qx(a2, c2)
        sumx = a * x + c1
    pa, pb = random.choice(prs)
    arcs = [_pl_arc("A", pa, f"({e1})°"), _pl_arc("B", pb, f"({e2})°")]
    sh = _pl_shape(arcs)
    if not sh or x <= 0:
        return None
    o = _m6o(x, [x + 5, x - 5 if x > 5 else x + 10, x + 10, x - 10 if x > 10 else x + 15, sumx, 180 - x if 180 - x != x else x + 20], str)
    q = "Şekilde d1 // d2 ve k kesendir. Şekilde gösterilen iki açının ölçüleri x cinsinden verilmiştir. Buna göre x kaçtır?"
    ex = f"Bu açılar {nm.lower()} olduğundan " + (f"{e1} = {e2} → x = {x}." if eq else f"({e1}) + ({e2}) = 180 → {a + a2}x = {180 - c1 - c2} → x = {x}.")
    return _mf_raw(subject, "Paralel doğrular ve kesen", q, o, ex, shape=sh) if o else None


def _mf6_dg_yamuk(subject):
    th = random.choice([50, 55, 60, 65, 70, 75, 80, 100, 105, 110, 120])
    ask = random.choice(["D", "C"])
    giv = "A" if ask == "D" else "B"
    sh = {"type": "geo", "sub_type": "quad", "kind": "trapezoid", "labels": ["A", "B", "C", "D"], "angles": {giv: f"{th}°", ask: "?"}}
    ans = 180 - th
    o = _m6o(ans, [th, 90 - th if th < 90 else th - 90 + 10, ans + 10, ans - 10 if ans > 10 else ans + 20, 360 - th - 90, ans + 20], lambda v: f"{v}°")
    q = f"Şekildeki ABCD yamuğunda [AB] // [DC] dir. m({giv}) = {th}° olduğuna göre m({ask}) kaç derecedir?"
    return _mf_raw(subject, "Dörtgenlerin açıları", q, o, f"Paralel kenarlar arasında aynı yandaki iç açıların toplamı 180°'dir: m({ask}) = 180° − {th}° = {ans}°.", shape=sh) if o else None


def _mf6_dg_genel(subject):
    for _ in range(60):
        a, b, c = [random.choice([50, 60, 65, 70, 75, 80, 85, 95, 100, 105, 110, 115, 120]) for _ in range(3)]
        d = 360 - a - b - c
        if 40 <= d <= 140:
            break
    else:
        return None
    L = ["A", "B", "C", "D"]
    ask = random.choice(L)
    vals = dict(zip(L, [a, b, c, d]))
    random.shuffle(L)
    vals = dict(zip(["A", "B", "C", "D"], random.sample([a, b, c, d], 4)))
    ans = vals[ask]
    sh = {"type": "geo", "sub_type": "quad", "kind": "general", "labels": ["A", "B", "C", "D"], "angles": {k: (f"{v}°" if k != ask else "?") for k, v in vals.items()}}
    o = _m6o(ans, [180 - ans, 360 - ans, ans + 10, ans - 10, ans + 20, 180 - ans + 10], lambda v: f"{v}°")
    q = f"Şekildeki ABCD dörtgeninde üç iç açının ölçüsü verilmiştir. m({ask}) kaç derecedir?"
    return _mf_raw(subject, "Dörtgenlerin açıları", q, o, f"Dörtgenin iç açılarının toplamı 360°'dir: m({ask}) = {ans}°.", shape=sh) if o else None


def _mf6_dg_esken(subject):
    th = random.choice([50, 55, 60, 65, 70, 75, 80, 100, 110, 120])
    ask = random.choice(["B", "C"])
    ans = 180 - th if ask == "B" else th
    sh = {"type": "geo", "sub_type": "quad", "kind": "rhombus", "labels": ["A", "B", "C", "D"], "angles": {"A": f"{th}°", ask: "?"}}
    o = _m6o(ans, [180 - ans, th // 2 + 10, ans + 10, ans - 10, 360 - 2 * th if 360 - 2 * th != ans else ans + 20, ans + 20], lambda v: f"{v}°")
    q = f"Şekildeki ABCD eşkenar dörtgeninde m(A) = {th}° olduğuna göre m({ask}) kaç derecedir?"
    return _mf_raw(subject, "Dörtgenlerin açıları", q, o, ("Karşılıklı açılar eşittir: " if ask == "C" else "Komşu açıların toplamı 180°'dir: ") + f"m({ask}) = {ans}°.", shape=sh) if o else None


def _mf6_dg_pk_cebir(subject):
    x = random.randint(10, 40)
    a = random.randint(1, 3)
    a2 = random.randint(1, 3)
    c1 = random.randint(0, 30)
    c2 = 180 - c1 - (a + a2) * x
    if c2 <= 0 or c2 > 60:
        return None
    sh = {"type": "geo", "sub_type": "quad", "kind": "parallelogram", "labels": ["A", "B", "C", "D"], "angles": {"A": f"({_qx(a, c1)})°", "B": f"({_qx(a2, c2)})°"}}
    o = _m6o(x, [x + 5, x - 5 if x > 5 else x + 10, x + 10, 180 - x, x + 15, x - 10 if x > 10 else x + 20], str)
    q = "Şekildeki ABCD paralelkenarında A ve B açılarının ölçüleri x cinsinden verilmiştir. Buna göre x kaçtır?"
    return _mf_raw(subject, "Dörtgenlerin açıları", q, o, f"Komşu açılar toplamı 180°: ({_qx(a, c1)}) + ({_qx(a2, c2)}) = 180 → {a + a2}x = {180 - c1 - c2} → x = {x}.", shape=sh) if o else None


_M6C = [(_mf6_ce_deger, 2, ("cebirsel", "değişken"), "MAT.6.2.3"), (_mf6_ce_yaz, 3, ("cebirsel", "değişken"), "MAT.6.2.3"), (_mf6_ce_oruntu_kural, 3, ("örüntü",), "MAT.6.2.2"),
        (_mf6_ce_makine, 3, ("cebirsel", "değişken"), "MAT.6.2.3"), (_mf6_pl_denklem, 4, ("dörtgenlerin", "paralel doğrular"), "MAT.6.3.2"), (_mf6_dg_yamuk, 3, ("dörtgenlerin", "paralel doğrular"), "MAT.6.3.4"),
        (_mf6_dg_genel, 2, ("dörtgenlerin", "paralel doğrular"), "MAT.6.3.4"), (_mf6_dg_esken, 3, ("dörtgenlerin", "paralel doğrular"), "MAT.6.3.4"), (_mf6_dg_pk_cebir, 4, ("dörtgenlerin", "paralel doğrular"), "MAT.6.3.4")]
for _f, _d, _kw, _cd in _M6C:
    _MF_GENS.append((_vy_wrap(_f), _kw, (6,)))
    _DIFF_OF[_f.__name__] = _d
    _MF_ITEMCODE[_f.__name__] = [_cd]



# ---- 6. SINIF MATEMATİK (5. aşama): Tam Sayılar ve Oran genişletme
def _tsn(v):
    return ("−" + str(-v)) if v < 0 else str(v)


def _mf6_ts_karsit(subject):
    a = random.randint(2, 7)
    others = [v for v in range(-7, 8) if abs(v) not in (a, 0)]
    vs = [-a * random.choice([1, -1]), 0]
    vs[1] = -vs[0]
    extra = random.sample([v for v in others if abs(v) != a], 2)
    allv = vs + extra
    random.shuffle(allv)
    hf = _lt(4)
    pts = [{"h": hf[i], "v": allv[i]} for i in range(4)]
    k = random.randrange(4)
    while -allv[k] not in allv:
        k = random.randrange(4)
    ans = hf[allv.index(-allv[k])]
    sh = _ts_sh(pts)
    q = f"Sayı doğrusunda dört nokta harflerle gösterilmiştir. {hf[k]} noktasının gösterdiği sayının karşıtı (toplama işlemine göre tersi) hangi noktayla gösterilmiştir?"
    return _mf_raw(subject, "Tam sayılar", q, (sorted(hf), ans), f"{hf[k]} noktası {_tsn(allv[k])} değerindedir; karşıtı {_tsn(-allv[k])} olup {ans} noktasıdır.", shape=sh)


def _mf6_ts_mutlak_en(subject):
    for _ in range(60):
        vs = random.sample(range(-8, 9), 4)
        ab = [abs(v) for v in vs]
        if len(set(ab)) == 4:
            break
    else:
        return None
    hf = _lt(4)
    en = random.choice([True, False])
    t = max(ab) if en else min(ab)
    ans = hf[ab.index(t)]
    sh = _ts_sh([{"h": hf[i], "v": vs[i]} for i in range(4)])
    q = f"Sayı doğrusunda dört nokta harflerle gösterilmiştir. Mutlak değeri en {'büyük' if en else 'küçük'} olan sayıyı gösteren nokta hangisidir?"
    return _mf_raw(subject, "Mutlak değer", q, (sorted(hf), ans), "Mutlak değer, sayının sıfıra uzaklığıdır: " + ", ".join(f"|{_tsn(v)}| = {abs(v)}" for v in vs) + f". En {'büyük' if en else 'küçük'}: {ans}.", shape=sh)


def _mf6_ts_bilanco(subject):
    gun = ["Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma"]
    vs = [random.choice([-1, 1]) * random.randint(2, 9) * 5 for _ in range(5)]
    tot = sum(vs)
    if tot == 0 or abs(tot) > 90 or any(vs.count(v) > 1 for v in vs):
        return None
    sh = {"type": "table", "title": "Bir kantinin günlük kâr (+) ve zararı (−) (TL)", "headers": ["Gün", "Kâr/Zarar (TL)"], "rows": [[g, ("+" if v > 0 else "−") + str(abs(v))] for g, v in zip(gun, vs)]}
    o = _m6o(tot, [sum(abs(v) for v in vs), tot + 10, tot - 10, tot + 5, tot - 5, tot + 15, tot - 15], lambda v: _tsn(v) + " TL")
    q = "Tabloda bir kantinin beş günlük kâr ve zarar durumu verilmiştir. Bu beş günün sonunda kantinin toplam durumu kaç TL’dir? (Kâr artı, zarar eksi sayılır.)"
    return _mf_raw(subject, "Tam sayılarla toplama", q, o, "Değerler toplanır: " + " ".join(("+" if v > 0 else "−") + str(abs(v)) for v in vs) + f" = {_tsn(tot)} TL.", shape=sh) if o else None


def _mf6_ts_sicaklik_fark(subject):
    sehir = random.sample(["Erzurum", "Kars", "Sivas", "Van", "Ankara", "Konya", "Bolu", "Ardahan"], 4)
    vs = random.sample(range(-14, 10), 4)
    i, j = random.sample(range(4), 2)
    fark = abs(vs[i] - vs[j])
    if fark in vs or fark == 0:
        return None
    sh = {"type": "table", "title": "Bir sabahın sıcaklıkları (°C)", "headers": ["Şehir", "Sıcaklık (°C)"], "rows": [[a, _tsn(b)] for a, b in zip(sehir, vs)]}
    o = _m6o(fark, [abs(vs[i] + vs[j]), fark + 2, fark - 2 if fark > 2 else fark + 4, fark + 5, fark + 1, abs(vs[i]) + abs(vs[j]) + 3], lambda v: f"{v} °C")
    q = f"Tabloda dört şehrin bir sabahki sıcaklıkları verilmiştir. {sehir[i]} ile {sehir[j]} arasındaki sıcaklık farkı kaç °C’dir?"
    return _mf_raw(subject, "Tam sayılarla çıkarma", q, o, f"{_tsn(vs[i])} ile {_tsn(vs[j])} arasındaki fark, sayı doğrusunda aradaki uzaklıktır: {fark} °C.", shape=sh) if o else None


def _mf6_or_karsilastir(subject):
    for _ in range(80):
        gr = [(random.randint(2, 9), random.randint(2, 9)) for _ in range(4)]
        vals = [_KFr(a, b) for a, b in gr]
        if len(set(vals)) == 4:
            break
    else:
        return None
    en = random.choice([True, False])
    t = max(vals) if en else min(vals)
    pairs = _m6let([f"{a} kız, {b} erkek" for a, b in gr])
    ans = None
    for (l, tx) in pairs:
        a, b = int(tx.split()[0]), int(tx.split()[2])
        if _KFr(a, b) == t:
            ans = l
    q = f"Tabloda dört sınıfın kız ve erkek öğrenci sayıları verilmiştir. Kız öğrenci sayısının erkek öğrenci sayısına oranı en {'büyük' if en else 'küçük'} olan sınıf hangi harfle gösterilmiştir?"
    ex = "Oranlar: " + ", ".join(f"{l}: {_fr(int(tx.split()[0]), int(tx.split()[2]))}" for l, tx in sorted(pairs)) + f". En {'büyük' if en else 'küçük'} oran {ans} sınıfındadır."
    return _mf_raw(subject, "Oran kavramı", q, (sorted(l for l, _ in pairs), ans), ex, shape=_m6tab("Sınıflar", "Öğrenci sayısı", pairs))


def _mf6_or_tarif(subject):
    m = random.choice([("un", "süt", "bardak"), ("şeker", "su", "kaşık"), ("kırmızı boya", "beyaz boya", "kutu"), ("limon suyu", "su", "bardak")])
    a, b = random.choice([(2, 3), (1, 4), (3, 5), (2, 5), (3, 4), (1, 3)])
    k = random.randint(2, 6)
    sh = {"type": "table", "title": "Tarif", "headers": ["Malzeme", f"Miktar ({m[2]})"], "rows": [[m[0], str(a)], [m[1], str(b)]]}
    ask1 = random.choice([True, False])
    given = b * k if ask1 else a * k
    ans = a * k if ask1 else b * k
    if ans in (a, b) or given in (a, b):
        return None
    o = _m6o(ans, [ans + a, ans - 1, given + ans, ans + k, ans * 2, given - a], str)
    q = f"Tabloda bir tarifin malzeme miktarları verilmiştir. Aynı oranı koruyarak {given} {m[2]} {m[1] if ask1 else m[0]} kullanılırsa kaç {m[2]} {m[0] if ask1 else m[1]} gerekir?"
    return _mf_raw(subject, "Orantı", q, o, f"Oran {a}:{b}; her bölüm {k} katına çıkar. Cevap {ans}.", shape=sh) if o else None


_M6D = [(_mf6_ts_karsit, 2, ("tam sayı", "mutlak değer"), None), (_mf6_ts_mutlak_en, 2, ("mutlak değer",), None), (_mf6_ts_bilanco, 2, ("tam sayı",), None), (_mf6_ts_sicaklik_fark, 3, ("tam sayı",), None),
        (_mf6_or_karsilastir, 3, ("oran kavramı", "orantı giriş"), None), (_mf6_or_tarif, 3, ("orantı giriş", "oran kavramı"), None)]
_M6D_IT = {"_mf6_ts_karsit": "Sayı doğrusunda karşıt sayı", "_mf6_ts_mutlak_en": "Mutlak değer karşılaştırma", "_mf6_ts_bilanco": "Kâr ve zarar toplamı", "_mf6_ts_sicaklik_fark": "Sıcaklık farkı",
           "_mf6_or_karsilastir": "Oranları karşılaştırma", "_mf6_or_tarif": "Tarifte orantı"}
for _f, _d, _kw, _cd in _M6D:
    _MF_GENS.append((_dl6_tag(_vy_wrap(_f), _f.__name__, _M6D_IT[_f.__name__], False), _kw, (6,)))
    _DIFF_OF[_f.__name__] = _d



# ---- 5. SINIF MATEMATİK: Açı İlişkileri ve Temel Geometrik Çizimler genişletme
def _mf5_a4_olc(subject):
    deg = random.choice([30, 40, 50, 55, 65, 70, 110, 120, 125, 130, 140])
    let = random.sample(list("KLMNPRST"), 4)
    gi = random.randrange(4)
    ai = random.choice([x for x in range(4) if x != gi])
    ms = [deg, 180 - deg, deg, 180 - deg]
    labs = list(let)
    labs[gi] = f"{ms[gi]}°"
    ans = ms[ai]
    ters = (gi - ai) % 2 == 0
    sh = {"type": "geo", "sub_type": "angles4", "degree": deg, "labels": labs}
    o = _mf_opts(ans, [x for x in (180 - ans, 90 - ans if ans < 90 else ans - 90, ans + 10, ans - 10, 360 - ans, ans + 20) if x != ans and x > 0], lambda v: f"{v}°", sort=False)
    q = f"Şekilde kesişen iki doğrunun oluşturduğu dört açıdan biri {ms[gi]}° olarak verilmiştir. Buna göre {let[ai]} ile gösterilen açının ölçüsü kaç derecedir?"
    ex = ("Ters açıların ölçüleri eşittir: " if ters else f"Komşu açıların ölçüleri toplamı 180°’dir: 180° − {ms[gi]}° = ") + f"{ans}°."
    return _mf_raw(subject, "Açı ilişkileri", q, o, ex, shape=sh) if o else None


def _mf5_a4_ters(subject):
    deg = random.choice([40, 50, 60, 70, 110, 120, 130])
    let = random.sample(list("KLMNPRST"), 4)
    sh = {"type": "geo", "sub_type": "angles4", "degree": deg, "labels": let}
    pairs = [(0, 2), (1, 3)]
    adj = [(0, 1), (1, 2), (2, 3), (3, 0)]
    c = random.choice(pairs)
    fm = lambda p: f"{let[p[0]]} ve {let[p[1]]}"
    wr = random.sample(adj, 3)
    o = _mf_opts(fm(c), [fm(p) for p in wr], lambda x: x, sort=False)
    q = "Şekilde kesişen iki doğru dört açı oluşturmuştur. Aşağıdaki açı çiftlerinden hangisi ters (karşıt) açılardır?"
    return _mf_raw(subject, "Açı ilişkileri", q, o, f"Ters açılar kesişen iki doğrunun karşılıklı açılarıdır: {fm(c)}. Diğer çiftler komşu açılardır.", shape=sh) if o else None


_MF5_TG = {
    "dogru": ("Hangisi bir doğruyu anlatır?", ["İki yönde de sonsuza kadar uzanır.", "Başlangıç ve bitiş noktası yoktur."]),
    "isin": ("Hangisi bir ışını anlatır?", ["Başlangıç noktası vardır ve bir yönde sonsuza kadar uzanır.", "Bir ucu sınırlı, diğer ucu sınırsızdır."]),
    "parca": ("Hangisi bir doğru parçasını anlatır?", ["İki ucu da sınırlıdır ve uzunluğu ölçülebilir.", "İki noktası arasındaki en kısa yolu gösterir."]),
    "paralel": ("Hangisi paralel doğruları anlatır?", ["Aynı düzlemde olup hiçbir yerde kesişmez.", "Aralarındaki uzaklık her yerde aynıdır."]),
    "dik": ("Hangisi birbirine dik doğruları anlatır?", ["Kesiştiği noktada 90°’lik açı oluşturur.", "Kesişirken dört dik açı oluşturur."]),
}


def _mf5_tg_cumle(subject):
    t = random.choice(list(_MF5_TG))
    phrase, sents = _MF5_TG[t]
    target = random.choice(sents)
    pool = [x for k, (ph, L) in _MF5_TG.items() if k != t for x in L]
    rows = [target] + random.sample(pool, 3)
    random.shuffle(rows)
    let = list("KLMN")
    random.shuffle(let)
    lab = {let[i]: rows[i] for i in range(4)}
    sh = {"type": "table", "title": "İfadeler", "headers": ["Harf", "İfade"], "rows": [[k, lab[k]] for k in sorted(lab)]}
    c = next(k for k, v in lab.items() if v == target)
    return _mf_raw(subject, "Temel geometrik kavramlar", "Tabloda dört ifade harflerle gösterilmiştir.\n" + phrase, (sorted(lab), c), f"{c} harfli ifade ({target}) sorudaki kavrama uygundur.", shape=sh)


for _f, _kw, _d, _it in ((_mf5_a4_olc, ("ters (karşıt)", "komşu açılar"), 2, "Kesişen doğrularda açı ölçüsü"), (_mf5_a4_ters, ("ters (karşıt)", "komşu açılar"), 2, "Ters açı çifti"),
                         (_mf5_tg_cumle, ("doğru, ışın, doğru parçası", "paralel ve dik doğrular"), 2, "Doğru, ışın ve doğru parçası")):
    _MF_GENS.append((_dl6_tag(_vy_wrap(_f), _f.__name__, _it, False), _kw, (5,)))
    _DIFF_OF[_f.__name__] = _d
    _MF_ITEMCODE[_f.__name__] = ["MAT.5.3.4"] if "a4" in _f.__name__ else ["MAT.5.3.1"]


# ---- 6. SINIF MATEMATİK (2. aşama): Alan ve Çevre, Kesirler, Oran, Ondalık/Yüzde, Paralel doğrular
def _ac(v):
    return str(v).replace(".", ",")


def _a_sh(kind, b, h, lb, lh, **kw):
    return {"type": "m6", "sub_type": "alan", "kind": kind, "b": b, "h": h, "lb": lb, "lh": lh, **kw}


def _mf6_al_ucgen(subject):
    b = random.choice([6, 8, 10, 12, 14, 16, 18, 20])
    h = random.randint(4, 13)
    s = h + random.randint(2, 5)
    a = b * h // 2
    o = _m6o(a, [b * h, b + h, s * b // 2, (b + h) * 2, a + b, a + h, b * s], lambda v: f"{v} cm²")
    sh = _a_sh("ucgen", b, h, f"{b} cm", f"{h} cm", ox=random.choice([.25, .35, .5]), ls=f"{s} cm")
    q = "Şekilde bir üçgenin taban uzunluğu, yüksekliği ve bir kenar uzunluğu verilmiştir. Bu üçgenin alanı kaç santimetrekaredir?"
    return _mf_raw(subject, "Üçgenin alanı", q, o, f"Alan = (taban × yükseklik) ÷ 2 = ({b} × {h}) ÷ 2 = {a} cm². Eğik kenar ({s} cm) alan hesabında kullanılmaz.", shape=sh) if o else None


def _mf6_al_paralel(subject):
    b = random.randint(5, 18)
    h = random.randint(3, 12)
    s = h + random.randint(2, 5)
    a = b * h
    o = _m6o(a, [b * s, 2 * (b + s), b + h, a // 2, a + b, (b + h) * 2, a - h], lambda v: f"{v} cm²")
    sh = _a_sh("paralel", b, h, f"{b} cm", f"{h} cm", off=random.choice([1.0, 1.3, 1.6]), ls=f"{s} cm")
    q = "Şekilde bir paralelkenarın taban uzunluğu, yüksekliği ve eğik kenar uzunluğu verilmiştir. Bu paralelkenarın alanı kaç santimetrekaredir?"
    return _mf_raw(subject, "Paralelkenarın alanı", q, o, f"Alan = taban × yükseklik = {b} × {h} = {a} cm². Eğik kenar ({s} cm) alanda kullanılmaz.", shape=sh) if o else None


def _mf6_al_ters(subject):
    kind = random.choice(["ucgen", "paralel"])
    b = random.choice([6, 8, 10, 12, 14, 16])
    h = random.randint(3, 11)
    a = b * h // 2 if kind == "ucgen" else b * h
    nm = "üçgenin" if kind == "ucgen" else "paralelkenarın"
    o = _m6o(h, [h + 1, h - 1, h * 2, a // b if a // b != h else h + 3, h + 2, b])
    sh = _a_sh(kind, b, h, f"{b} cm", "h = ?", **({"ox": .4} if kind == "ucgen" else {"off": 1.3}), **{"in": f"Alan = {a} cm²"})
    q = f"Şekilde alanı {a} cm² ve taban uzunluğu {b} cm olan bir {nm} yüksekliği (h) kaç santimetredir?".replace("bir üçgenin yüksekliği", "bir üçgenin yüksekliği").replace("bir paralelkenarın yüksekliği", "bir paralelkenarın yüksekliği")
    ex = (f"{a} = ({b} × h) ÷ 2 → h = {a * 2} ÷ {b} = {h}." if kind == "ucgen" else f"{a} = {b} × h → h = {a} ÷ {b} = {h}.")
    return _mf_raw(subject, "Alan problemleri", q, o, ex, shape=sh) if o else None


def _mf6_al_bilesik(subject):
    w = random.choice([6, 8, 10, 12])
    rh = random.randint(3, 8)
    t = random.choice([2, 4, 6])
    a = w * rh + w * t // 2
    o = _m6o(a, [w * rh, w * rh + w * t, w * (rh + t), a + w, a - w, w * t // 2, 2 * (w + rh)], lambda v: f"{v} cm²")
    sh = {"type": "m6", "sub_type": "alan", "kind": "bilesik", "b": w, "h": rh, "lb": f"{w} cm", "lh": f"{rh} cm", "lt": f"{t} cm"}
    q = "Şekildeki bileşik şekil bir dikdörtgen ile bir üçgenden oluşmaktadır. Şeklin toplam alanı kaç santimetrekaredir?"
    return _mf_raw(subject, "Alan problemleri", q, o, f"Dikdörtgen: {w} × {rh} = {w * rh}; üçgen: ({w} × {t}) ÷ 2 = {w * t // 2}; toplam {a} cm².", shape=sh) if o else None


def _cm_sh(mode, lr, **kw):
    return {"type": "m6", "sub_type": "cember", "mode": mode, "lr": lr, **kw}


def _mf6_cm_r(subject):
    r = random.randint(3, 20)
    c = 6 * r
    o = _m6o(c, [3 * r, 12 * r if 12 * r != c else c + 6, r * r * 3, 2 * r, c + 6, c - 6, 4 * r], lambda v: f"{v} cm")
    q = "Şekilde yarıçapı verilen çemberin çevre uzunluğu kaç santimetredir? (π = 3 alınız.)"
    return _mf_raw(subject, "Çemberin uzunluğu", q, o, f"Çevre = 2 × π × r = 2 × 3 × {r} = {c} cm.", shape=_cm_sh("r", f"r = {r} cm")) if o else None


def _mf6_cm_cap(subject):
    d = random.choice([4, 6, 8, 10, 12, 14, 16, 18, 20, 24])
    c = 3 * d
    o = _m6o(c, [6 * d, d * d, 2 * d, c + 3, c - 3, d // 2 * 3 if (d // 2 * 3) != c else c + 6, 9 * d])
    q = "Şekilde çapı verilen çemberin çevre uzunluğu kaç santimetredir? (π = 3 alınız.)"
    return _mf_raw(subject, "Çemberin uzunluğu", q, [x for x in [o]][0], f"Çevre = π × d = 3 × {d} = {c} cm.", shape=_cm_sh("cap", f"d = {d} cm")) if o else None


def _mf6_cm_ters(subject):
    r = random.randint(2, 15)
    c = 6 * r
    o = _m6o(r, [r * 2, r + 1, r - 1, c // 3 if c // 3 != r else r + 3, c, r + 2, r // 2 + 1 if r // 2 + 1 != r else r + 4], lambda v: f"{v} cm")
    q = f"Şekilde çevre uzunluğu {c} cm olan bir çember verilmiştir. Bu çemberin yarıçapı (r) kaç santimetredir? (π = 3 alınız.)"
    return _mf_raw(subject, "Çemberin uzunluğu", q, o, f"Çevre = 2 × 3 × r = 6r = {c} → r = {r} cm.", shape=_cm_sh("r", "r = ?", note=f"Çevre = {c} cm")) if o else None


def _mf6_cm_yay(subject):
    for _ in range(40):
        th = random.choice([60, 90, 120, 180, 270])
        r = random.randint(4, 20)
        if (th * r) % 60 == 0:
            break
    else:
        return None
    y = th * r // 60
    o = _m6o(y, [6 * r, 3 * r, y + 3, y - 3, r * th // 90 if r * th // 90 != y else y + 6, y + 6, 2 * r])
    sh = _cm_sh("dilim", f"r = {r} cm", theta=th, lt=f"{th}°")
    q = "Şekilde merkez açısı ve yarıçapı verilen daire diliminin yay uzunluğu kaç santimetredir? (π = 3 alınız.)"
    return _mf_raw(subject, "Çemberin uzunluğu", q, [o][0], f"Çevre = 6 × {r} = {6 * r} cm; yay = {6 * r} × {th}/360 = {y} cm.", shape=sh) if o else None


# ---- Kesirler
def _frs(a, b):
    f = _KFr(a, b)
    return f"{f.numerator}/{f.denominator}"


def _kb_sh(rows):
    return {"type": "kes", "sub_type": "bar", "rows": rows}


def _kbrow(name, d, k):
    return {"name": name, "segs": [{"l": "", "w": 1, "q": i >= k} for i in range(d)]}


def _mf6_kf_topla(subject):
    pr = random.choice([(2, 4), (3, 6), (5, 10), (4, 8), (2, 6), (3, 9)])
    d1, d2 = pr
    a, b = random.randint(1, d1 - 1), random.randint(1, d2 - 1)
    s = _KFr(a, d1) + _KFr(b, d2)
    if s.denominator > 12 or s >= 2:
        return None
    sh = _kb_sh([_kbrow("I", d1, a), _kbrow("II", d2, b)])
    wr = [_frs(a + b, d1 + d2), _frs(a + b, d1), _frs(a + b, d2), _frs(a * b, d1 * d2), _frs(abs(a * d2 - b * d1) or 1, d1 * d2)]
    o = _m6o(_frs(s.numerator, s.denominator), wr, lambda v: v)
    q = "Şekilde birbirine eş iki şerit farklı sayıda eş parçaya bölünmüştür ve boyalı kısımlar gösterilmiştir. Boyalı kısımların toplamı bütünün kaçta kaçıdır?"
    return _mf_raw(subject, "Kesir işlemleri", q, o, f"{a}/{d1} + {b}/{d2} = {_frs(a * d2 + b * d1, d1 * d2)} = {_frs(s.numerator, s.denominator)}.", shape=sh) if o else None


def _mf6_kf_cikar(subject):
    pr = random.choice([(2, 4), (3, 6), (5, 10), (4, 8), (2, 6), (3, 9)])
    d1, d2 = pr
    for _t in range(30):
        a, b = random.randint(1, d1 - 1), random.randint(1, d2 - 1)
        if _KFr(a, d1) > _KFr(b, d2):
            break
    s = _KFr(a, d1) - _KFr(b, d2)
    if s <= 0:
        return None
    sh = _kb_sh([_kbrow("I", d1, a), _kbrow("II", d2, b)])
    wr = [_frs(abs(a - b) or 1, abs(d1 - d2) or 1), _frs(a + b, d1 + d2), _frs(a * d2 + b * d1, d1 * d2), _frs(abs(a - b) or 1, d1), _frs(abs(a - b) or 1, d2)]
    o = _m6o(_frs(s.numerator, s.denominator), wr, lambda v: v)
    q = "Şekilde birbirine eş iki şerit farklı sayıda eş parçaya bölünmüştür ve boyalı kısımlar gösterilmiştir. I. şeridin boyalı kısmı, II. şeridin boyalı kısmından bütünün kaçta kaçı kadar fazladır?"
    return _mf_raw(subject, "Kesir işlemleri", q, o, f"{a}/{d1} − {b}/{d2} = {_frs(s.numerator, s.denominator)}.", shape=sh) if o else None


def _mf6_kf_alan(subject):
    d1, d2 = random.randint(3, 6), random.randint(3, 6)
    a, b = random.randint(1, d1 - 1), random.randint(1, d2 - 1)
    sh = {"type": "m6", "sub_type": "alanm", "rows": d1, "cols": d2, "a": a, "b": b}
    ans = f"{a * b}/{d1 * d2}"
    wr = [f"{a}/{d1}", f"{b}/{d2}", f"{a + b}/{d1 + d2}", f"{a * b}/{d1 + d2}", f"{a + b}/{d1 * d2}"]
    o = _m6o(ans, wr, lambda v: v)
    q = f"Şekilde birim kare {d1} eş yatay ve {d2} eş dikey şeride bölünmüştür. Mavi şeritler bütünün {a}/{d1} kesrini, sarı şeritler {b}/{d2} kesrini göstermektedir. Turuncu bölge (iki rengin kesiştiği yer) bütünün kaçta kaçıdır?"
    return _mf_raw(subject, "Kesir işlemleri", q, o, f"{a}/{d1} × {b}/{d2} = {ans}. Turuncu bölgede {a * b} küçük kare, toplamda {d1 * d2} küçük kare vardır.", shape=sh) if o else None


def _mf6_kf_problem(subject):
    d = random.choice([4, 5, 6, 8, 10])
    k = random.randint(1, d - 1)
    unit = random.choice([("kitap", "sayfa"), ("depo", "litre"), ("yol", "km")])
    t = d * random.randint(6, 25)
    rem = t * (d - k) // d
    sh = _kb_sh([{"name": "", "segs": [{"l": "", "w": 1, "q": i >= k} for i in range(d)], "brace": f"{t} {unit[1]}"}])
    o = _m6o(rem, [t * k // d, t - d, t // d, t + k, rem + d, rem - d, t - k], lambda v: f"{v} {unit[1]}")
    nm = {"kitap": "Şekilde toplam", "depo": "Şekilde toplam", "yol": "Şekilde toplam"}[unit[0]]
    q = f"Şekildeki çubuk modelinde toplam {t} {unit[1]} olan bir bütünün boyalı kısmı kullanılmıştır. Kullanılmayan (boyasız) kısım kaç {unit[1]}dır?".replace("litredır", "litredir").replace("sayfadır", "sayfadır").replace("kmdır", "km'dir")
    return _mf_raw(subject, "Kesir problemleri", q, o, f"Her parça {t} ÷ {d} = {t // d}; boyasız {d - k} parça → {rem} {unit[1]}.", shape=sh) if o else None


# ---- Oran
def _mf6_or_say(subject):
    g = random.choice([(2, 3), (3, 4), (1, 2), (3, 5), (2, 5), (4, 5), (1, 3)])
    m = random.randint(1, 3)
    a, b = g[0] * m, g[1] * m
    if a + b > 24:
        return None
    sh = {"type": "m6", "sub_type": "oran", "gr": [{"c": "K", "n": a}, {"c": "M", "n": b}]}
    ans = f"{g[0]}/{g[1]}"
    wr = [f"{g[1]}/{g[0]}", f"{g[0]}/{g[0] + g[1]}", f"{g[1]}/{g[0] + g[1]}", f"{a}/{b + 1}", f"{g[0] + 1}/{g[1]}"]
    o = _m6o(ans, wr, lambda v: v)
    q = "Şekilde bir torbadaki kırmızı ve mavi bilyeler gösterilmiştir. Kırmızı bilyelerin sayısının mavi bilyelerin sayısına oranı en sade biçimde kaçtır?"
    return _mf_raw(subject, "Oran kavramı", q, o, f"Kırmızı {a}, mavi {b}; oran {a}/{b} = {ans}.", shape=sh) if o else None


def _mf6_or_karisim(subject):
    a, b = random.choice([(1, 2), (2, 3), (1, 3), (3, 5), (2, 5), (1, 4), (3, 4)])
    m = random.randint(2, 8)
    t = (a + b) * m
    ask = random.choice(["K", "M"])
    segs = [{"l": "K", "w": 1} for _ in range(a)] + [{"l": "M", "w": 1, "q": True} for _ in range(b)]
    sh = _kb_sh([{"name": "", "segs": segs, "brace": f"{t} L"}])
    ans = a * m if ask == "K" else b * m
    nm = "kırmızı boya (K)" if ask == "K" else "mavi boya (M)"
    o = _m6o(ans, [t - ans, t // (a + b), ans + m, max(ans - m, 1), a + b, ans * 2], lambda v: f"{v} L")
    q = f"Şekilde toplam {t} L olan bir karışımın kırmızı boya (K) ve mavi boya (M) oranı gösterilmiştir. Bu karışımda kaç litre {nm} vardır?"
    return _mf_raw(subject, "Oran kavramı", q, o, f"Toplam {a + b} parça; her parça {t} ÷ {a + b} = {m} L. {nm}: {ans} L.", shape=sh) if o else None


def _mf6_or_tablo(subject):
    sc = random.choice([("Defter sayısı", "Ödenen tutar (TL)", 6, 20), ("Haritadaki uzunluk (cm)", "Gerçek uzunluk (km)", 1, 25), ("Su miktarı (L)", "Yağ miktarı (mL)", 1, 15), ("Çalışma süresi (saat)", "Üretilen parça (adet)", 1, 12)])
    ks = sorted(random.sample([1, 2, 3, 4, 5, 6, 8], 3))
    r = random.randint(2, 9) if sc[2] == 1 else random.choice([5, 6, 7, 8, 9, 10, 12])
    rows = [[str(k), str(k * r)] for k in ks[:2]] + [[str(ks[2]), "?"]]
    ans = ks[2] * r
    o = _m6o(ans, [ans + r, ans - r, ans + 2 * r, ks[2] + r, ans + 1, ans - 1, ks[1] * r + ks[2]], str)
    sh = {"type": "table", "title": "Doğru orantılı iki nicelik", "headers": [sc[0], sc[1]], "rows": rows}
    q = "Tabloda doğru orantılı iki nicelik verilmiştir. Tablodaki ? yerine hangi sayı gelmelidir?"
    return _mf_raw(subject, "Orantı", q, o, f"Her satırda ikinci sayı birincinin {r} katıdır. ? = {ks[2]} × {r} = {ans}.", shape=sh) if o and ans > 0 and ks[0] * r != ans else None


# ---- Ondalık gösterim ve yüzde
def _yz_sh(n):
    return {"type": "m6", "sub_type": "yuzluk", "n": n}


def _mf6_od_yuzde(subject):
    n = random.choice([x for x in range(8, 93) if x % 5 != 0 or random.random() < .4])
    mode = random.choice(["boyali", "bos"])
    ans = n if mode == "boyali" else 100 - n
    o = _m6o(ans, [100 - ans, ans + 5, ans - 5, ans // 10 + 10, ans + 10, ans + 1], lambda v: f"%{v}")
    q = f"Şekilde 100 eş kareye bölünmüş bir ızgaranın {'boyalı' if mode == 'boyali' else 'boyasız'} kısmını yüzde olarak yazınız."
    q = f"Şekilde 100 eş kareye bölünmüş ızgaranın {'boyalı' if mode == 'boyali' else 'boyasız'} kısmı yüzde kaçtır?"
    return _mf_raw(subject, "Yüzde", q, o, f"100 karenin {n} tanesi boyalı, {100 - n} tanesi boyasızdır → %{ans}.", shape=_yz_sh(n)) if o else None


def _mf6_od_ond(subject):
    n = random.choice([x for x in range(11, 99) if x % 10 != 0])
    ans = _ac(f"{n / 100:.2f}")
    wr = [_ac(f"{n / 10:.1f}"), _ac(f"{n / 1000:.3f}"), _ac(f"{(100 - n) / 100:.2f}"), _ac(f"{int(str(n)[::-1]) / 100:.2f}"), _ac(f"{n}")]
    o = _m6o(ans, wr, lambda v: v)
    q = "Şekilde 100 eş kareye bölünmüş ızgaranın boyalı kısmının ondalık gösterimi aşağıdakilerden hangisidir?"
    return _mf_raw(subject, "Ondalık gösterim", q, o, f"100 karenin {n} tanesi boyalı: {n}/100 = {ans}.", shape=_yz_sh(n)) if o else None


def _mf6_od_kesir(subject):
    n = random.choice([10, 15, 20, 25, 30, 35, 40, 45, 50, 60, 65, 70, 75, 80, 85])
    f = _KFr(n, 100)
    ans = f"{f.numerator}/{f.denominator}"
    wr = [f"{n}/100", f"{100 - n}/100", f"{f.denominator}/{f.numerator}", f"{f.numerator}/{f.denominator + 1}", f"{n}/10"]
    o = _m6o(ans, wr, lambda v: v)
    q = "Şekilde 100 eş kareye bölünmüş ızgaranın boyalı kısmı en sade (sadeleşmiş) kesir olarak aşağıdakilerden hangisidir?"
    return _mf_raw(subject, "Kesir, ondalık, yüzde", q, o, f"{n}/100 sadeleştirilince {ans} olur.", shape=_yz_sh(n)) if o else None


def _mf6_od_tablo(subject):
    items = random.sample([("Ekmek", 7.5), ("Süt", 28.75), ("Peynir", 96.5), ("Zeytin", 64.25), ("Bal", 120.0), ("Yoğurt", 35.5), ("Domates", 22.25), ("Çay", 84.75)], 4)
    i, j = random.sample(range(4), 2)
    t = items[i][1] + items[j][1]
    fmt = lambda v: f"{v:.2f}".replace(".", ",")
    ans = fmt(t)
    wr = [fmt(t + 1), fmt(t - 1.25), fmt(t + 10), fmt(abs(items[i][1] - items[j][1])), fmt(t + .5), fmt(t - 10)]
    o = _m6o(ans, wr, lambda v: v)
    sh = {"type": "table", "title": "Market fiyat listesi", "headers": ["Ürün", "Fiyat (TL)"], "rows": [[n, fmt(v)] for n, v in items]}
    q = f"Tabloda bir marketteki ürünlerin fiyatları verilmiştir. {items[i][0]} ile {items[j][0]} birlikte alınırsa toplam kaç TL ödenir?"
    return _mf_raw(subject, "Ondalık sayılarla işlemler", q, o, f"{fmt(items[i][1])} + {fmt(items[j][1])} = {ans} TL.", shape=sh) if o else None


# ---- Paralel doğrular ve kesen (geo şeması)
_PAR_PTS = {"A": "d1_k", "B": "d2_k", "C": "d1_r", "D": "d1_l", "E": "d2_r", "F": "d2_l", "G": "k_up", "H": "k_down"}
_PAR_ANG = {("A", "UR"): ("A", "C", "G"), ("A", "UL"): ("A", "D", "G"), ("A", "LR"): ("A", "C", "B"), ("A", "LL"): ("A", "D", "B"),
            ("B", "UR"): ("B", "E", "A"), ("B", "UL"): ("B", "F", "A"), ("B", "LR"): ("B", "E", "H"), ("B", "LL"): ("B", "F", "H")}
_PAR_REL = [("Yöndeş açılardır", "eq", [("UR", "UR"), ("UL", "UL"), ("LR", "LR"), ("LL", "LL")]), ("İç ters açılardır", "eq", [("LR", "UL"), ("LL", "UR")]),
            ("Dış ters açılardır", "eq", [("UR", "LL"), ("UL", "LR")]), ("Karşı durumlu (iç) açılardır", "sup", [("LR", "UR"), ("LL", "UL")])]


def _par_shape(g, a, x, y):
    va = _PAR_ANG[("A", g)]
    vb = _PAR_ANG[("B", a)]
    pts = {k: v for k, v in _PAR_PTS.items()}
    sh = {"type": "geo", "sub_type": "parallel", "layout": "transversal", "labels": ["d1", "d2", "k"], "points": pts,
          "arcs": [{"v": va[0], "a": va[1], "b": va[2], "label": x}, {"v": vb[0], "a": vb[1], "b": vb[2], "label": y}]}
    return sh, va, vb


def _par_ok(sh):
    try:
        from . import visuals as _v
        return bool(_v.par_geometry(sh)["ok"])
    except Exception:
        return False


def _mf6_pl_olcu(subject):
    nm, kind, pairs = random.choice(_PAR_REL)
    g, a = random.choice(pairs)
    th = random.choice([40, 50, 55, 65, 70, 110, 115, 125, 130, 140])
    ans = th if kind == "eq" else 180 - th
    sh, va, vb = _par_shape(g, a, f"{th}°", "x")
    if not _par_ok(sh):
        return None
    o = _m6o(ans, [180 - ans, ans + 10, ans - 10, 90 - ans if ans < 90 else ans - 90, ans + 20, 360 - ans if 360 - ans != ans else ans + 5], lambda v: f"{v}°")
    q = f"Şekilde d1 // d2 ve k kesendir. m({va[1] + va[0] + va[2]}) = {th}° olduğuna göre m({vb[1] + vb[0] + vb[2]}) = x kaç derecedir?"
    return _mf_raw(subject, "Paralel doğrular ve kesen", q, o, f"{nm[:-7]} açılarda " + ("ölçüler eşittir" if kind == "eq" else "ölçüler toplamı 180°'dir") + f" → x = {ans}°.", shape=sh) if o else None


def _mf6_pl_iliski(subject):
    nm, kind, pairs = random.choice(_PAR_REL)
    g, a = random.choice(pairs)
    sh, va, vb = _par_shape(g, a, "x", "y")
    if not _par_ok(sh):
        return None
    allv = [r[0] for r in _PAR_REL]
    q = f"Şekilde d1 // d2 ve k kesendir. m({va[1] + va[0] + va[2]}) = x ve m({vb[1] + vb[0] + vb[2]}) = y açıları birbirine göre hangi ilişkidedir?"
    return _mf_raw(subject, "Paralel doğrular ve kesen", q, (allv, nm), f"Bu iki açı {nm[:-9].lower()} konumundadır.", shape=sh)


def _mf6_dg_paralelkenar(subject):
    t = random.choice([50, 60, 70, 80, 100, 110, 120, 130])
    pos = "ardışık"
    kd = random.choice(["parallelogram", "rhombus"])
    ans = 180 - t
    ang = {"A": t if False else f"{t}°", "C": "x"} if pos == "karşıt" else {"A": f"{t}°", "B": "x"}
    sh = {"type": "geo", "sub_type": "quad", "kind": kd, "labels": ["A", "B", "C", "D"], "angles": ang}
    o = _m6o(ans, [180 - ans, ans + 10, ans - 10, 360 - ans - t if 360 - ans - t > 0 else ans + 20, 90, ans + 20], lambda v: f"{v}°")
    ask = "C" if pos == "karşıt" else "B"
    q = f"Şekildeki ABCD {'paralelkenarında' if kd == 'parallelogram' else 'eşkenar dörtgeninde'} m(A) = {t}° olduğuna göre x ile gösterilen m({ask}) kaç derecedir?"
    return _mf_raw(subject, "Dörtgenlerin açıları", q, o, ("Karşıt açılar eşittir" if pos == "karşıt" else "Ardışık açıların toplamı 180°'dir") + f" → x = {ans}°.", shape=sh) if o else None


