def _fam_item(name, fn, subject, items):
    """Hazır kalıp hangi alt konuya/kazanıma ait? Birkaç örnek sorusunun metni alt konu metniyle eşleştirilir (önbellekli)."""
    key = (name, tuple(items))
    if key in _FI_CACHE:
        return _FI_CACHE[key]
    for _code in _MF_ITEMCODE.get(name, ()):
        for _ix, _txt in enumerate(items):
            if _txt.startswith(_code):
                _FI_CACHE[key] = _ix
                return _ix
    _it = getattr(fn, "ITEM", None)
    if _it is not None:
        _FI_CACHE[key] = items.index(_it) if _it in items else -1
        return _FI_CACHE[key]
    from collections import Counter as _C
    votes = _C()
    for _ in range(4):
        try:
            r = fn(subject)
        except Exception:
            r = None
        if r:
            votes[_q_item(r, items)] += 1
    v = votes.most_common(1)[0][0] if votes else -1
    _FI_CACHE[key] = v
    return v


_YN_PREFIX = {"Matematik": ("_mf_yn_",), "Fen Bilimleri": ("_ff_yn_", "_ff_yn2_"), "Sosyal Bilgiler": ("_sf_yn_",), "Din Kültürü ve Ahlak Bilgisi": ("_df_yn_",), "İngilizce": ("_en_yn_",), "Türkçe": ("_tf_par_", "_tf_dk_")}
_YN_SHARE = 0.3  # sınavdaki yeni nesil (senaryo/tablo/belge/paragraf) soru payı


def _bal_order(rkey, byname, subject, grade_label, topics, n):
    """Yeni nesil kalıplara sınavda en az ~%30 pay ayırır (Fen/Türkçe); sıra dengesi _bal_order0'dan gelir."""
    out = _bal_order0(rkey, byname, subject, grade_label, topics, n)
    pre = _YN_PREFIX.get(subject)
    if not pre or n < 4:
        return out
    yn = [x for x in out if x.startswith(pre)]
    if not yn:
        return out
    q = min(len(yn), max(1, round({"Matematik": 0.4, "Fen Bilimleri": 0.4, "Sosyal Bilgiler": 0.4, "Din Kültürü ve Ahlak Bilgisi": 0.4, "İngilizce": 0.4}.get(subject, _YN_SHARE) * n)))
    pick = yn[:q]
    rest = [x for x in out if x not in pick]
    step = max(1, n // q)
    for i, x in enumerate(pick):
        rest.insert(min(len(rest), 1 + i * step), x)
    return rest


def _bal_order0(rkey, byname, subject, grade_label, topics, n):
    """Kalıpları alt konulara/kazanımlara göre dönüşümlü sıralar: ilk n soru mümkün olduğunca farklı kazanımlardan gelir."""
    names = list(byname)
    items = _topic_items(subject, grade_label, topics)
    if len(items) < 2 or len(names) < 3:
        return _recent_order(rkey, names)
    grp = {}
    for nm in names:
        grp.setdefault(_fam_item(nm, byname[nm], subject, items), []).append(nm)
    ik = ("item",) + tuple(rkey)
    keys = _recent_order(ik, list(grp))
    lists = {k: _recent_order(rkey, v) for k, v in grp.items()}
    out = []
    while any(lists.values()):
        for k in keys:
            if lists[k]:
                out.append(lists[k].pop(0))
    for k in keys[:max(1, n)]:
        _recent_mark(ik, k)
    return out


def _scope_plan(subject, n, topics, grade_label):
    """Yapay zekâ isteğinde her soruya farklı kazanım/alt konu atar."""
    items = _topic_items(subject, grade_label, topics)
    if len(items) < 2 or n < 2:
        return ""
    order = []
    while len(order) < n:
        order += random.sample(items, len(items))
    lines = [f"  Soru {i + 1} → kazanım/alt konu: {order[i][:170]}" for i in range(n)]
    return ("\nKAZANIM DAĞILIMI (her soru yalnızca yanındaki kazanımdan/alt konudan olsun; art arda aynı kazanımdan soru yazma; seçilen tüm kazanımlar dengeli temsil edilsin):\n" + "\n".join(lines) + "\n")


def _item_scope(byname, subject, grade_label, topics):
    """Seçilen kazanımlar belirliyse, başka kazanıma ait bilgi-bankası kalıpları dışarıda bırakılır."""
    try:
        from . import curriculum as _cu
        g = next((c for c in str(grade_label) if c.isdigit()), "")
        txt = str(topics or "")
        sel = set()
        for _u, its in _cu.units(g, subject):
            sel |= {it for it in its if it and it in txt}
        if not sel:
            return byname
        keep = {k: f for k, f in byname.items() if getattr(f, "ITEM", None) is None or f.ITEM in sel}
        return keep or byname
    except Exception:
        return byname


def _dl_filter(byname, dl, subject, grade_label, topics):
    """Zorluğa yakın (±1) kalıpları tutar; ama hiçbir alt konu/kazanım ve çeşitlilik zorluk yüzünden boşalmaz:
    her alt konuda en az 2, toplamda en az 6 kalıp (zorluğa en yakınlar) kalır."""
    if not dl or not byname:
        return byname
    dist = lambda k: abs(_DIFF_OF.get(k, 3) - dl)
    keep = {k for k in byname if dist(k) <= 1 or (k in _GV_VIS and dist(k) <= 2)}  # şekilli geometri aileleri bir kademe fazla toleranslı
    items = _topic_items(subject, grade_label, topics)
    groups = {}
    if len(items) >= 2:
        for k, f in byname.items():
            groups.setdefault(_fam_item(k, f, subject, items), []).append(k)
    else:
        groups = {0: list(byname)}
    for _g, ks in groups.items():
        have = [k for k in ks if k in keep]
        if len(have) < 2:
            for k in sorted([k for k in ks if k not in keep], key=lambda k: (dist(k), random.random()))[:2 - len(have)]:
                keep.add(k)
    if len(keep) < 6:
        for k in sorted([k for k in byname if k not in keep], key=lambda k: (dist(k), random.random()))[:6 - len(keep)]:
            keep.add(k)
    return {k: v for k, v in byname.items() if k in keep}


def _fam_of(q):
    return str(q.get("tpl") or q.get("_sty") or _style_key(q))


def _greedy_fill(qs_, cands, n, hsets, seen_, allow_hist=False, allow_seen=False, need_ready=False, items=None):
    """Eksik soruları, aynı kalıptan çok soru girmeyecek ve geçmişe en az benzeyecek biçimde tek tek seçerek tamamlar.
    Önce her kalıptan en çok 2 soru, olmazsa sınır kalkar; aday sırası: (aynı kalıp sayısı, geçmişe benzerlik)."""
    from collections import Counter
    cnt = Counter(_fam_of(q) for q in qs_)
    icn = Counter(_q_item(q, items) for q in qs_) if items else Counter()
    have = [_qwords(q) for q in qs_]
    sigs = {(q.get("question"), tuple((q.get("options") or {}).values())) for q in qs_}
    pool = list(cands)
    for cap in ((2, 3, 99) if (allow_hist or allow_seen) else (2, 3, 4)):  # sınırsız kalıp yalnızca son çare kademesinde; önce başka kalıplar (geçmişe benzese de) denenir
        while len(qs_) < n:
            best, bk = None, None
            for q in pool:
                f = _fam_of(q)
                if cnt[f] >= cap:
                    continue
                if need_ready and not (q.get("vfd") or q.get("local") or q.get("tpl") or q.get("pool")):
                    continue
                w = _qwords(q)
                if allow_hist:  # son çare: yalnızca birebir aynı soru (metin + şıklar) engellenir; sayıları farklı hazır kalıp örnekleri geçerlidir
                    if (q.get("question"), tuple((q.get("options") or {}).values())) in sigs:
                        continue
                elif any(h and w and len(h & w) / len(h | w) > 0.85 for h in have):
                    continue
                s_in = _stem(q) in seen_
                if s_in and not allow_seen:
                    continue
                ms = _hist_maxsim(q, hsets)
                if ms > 0.5 and not allow_hist:
                    continue
                ik = icn[_q_item(q, items)] if items else 0
                gp = 0
                if q.get("subject") == "Matematik" and not q.get("shape") and (_GEO_STRICT.search(f"{q.get('topic', '')} {str(q.get('question', ''))[:90]}") or (items and re.search(r"geometri|açı|çokgen|çember|çevre|alan|inşa|çizim|doğru|ışın", str(_q_item(q, items)), re.I))):
                    gp = 1  # geometri: görselli (şekilli) sorular önce seçilsin
                k = (ik, gp, cnt[f], s_in, round(ms, 1))
                if bk is None or k < bk:
                    best, bk = q, k
            if best is None:
                break
            qs_.append(best)
            sigs.add((best.get("question"), tuple((best.get("options") or {}).values())))
            pool.remove(best)
            cnt[_fam_of(best)] += 1
            if items:
                icn[_q_item(best, items)] += 1
            have.append(_qwords(best))
    return qs_


def _hist_similar(q, sets, thr=0.5):
    """Soru, önceki sınavlardaki bir soruyla (rakam/harf/şık farkı hariç) aynı mı? Jaccard > thr -> True."""
    try:
        w, n = _hist_parts(q)
        if len(w) < 4 or not sets:
            return False
        for h in sets:
            if h and _hist_sim1(w, n, h) > thr:
                return True
    except Exception:
        return False
    return False


def generate_mc(plan, grade_label, difficulty, scope_label, avoid=None, focus="", on_progress=None, use_bank=True, deposit=True, keys=None, verify=False, count=True, like="", _nb=False):
    """plan: [{subject, n, topics}] -> (questions, errors).
    Her ders BAĞIMSIZ ilerler (başka dersi beklemez): bankadan al -> paralel üret -> eksik kaldıkça yeniden tamamla
    (turlar ilerledikçe daha çok yedek ister, çeşitlilik kuralını gevşetir, en son görselsiz moda geçer).
    Amaç: istenen sayının TAM karşılanması."""
    if not _nb and not like:
        difficulty = _bump_diff(difficulty)  # tüm derslerde seçilen kademenin bir üstü üretilir (basit sorular gelmesin)
    avoid = {k: list(v) for k, v in (avoid or {}).items()}
    gk, mk = (keys if keys else load_keys()) if not demo_mode() else ([], [])
    no_keys = not demo_mode() and not gk and not mk and not extra_keys()
    bank_ok = use_bank and not demo_mode() and not focus.strip()
    dep_ok = deposit and not demo_mode() and not focus.strip()
    seen = set(s for v in avoid.values() for s in v)
    dl = 0 if like else _diff_level(difficulty)
    hist = _hist_sets({p.get('subject') for p in plan}) if (not demo_mode() and not like) else {}
    try:
        from . import store as _stx
        hsty = _stx.recent_styles() if (not demo_mode() and not like) else {}
    except Exception:
        hsty = {}
    seen_lock = threading.Lock()
    prog_lock = threading.Lock()
    prog = {"done": 0, "total": max(1, sum(-(-p["n"] // CHUNK) for p in plan))}
    state = [{"p": p, "qs": [], "reserve": [], "over": [], "fails": 0, "err": None, "bank_stems": [], "styles": set(),
              "items": _topic_items(p.get("subject"), grade_label, p.get("topics", "")), "icnt": {}} for p in plan]
    for _s in state:  # alt konu/kazanım başına üst sınır: soru sayısı / konu sayısı (+1)
        _s["icap"] = max(2, -(-p_n // len(_s["items"])) + 1) if (_s["items"] and (p_n := _s["p"]["n"])) else 99
    T0 = time.time()
    E = ThreadPoolExecutor(max_workers=WORKERS)

    def take(st_, batch, relax=False):
        p, qs_, res_ = st_["p"], st_["qs"], st_["reserve"]
        with seen_lock:
            for i, q in enumerate(batch):
                if len(qs_) >= p["n"]:
                    st_["over"].extend(batch[i:])  # fazlalık atılmaz, bankaya gider
                    break
                s = _stem(q)
                if not s:
                    continue
                if not _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label):
                    continue  # seçilen konu dışı: yedeğe bile alınmaz
                if dl and q.get("tpl") and abs(_DIFF_OF.get(q["tpl"], 3) - dl) > 1:
                    res_.append(q)  # hazır kalıp seçilen zorluk kademesine uymuyor: yalnız yapay zekâ yetmezse son çare olarak kullanılır
                    continue
                if not like and _negative_stem(q):
                    if q.get("seed") or q.get("local"):
                        res_.append(q)  # hazır soru: yalnızca son çare
                    continue  # olumsuz kök ('hangisi yanlıştır') yok
                sk = _style_key(q)
                q["_sty"] = sk
                if not relax and not like and sk and (sk in st_["styles"] or sk in hsty.get(p.get("subject"), ())):
                    res_.append(q)  # aynı tarz: aynı sınavda ya da son sınavlarda çıkmış; yalnızca son çare
                    continue
                ix = _q_item(q, st_["items"]) if st_["items"] else -1
                if not relax and not like and ix >= 0 and st_["icnt"].get(ix, 0) >= st_["icap"]:
                    res_.append(q)  # aynı kazanım/alt konudan yeterince soru var: yalnızca son çare
                    continue
                if s in seen:
                    res_.append(q)
                elif not like and _hist_similar(q, hist.get(p.get("subject"))):
                    res_.append(q)  # önceki sınavlarda gördüğün bir sorunun aynısı (yalnız sayı/harf farkı): son çare yedeği
                elif (_relaxed_ok(q, qs_) if relax else accept_diverse(q, qs_, p["n"])):
                    seen.add(s)
                    qs_.append(q)
                    st_["styles"].add(sk)
                    if ix >= 0:
                        st_["icnt"][ix] = st_["icnt"].get(ix, 0) + 1
                else:
                    res_.append(q)

    def work_chunk(st_, c_ask, use_focus, extra_avoid, plain):
        p = st_["p"]
        subj, idx = p["subject"], next(_UID)
        try:
            if demo_mode():
                return _demo_mc(subj, c_ask, p["topics"]), None
            av = list(avoid.get(subj, [])) + list(extra_avoid)
            prompt = mc_prompt(grade_label, subj, c_ask, p["topics"], difficulty, scope_label, av, focus if use_focus else "", plain=plain, like=like)

            def validate(items):
                out = []
                for q in items:
                    try:
                        x = _norm_q(q, subj)
                    except Exception:  # tek bozuk soru tüm üretimi bozmasın
                        x = None
                    if x:
                        out.append(x)
                        qstat(subj, "üretildi")
                    else:
                        try:
                            rs = diagnose(q, subj)
                        except Exception:
                            rs = "yakalanmadı"
                        qstat(subj, "elendi: " + ("diğer kural" if rs in ("yakalanmadı", "kural_red") else rs.replace("_", " ")))
                return out

            qs, err = _ask_questions(prompt, gk, mk, idx, validate, reasoning=GEN_REASONING.get(subj))
            if (verify or subj in STRICT_MODE) and qs and (not VERIFY_SUBJECTS or subj in VERIFY_SUBJECTS or subj in STRICT_VERIFY) and (gk or mk or extra_keys()):  # yalnız arka plan (banka/havuz) dolumunda
                try:
                    if subj in STRICT_MODE:
                        qs = verify_strict(qs, gk, mk, offset=idx, fast=True)  # SIKI MOD: iki bağımsız çözücü aynı şıkkı vermeli
                    else:
                        qs = verify_questions(qs, gk, mk, offset=idx)
                except Exception:  # doğrulayıcı hatası üretimi engellemesin
                    if subj in STRICT_MODE:
                        qs = []
                if subj in FAIL_CLOSED_SUBJECTS:  # Matematik: bağımsız modelce doğrulanmayan soru ASLA sınava girmez (hatalı soru yerine kodla hesaplanan soru gelir)
                    _ok = [q for q in qs if q.get("vfd") or q.get("local") or q.get("tpl") or q.get("pool")]
                    st_.setdefault("unv", []).extend([q for q in qs if q not in _ok])  # son çare yedeği: doğrulanamayanlar (yalnızca soru sayısı tamamlanamazsa)
                    qs = _ok
            for _q in qs:
                _q.pop("_gp", None)
            return qs, (err if not qs else None)
        except Exception as e:
            return [], f"{type(e).__name__}: {str(e)[:80]}"

    def run_item(st_):
        p = st_["p"]
        subj, n = p["subject"], p["n"]
        try:
            if bank_ok:  # 00) beğenilen sorulara benzer havuzdan (en çok %40)
                try:
                    from . import store
                    lp = [q for q in store.lpool_peek(subj, grade_label, difficulty, p.get("topics", ""), limit=n) if _stem(q) and _stem(q) not in seen]
                    take(st_, lp[:max(1, int(n * 0.4))])
                    store.lpool_remove([_stem(q) for q in st_["qs"]])
                except Exception:
                    pass
            if not demo_mode() and not like and os.environ.get("DENEMEMATIK_NO_FACTORY") != "1" and subj in ("Sosyal Bilgiler", "Türkçe", "Din Kültürü ve Ahlak Bilgisi", "Matematik", "Fen Bilimleri"):  # 00b) onaylı çekirdek + kodla hesaplanan sorular (API'siz)
                try:  # çekirdek/hesaplanan soruların toplam payı en çok ~%25 (çoğunluk yapay zekâ); kaynaklar sırayla, dönüşümlü
                    fb = max(1 if n >= 4 else 0, int(n * (0.6 if subj in STRICT_MODE else (0.5 if str(grade_label)[:1] == "5" else 0.25))))
                    if subj == "Matematik" and str(grade_label)[:1] == "5":
                        try:  # yalnızca geometri temaları seçiliyse: şekilli ve kodla doğrulanmış sorular ağırlıkta (yapay zekâ şekilsiz/ilgisiz soru getirmesin)
                            _su = _selected_units(grade_label, subj, p.get("topics", "")) or set()
                            if _su and all(re.search(r"Geometrik", str(x)) for x in _su):
                                fb = max(fb, int(n * 0.85 + 0.5))
                        except Exception:
                            pass  # Matematikte kodla hesaplanan soru payı yüksek (hatasız); AI soruları yalnızca doğrulanırsa girer
                    srcs = [lambda k: seed_questions(subj, grade_label, p.get("topics", ""), limit=k, seen=seen),
                            lambda k: local_questions(subj, grade_label, k, p.get("topics", ""), seen=seen)]
                    if subj == "Matematik":
                        srcs.append(lambda k: math_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    if subj == "Fen Bilimleri":
                        srcs.append(lambda k: fen_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    if subj == "Sosyal Bilgiler":
                        srcs.append(lambda k: sosyal_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    if subj == "Türkçe":
                        srcs.append(lambda k: turkce_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    if subj == "İngilizce":
                        srcs.append(lambda k: eng_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    if subj == "Din Kültürü ve Ahlak Bilgisi":
                        srcs.append(lambda k: din_questions(grade_label, k, p.get("topics", ""), seen=seen, dl=dl))
                    random.shuffle(srcs)
                    got_f = 0
                    for _r in range(max(1, fb)):
                        for src in srcs:
                            if got_f >= fb or len(st_["qs"]) >= n:
                                break
                            before = len(st_["qs"])
                            take(st_, src(1))
                            got_f += len(st_["qs"]) - before
                except Exception:
                    pass
            if subj == "Matematik" and not demo_mode() and not like and os.environ.get("DENEMEMATIK_NO_POOL") != "1":  # 00bb) model yazarlı, kod hesaplı şablonlar (en çok %40)
                try:
                    take(st_, tpl_questions(grade_label, min(max(1, int(n * 0.4)), n - len(st_["qs"])), p.get("topics", ""), seen=seen))
                except Exception:
                    pass
            if not demo_mode() and not like and os.environ.get("DENEMEMATIK_NO_POOL") != "1":  # 00c) önceden üretilip doğrulanmış havuz (yapay zekâ kaynaklı; API'siz)
                try:
                    _need = n - len(st_["qs"])
                    take(st_, pool_questions(subj, grade_label, p.get("topics", ""), _need, seen=seen, difficulty=difficulty, extra=2 * _need))  # fazlası yedeğe: sınav doldururken aynı kalıp yığılmasın
                except Exception:
                    pass
            if bank_ok:  # 0) bankadan doldur
                try:
                    from . import store
                    key = bank_key_for(p, grade_label, difficulty)
                    fresh, purge = [], []
                    for q in store.bank_peek(key, n * 2 + 4):
                        s = _stem(q)
                        if not s or s in seen:  # daha önce çözülmüş: bankadan da temizle
                            purge.append(s)
                        else:
                            fresh.append(q)
                    take(st_, fresh)
                    st_["reserve"], st_["over"] = [], []  # elenenler bankada kalır
                    got = [_stem(q) for q in st_["qs"]]
                    store.bank_remove(key, got + purge)
                    st_["bank_stems"] = got
                except Exception:
                    pass  # banka hatası üretimi engellemesin
            if bank_ok and len(st_["qs"]) < n:  # 0b) aynı ders/sınıf/zorlukta konusu örtüşen diğer banka kapsamlarından tamamla
                try:
                    from . import store
                    have = {_stem(q) for q in st_["qs"]}
                    sim = [(k_, q) for k_, q in store.bank_peek_similar(grade_label, subj, difficulty, p.get("topics", ""), limit=(n - len(st_["qs"])) * 3 + 6,
                                                                        exclude_key=bank_key_for(p, grade_label, difficulty))
                           if _stem(q) and _stem(q) not in seen and _stem(q) not in have]
                    take(st_, [q for _k, q in sim])
                    taken = {_stem(q) for q in st_["qs"]} - have
                    for k_ in {k for k, q in sim if _stem(q) in taken}:
                        store.bank_remove(k_, [_stem(q) for k, q in sim if k == k_ and _stem(q) in taken])
                except Exception:
                    pass
            for rnd in range(MAX_ROUNDS + 1):
                need = n - len(st_["qs"])
                if need <= 0 or (no_keys and not demo_mode()):
                    break
                _fast5 = str(grade_label)[:1] == "5" and not like and not focus.strip() and not demo_mode()
                if _fast5 and rnd > 0:
                    break  # 5. sınıf: tek hızlı yapay zekâ turu; eksik kalanı hatasız hazır kalıplar doldurur
                if rnd > 0 and (time.time() - T0 > GEN_BUDGET or st_["fails"] >= 3):
                    break
                sizes, left = [], need
                while left > 0:
                    c = min(CHUNK, left)
                    sizes.append(c)
                    left -= c
                extra_av = [_stem(q) for q in st_["qs"]] + st_["bank_stems"]
                futs = [E.submit(work_chunk, st_, c + EXTRA_FIRST + min(rnd, 3) + (2 if subj in FAIL_CLOSED_SUBJECTS else 0), rnd == 0 and k == 0, extra_av, rnd >= 3) for k, c in enumerate(sizes)]
                before = len(st_["qs"])
                _t_wait = time.time()
                for f in futs:
                    try:
                        qs, err = f.result(timeout=max(0.5, AI5_WAIT - (time.time() - _t_wait))) if _fast5 else f.result()
                    except Exception:  # süre doldu: gecikeni bekleme, hazır kalıplar tamamlasın
                        st_["err"] = st_.get("err") or "yapay zekâ gecikti"
                        continue
                    if err:
                        st_["err"] = err
                    take(st_, qs, relax=rnd >= 2)
                    if on_progress:
                        with prog_lock:
                            prog["done"] += 1
                            on_progress(min(prog["done"], prog["total"]), prog["total"], subj)
                st_["fails"] = 0 if len(st_["qs"]) > before else st_["fails"] + 1
        except Exception as e:
            st_["err"] = f"{type(e).__name__}: {str(e)[:80]}"

    try:
        with ThreadPoolExecutor(max_workers=max(1, len(state))) as SX:
            list(SX.map(run_item, state))
    finally:
        E.shutdown(wait=False)
    errors, questions = [], []
    for st_ in state:
        p, qs_ = st_["p"], st_["qs"]
        _hs = hist.get(p.get("subject")) if not like else None
        if len(qs_) < p["n"] and st_["reserve"]:  # son çare 1: elenenlerden; aynı kalıp en çok 2, geçmişe benzeyen ve önceki sınav sorusu yok
            _greedy_fill(qs_, st_["reserve"] + [q for q in st_["over"] if q not in st_["reserve"]], p["n"], _hs, seen, items=st_.get("items"))
        if len(qs_) < p["n"] and not like:  # 2b. kademe = hazır kalıplardan (kodla hesaplanan, hatasız) önceki sınavlara bakmadan; yalnızca bu sınavdaki kopyalar hariç
            _fn = {"Matematik": math_questions, "Fen Bilimleri": fen_questions, "Sosyal Bilgiler": sosyal_questions, "Türkçe": turkce_questions, "Din Kültürü ve Ahlak Bilgisi": din_questions, "İngilizce": eng_questions}.get(p.get("subject"))
            if _fn:
                try:
                    inx = {_stem(q) for q in qs_}
                    _cand = []
                    for _dd in ((dl, 0) if dl else (0,)):  # önce seçilen zorluğa uyanlar, yetmezse zorluk gözetmeden
                        for _rep in range(6):  # her çağrı kalıp başına bir örnek verir; çeşitlilik için birkaç tur
                            for q in _fn(grade_label, (p["n"] - len(qs_)) * 3, p.get("topics", ""), seen=inx, dl=_dd):
                                if _stem(q) in inx or not _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label):
                                    continue
                                inx.add(_stem(q))
                                _cand.append(q)
                        _greedy_fill(qs_, _cand, p["n"], _hs, seen, items=st_.get("items"))
                        if len(qs_) >= p["n"]:
                            break
                    if len(qs_) < p["n"]:  # hâlâ eksikse: geçmişe benzeyen taze örnekler dahil
                        _greedy_fill(qs_, _cand, p["n"], _hs, seen, allow_hist=True, allow_seen=True, items=st_.get("items"))
                    if len(qs_) < p["n"]:  # son: rezervdeki daha önce görülmüş hazır sorular
                        _greedy_fill(qs_, st_["reserve"], p["n"], _hs, seen, allow_hist=True, allow_seen=True, need_ready=True, items=st_.get("items"))
                except Exception:
                    pass
        if len(qs_) < p["n"] and st_.get("unv") and p.get("subject") not in STRICT_MODE:  # 3. kademe (sıkı modda YOK: doğrulanmamış soru girmez) = doğrulayıcıya ulaşılamayan ama diğer tüm kontrolleri geçen sorular (ünite/olumsuz kök/tutarlılık)
            have = [_qwords(q) for q in qs_]
            for q in st_["unv"]:
                if len(qs_) >= p["n"]:
                    break
                w = _qwords(q)
                if any(h and w and len(h & w) / len(h | w) > 0.85 for h in have):
                    continue
                if not _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label) or _negative_stem(q):
                    continue
                qs_.append(q)
                have.append(w)
                st_["used_unv"] = st_.get("used_unv", 0) + 1
        if st_.get("used_unv"):
            errors.append(f"ℹ️ {p['subject']}: {st_['used_unv']} soru ikinci model tarafından doğrulanamadı (yoğunluk); şüpheli görürsen 🚩 ile bildir")
        if len(qs_) < p["n"]:
            errors.append(f"{p['subject']}: {len(qs_)}/{p['n']} soru hazırlanabildi (yoğunluk nedeniyle); tekrar denersen tamamlanır" if _quota_like(st_.get("err")) else
                          f"{p['subject']}: {len(qs_)}/{p['n']} soru üretilebildi" + (f" ({st_['err'][:90]})" if st_.get("err") and not qs_ else ""))
        try:  # son güvenlik kapısı: hangi kaynaktan gelmiş olursa olsun seçilen konu/ünite dışındaki soru sınava girmez; eksik kalırsa yerel sorularla tamamlanır
            _ok = [q for q in qs_ if _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label)]
            if len(_ok) < len(qs_) or len(_ok) < p["n"]:
                _hv = {_stem(q) for q in _ok} | set(seen)
                if len(_ok) < p["n"] and p.get("subject") in ("Matematik", "Fen Bilimleri", "Sosyal Bilgiler", "Din Kültürü ve Ahlak Bilgisi", "Türkçe", "İngilizce"):
                    _fn = {"Matematik": math_questions, "Fen Bilimleri": fen_questions, "Sosyal Bilgiler": sosyal_questions, "Din Kültürü ve Ahlak Bilgisi": din_questions, "Türkçe": turkce_questions, "İngilizce": eng_questions}[p["subject"]]
                    for q in _fn(grade_label, (p["n"] - len(_ok)) * 2, p.get("topics", ""), seen=_hv, dl=dl) or []:
                        if len(_ok) >= p["n"]:
                            break
                        if _stem(q) not in _hv and _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label):
                            _ok.append(q)
                            _hv.add(_stem(q))
                qs_ = _ok
        except Exception:
            pass
        questions += qs_[:p["n"]]
    if dep_ok:  # artan sağlam soruları bankaya ekle
        try:
            from . import store
            for st_ in state:
                p = st_["p"]
                used = {_stem(q) for q in st_["qs"][:p["n"]]}
                extra = [q for q in st_["over"] + st_["reserve"] if _stem(q) and _stem(q) not in used and _stem(q) not in seen
                         and q.get("vfd") and _on_topic(q, p.get("topics", ""), p.get("subject"), grade_label)]  # bankaya yalnızca ikinci modelle doğrulanmış sorular girer
                if extra:
                    store.bank_put(bank_key_for(p, grade_label, difficulty), _bank_meta(p, grade_label, difficulty), extra)
        except Exception:
            pass
    if no_keys and not questions:
        return [], ["API anahtarı bulunamadı"]
    _spread_answers(questions)
    _balance_letters(questions)
    for i, q in enumerate(questions, 1):
        q["id"] = i
    if count:
        try:
            store.count_generated(len(questions))
        except Exception:
            pass
    return questions, errors


_FILLING = set()
_FILL_LOCK = threading.Lock()


def bank_topup_async(plan, grade_label, difficulty, scope_label, used_qs=()):
    """Sınav üretildikten sonra arka planda, bu kapsamın bankasını bir sonraki sınav için tamamlar (en fazla bir sınav boyu).
    Ana iş parçacığında çağrılır; anahtarlar ve kaçınılacak soru listesi burada alınır, işi daemon iş parçacığı yapar."""
    difficulty = _bump_diff(difficulty)  # generate_mc ile aynı (bir üst) kademe: banka anahtarları uyuşsun
    if demo_mode() or not plan:
        return False
    try:
        from . import store
        gk, mk = load_keys()
        if not gk and not mk and not extra_keys():
            return False
        avoid = {k: list(v) for k, v in store.recent_stems().items()}
        for q in used_qs:
            avoid.setdefault(q.get("subject", "Genel"), []).append(_stem(q))
        todo = []
        for p in plan:
            key = bank_key_for(p, grade_label, difficulty)
            need = min(p["n"] * 2, 12) - store.bank_count(key)  # bankada en az iki sınavlık hazır soru dursun
            with _FILL_LOCK:
                if need > 0 and key not in _FILLING:
                    _FILLING.add(key)
                    todo.append((key, {**p, "n": need}))
        if not todo:
            return False
    except Exception:
        return False

    def run():
        try:
            sub = [p for _, p in todo]
            qs, _e = generate_mc(sub, grade_label, difficulty, scope_label, avoid=avoid, use_bank=False, deposit=False, keys=(gk, mk), verify=True, count=False, _nb=True)
            for key, p in todo:
                mine = [q for q in qs if q.get("subject") == p["subject"]]
                store.bank_put(key, _bank_meta(p, grade_label, difficulty), mine)
        except Exception:
            pass
        finally:
            with _FILL_LOCK:
                for key, _p in todo:
                    _FILLING.discard(key)

    threading.Thread(target=run, daemon=True).start()
    return True


_GUIDE = {
    "eksik_veri": "Soru metninin atıf yaptığı şema/tablo/metin/veri MUTLAKA soruda verilmiş olsun; 'aşağıdaki veri' deyip veri verme.",
    "ölçü_aleti": "Ölçü aleti değerleri çizgiye tam oturan okunabilir sayılar olsun; 'kaç gösterir' cevabı şekildeki değerle birebir aynı olsun; metindeki kuvvet değerleri şekilde de bulunsun.",
    "grafik_şık": "Şıklar grafikteki/tablodaki kategorilerden oluşsun (olmayan grup yazma); 'en çok/en az' sorusunda doğru şık gerçekten uç değer olsun.",
    "sızıntı": "Doğru cevabı soru metninde ya da görselde aynen verme.",
    "kural_red": "Metin, görsel ve şıklar birbiriyle birebir uyumlu ve mantıksal olarak tutarlı olsun; çözümü olmayan/belirsiz soru yazma.",
}


def diagnose(q, subject=None):
    """Bildirilen sorunun hangi otomatik kurala takıldığını söyler ('yakalanmadı' = kurallar kaçırdı)."""
    try:
        opts = q.get("options") or {}
        ans = str(q.get("answer", "")).strip().upper()[:1]
        qt, pas, sh = str(q.get("question", "")), str(q.get("passage") or ""), q.get("shape")
        if not sh and _dangling_ref(qt, pas, opts):
            return "eksik_veri"
        if sh and not _complete_ok(qt, pas, opts, sh):
            return "eksik_veri"
        if not _instrument_ok(sh, qt, pas, opts, ans):
            return "ölçü_aleti"
        if not _chart_answer_ok(sh, qt, opts, ans):
            return "grafik_şık"
        import copy
        if _norm_q(copy.deepcopy(q), subject or q.get("subject")) is None:
            return "kural_red"
    except Exception:
        pass
    return "yakalanmadı"


def golden(subject, grade_label):
    """Öğrencinin beğendiği (altın) soruların en fazla ikisini kalite örneği olarak istemine ekler."""
    try:
        import random as _rnd
        from . import store
        L = [x["q"] for x in store.liked()[-30:] if x.get("grade_label") == grade_label and x["q"].get("subject") == subject]
        if not L:
            return ""
        out = "\n⭐ KALİTE ÖRNEKLERİ (öğrencinin beğendiği sorular; bu netlikte, bu zorlukta ve metin-şık-görsel uyumunda yaz, KOPYALAMA):"
        for q in _rnd.sample(L, min(2, len(L))):
            o = " | ".join(f"{k}) {v}" for k, v in (q.get("options") or {}).items()) if isinstance(q.get("options"), dict) else ""
            g = f" [görsel: {q['shape'].get('type')}]" if isinstance(q.get("shape"), dict) else ""
            out += f"\n- {str(q.get('passage') or '')[:300]} {str(q.get('question', ''))[:400]}{g} ŞIKLAR: {o[:300]} DOĞRU: {q.get('answer')}"
        return out
    except Exception:
        return ""


def lessons(subject):
    """Bu dersteki son hata bildirimlerinden üretim istemine eklenecek 'kaçın' notu."""
    try:
        from . import store
        R = store.reports(subject, 40)
    except Exception:
        return ""
    if not R:
        return ""
    cnt = {}
    for x in R:
        cnt[x.get("reason")] = cnt.get(x.get("reason"), 0) + 1
    lines = [_GUIDE[k] for k, _v in sorted(cnt.items(), key=lambda kv: -kv[1]) if k in _GUIDE][:3]
    ex = [x["head"] for x in R if x.get("reason") == "yakalanmadı"][-2:]
    out = ""
    if lines:
        out += "\n⚠ BU DERSTE KULLANICI HATA BİLDİRDİ, KAÇIN: " + " ".join(lines)
    if ex:
        out += "\n⚠ Şu tarzda sorular hatalı bulundu, benzerini yazma: " + " || ".join(ex)
    return out


def verify_bank(gk, mk, max_q=240, batch=12, subjects=None):
    """Bilgi bankası girdilerini (elle yazılmış) bağımsız yapay zekâ ile çözdürür: model 'tek soru' ve 'doğru ifade' sorularında bizim cevabımızı bulamazsa
    girdi devre dışı bırakılır (bad_facts) ve rapora yazılır. Doğrulananlar bir daha sorulmaz; her çalışmada en fazla max_q soru kullanılır.
    -> {'checked': n, 'bad': [...], 'left': kalan doğrulanmamış girdi}"""
    from . import store
    done = store._load("bank_verified.json", {})
    _rok, _rbad = _bank_checks()
    for _k in _rok:
        done.setdefault(_k, "ok")
    for _k in _rbad:
        done.setdefault(_k, "bad")
    todo = []
    for nm, sj in (("_FFACTS", "Fen Bilimleri"), ("_SFACTS", "Sosyal Bilgiler"), ("_TFACTS", "Türkçe"), ("_EFACTS", "İngilizce"), ("_DFACTS", "Din Kültürü ve Ahlak Bilgisi")):
        if subjects and sj not in subjects:
            continue
        for unit, F in globals().get(nm, {}).items():
            for i, f in enumerate(F):
                key = f"{unit}|{f[0]}|{f[2]}"
                if key not in done:
                    todo.append((sj, unit, F, i, key))
    random.shuffle(todo)
    left = len(todo)
    qs, meta = [], []
    for sj, unit, F, i, key in todo:
        if len(qs) + 2 > max_q:
            break
        lab, q, c, wr, tt, ff = F[i]
        o = [c] + list(wr[:3])
        random.shuffle(o)
        qs.append({"subject": sj, "question": q, "options": dict(zip("ABCD", o)), "answer": "ABCD"[o.index(c)], "_k": key})
        oth = [F[j][5] for j in range(len(F)) if j != i]
        random.shuffle(oth)
        o2 = [tt, ff] + oth[:2]
        if len(o2) == 4:
            random.shuffle(o2)
            qs.append({"subject": sj, "question": "Aşağıdaki ifadelerden hangisi doğrudur?" if sj != "İngilizce" else "Which sentence is correct?", "options": dict(zip("ABCD", o2)), "answer": "ABCD"[o2.index(tt)], "_k": key})
    bad, checked = set(), 0
    status = {}  # girdi anahtarı -> {'ok','bad','unv'} sayacı
    for b0 in range(0, len(qs), batch):
        chunk = qs[b0:b0 + batch]
        try:
            kept = verify_questions([dict(q) for q in chunk], gk, mk, offset=b0)
        except Exception:
            continue
        kmap = {(q["question"], q["answer"], tuple(sorted(q["options"].items()))): bool(q.get("vfd")) for q in kept}
        for q in chunk:
            kk = (q["question"], q["answer"], tuple(sorted(q["options"].items())))
            s = status.setdefault(q["_k"], {"ok": 0, "bad": 0, "unv": 0})
            if kk not in kmap:
                s["bad"] += 1
            elif kmap[kk]:
                s["ok"] += 1
            else:
                s["unv"] += 1
        checked += len(chunk)
    for k, s in status.items():
        if s["bad"]:
            done[k] = "bad"
            bad.add(k)
        elif s["ok"] and not s["unv"]:
            done[k] = "ok"
    store._save("bank_verified.json", done)
    if bad:
        bf = store._load("bad_facts.json", [])
        for k in sorted(bad):
            if k not in bf:
                bf.append(k)
        store._save("bad_facts.json", bf[-1500:])
        sus = store._load("bank_suspects.json", [])
        store._save("bank_suspects.json", sorted(set(sus) | bad))
    return {"checked": checked, "bad": sorted(bad), "left": max(0, left - len(qs) // 2)}



def bank_integrity():
    """Bilgi bankası girdilerinin iç tutarlılığı (doğru şık yanlışlarda yok, >=3 farklı yanlış, doğru/yanlış ifade farklı, kopya yok)."""
    out = []
    for nm, sj in (("_FFACTS", "Fen"), ("_SFACTS", "Sosyal"), ("_TFACTS", "Türkçe"), ("_EFACTS", "İngilizce"), ("_DFACTS", "Din")):
        for unit, F in globals().get(nm, {}).items():
            seen = set()
            for f in F:
                try:
                    lab, q, c, wr, tt, ff = f
                except Exception:
                    out.append((sj, unit, "?", "girdi biçimi bozuk"))
                    continue
                norm = lambda s: _alnum(str(s))
                ws = [norm(w) for w in wr]
                if len(wr) < 3:
                    out.append((sj, unit, lab, "3'ten az yanlış şık"))
                if len(set(ws)) < len(ws):
                    out.append((sj, unit, lab, "yanlış şıklar birbirinin aynısı"))
                if norm(c) in ws:
                    out.append((sj, unit, lab, "doğru cevap yanlış şıklar arasında"))
                if norm(tt) == norm(ff):
                    out.append((sj, unit, lab, "doğru ve yanlış ifade aynı"))
                if norm(c) and norm(c) in {norm(w) for w in wr}:
                    out.append((sj, unit, lab, "doğru=yanlış"))
                if (norm(q), norm(c)) in seen:
                    out.append((sj, unit, lab, "tekrarlanan girdi"))
                seen.add((norm(q), norm(c)))
    return out


def self_audit(n=10, subjects=None, grade="5"):
    """Tüm hazır soru kalıplarından örnek üretip denetler: hata fırlatma, aşırı red, şık/çözüm tutarsızlığı, bilgi bankası bütünlüğü.
    Bilgi bankası kusurlu girdileri otomatik devre dışı bırakır. -> {'ts','families','problems':[...],'auto':[...]}"""
    import copy
    t0 = time.time()
    REG = {"Matematik": [(f, k) for f, k, g in _MF_GENS if int(grade) in g], "Fen Bilimleri": _FF_GENS, "Sosyal Bilgiler": _SF_GENS,
           "Türkçe": _TF_GENS, "Din Kültürü ve Ahlak Bilgisi": _DF_GENS, "İngilizce": _EF_GENS}
    prob, fam, auto = [], 0, []
    for sj, reg in REG.items():
        if subjects and sj not in subjects:
            continue
        for f, _kw in reg:
            fam += 1
            c = {"ok": 0, "none": 0, "rej": 0, "exc": 0}
            ex = ""
            for _ in range(n):
                try:
                    r = f(sj)
                except Exception as e:
                    c["exc"] += 1
                    ex = ex or repr(e)[:120]
                    continue
                if not r:
                    c["none"] += 1
                    continue
                try:
                    qn = _norm_q(copy.deepcopy(r), sj)
                except Exception as e:
                    c["exc"] += 1
                    ex = ex or repr(e)[:120]
                    continue
                if not qn:
                    c["rej"] += 1
                    ex = ex or str(r.get("question", ""))[:100]
                    continue
                c["ok"] += 1
                o = qn["options"]
                if len({_alnum(re.sub(r"(?<![\w)])[-−–]\s*(?=\d)", "eksi ", str(v))) for v in o.values()}) < 4 or qn["answer"] not in o:
                    prob.append({"ders": sj, "kalıp": f.__name__, "sorun": "şıklar/cevap tutarsız", "örnek": qn["question"][:100]})
            if c["exc"]:
                prob.append({"ders": sj, "kalıp": f.__name__, "sorun": "hata fırlatıyor", "örnek": ex})
                auto.append(f.__name__)
            elif c["ok"] < max(1, int((n - c["none"]) * 0.4)) and (n - c["none"]) > 0:
                prob.append({"ders": sj, "kalıp": f.__name__, "sorun": f"çok soru elendi ({c['ok']}/{n} geçti)", "örnek": ex})
    for sj, unit, lab, why in bank_integrity():
        prob.append({"ders": sj, "kalıp": "bilgi bankası", "sorun": why, "örnek": f"{unit} / {lab}"})
    try:
        from . import store
        if auto:
            bt = store._load("bad_tpls.json", {})
            for nm in auto:
                e = bt.setdefault(nm, {"n": 0, "why": []})
                e["why"] = (e["why"] + ["otomatik denetim: hata fırlattı"])[-5:]
                e["ex"] = "otomatik denetim"
            store._save("bad_tpls.json", bt)
        res = {"ts": int(time.time()), "families": fam, "problems": prob[:200], "auto": auto, "secs": round(time.time() - t0, 1), "n": n}
        store.audit_save(res)
        return res
    except Exception:
        return {"ts": int(time.time()), "families": fam, "problems": prob[:200], "auto": auto, "secs": round(time.time() - t0, 1), "n": n}



def audit_pools_async():
    """Günde bir kez: banka ve beğeni havuzunu güncel doğrulama kurallarıyla yeniden süz (API kullanmaz)."""
    try:
        from . import store
        today = str(store._today())
        if store.settings().get("audit_day") == today:
            return False
        store.save_settings(audit_day=today)
    except Exception:
        return False

    def keep(q):
        import copy
        subj = q.get("subject")
        if not subj:
            return True
        return _norm_q(copy.deepcopy(q), subj) is not None

    prof = store.current_profile()

    def run():
        store.set_thread_profile(prof)
        try:
            store.audit_pool_files(keep)
        except Exception:
            pass
    threading.Thread(target=run, daemon=True).start()
    return True


_LIKING = set()


def like_similar_async(q, grade_label, difficulty, n=2, auto=False):
    """Beğenilen soruya benzer sorular üretip havuza koyar (arka planda). Ana iş parçacığında çağrılır."""
    if demo_mode() or not isinstance(q, dict):
        return False
    try:
        from . import store
        gk, mk = load_keys()
        if not gk and not mk and not extra_keys():
            return False
        subj = q.get("subject") or "Genel"
        topics = str(q.get("kazanim") or q.get("topic") or "")
        stem = _stem(q)
        if stem in _LIKING:
            return False
        if auto:  # kotayı koru: modeller soğumadaysa ya da günlük limit dolduysa üretme
            ps = pool_status()
            if ps.get("cooling", 0) > 0 or ps.get("disabled", 0) > 0 or _FILLING or not store.like_budget_take(True):
                return False
        else:
            store.like_budget_take(False)
        _LIKING.add(stem)
        opts = " | ".join(f"{k}) {v}" for k, v in (q.get("options") or {}).items()) if isinstance(q.get("options"), dict) else ""
        ex = f"{q.get('passage') or ''} {q.get('question', '')} {opts}".strip()
        if isinstance(q.get("shape"), dict):
            ex += " [görsel: " + json.dumps({k: v for k, v in q["shape"].items() if k != "_bad"}, ensure_ascii=False)[:300] + "]"
        avoid = {k: list(v) for k, v in store.recent_stems().items()}
        avoid.setdefault(subj, []).append(stem)
    except Exception:
        return False

    prof = store.current_profile()

    def run():
        store.set_thread_profile(prof)
        try:
            plan = [{"subject": subj, "n": n, "topics": topics or subj}]
            qs, _e = generate_mc(plan, grade_label, difficulty, "Beğenilen soruya benzer", avoid=avoid, use_bank=False, deposit=False,
                                 keys=(gk, mk), verify=True, count=False, like=ex)
            mine = [x for x in qs if x.get("subject") == subj]
            store.lpool_put(subj, grade_label, difficulty, topics or subj, mine, src=stem)
        except Exception:
            pass
        finally:
            _LIKING.discard(stem)

    threading.Thread(target=run, daemon=True).start()
    return True


def _fam_fn(name):
    for G in (_FF_GENS, _SF_GENS, _TF_GENS, _DF_GENS, _EF_GENS, _MF_GENS):
        for it in G:
            if getattr(it[0], "__name__", "") == name:
                return it[0]
    return None


def like_similar_local(q, grade_label, difficulty, n=8):
    """Beğenilen soru hazır kalıptan (havuz) geldiyse: aynı kalıptan, yapay zekâ kullanmadan, farklı değerlerle benzer sorular üretip beğeni havuzuna koyar."""
    try:
        from . import store
        fam = str(q.get("fam") or "")
        subj = q.get("subject") or ""
        fn = _fam_fn(fam) if fam else None
        if not fn or not subj:
            return 0
        seen = {store._bstem(q)}
        seen_full = {str(q.get("question")) + str(q.get("options"))}
        outs = []
        for _ in range(n * 15):
            try:
                x = _norm_q(fn(subj), subj)
            except Exception:
                x = None
            if not x:
                continue
            k = str(x.get("question")) + str(x.get("options"))
            if k in seen_full:
                continue
            seen_full.add(k)
            x["vfd"] = True
            x["fam"] = fam
            outs.append(x)
            if len(outs) >= n:
                break
        topics = str(q.get("topic") or subj)
        return store.lpool_put(subj, grade_label, difficulty, topics, outs, src=store._bstem(q))
    except Exception:
        return 0


def like_refill_async(grade_label, difficulty, per_src=5, max_src=2):
    """Beğenilen soruların benzer havuzunu büyütür: havuzda en az benzeri kalan beğenilenler için 2'şer soru daha üretir."""
    try:
        from . import store
        cnt = store.lpool_per_src()
        L = [x for x in store.liked() if x.get("grade_label") == grade_label and x.get("difficulty") == difficulty
             and cnt.get(x.get("stem"), 0) < per_src and x.get("stem") not in _LIKING]
        L.sort(key=lambda x: cnt.get(x.get("stem"), 0))
        for x in L[:max_src]:
            like_similar_async(x["q"], grade_label, difficulty, auto=True)
        return bool(L)
    except Exception:
        return False


_DFILL = {"running": False, "last": 0.0}
DAILY_FILL_RUNS = 10     # günde en fazla bu kadar banka dolum turu (her tur bir sınıf × birkaç ders)
DAILY_FILL_SUBJ = 4      # bir turda doldurulan ders sayısı
DAILY_FILL_GOAL = 60     # yıl geneli kapsamda ders başına hedef soru sayısı


def daily_fill_async(min_interval=1200):
    """Tüm sınıflar için: yıl geneli kapsamlarda en az dolu (sınıf, ders) bankalarını arka planda doğrulanmış sorularla doldurur.
    Kota koruması: günlük tur limiti, model soğumadaysa ya da başka dolum sürüyorsa çalışmaz. Ana iş parçacığında çağrılır."""
    if demo_mode() or _DFILL["running"] or time.time() - _DFILL["last"] < min_interval:
        return False
    try:
        from . import store
        from . import curriculum as cur
        gk, mk = load_keys()
        if not gk and not mk and not extra_keys():
            return False
        ps = pool_status()
        if ps.get("cooling", 0) > 0 or ps.get("disabled", 0) > 0 or _FILLING:
            return False
        _DFILL["last"] = time.time()
        diffs = [d for d, _c in sorted(_diff_counts(store).items(), key=lambda kv: -kv[1])][:2] or [cur.DIFFICULTIES[2]]
        scope = {"type": "year"}
        best = None  # (doluluk, g, difficulty, [plan])
        for g in ("5", "6", "7", "8", "4"):
            gl = cur.GRADE_LABELS[g]
            for d in diffs:
                gaps = []
                for sj in cur.subjects_for(g):
                    topics = cur.scope_topic_text(g, sj, scope)
                    if not topics:
                        continue
                    pl = {"subject": sj, "n": 10, "topics": topics, "short": cur.scope_short(g, sj, scope)}
                    have = store.bank_count(bank_key_for(pl, gl, d))
                    if have < DAILY_FILL_GOAL:
                        gaps.append((have, pl))
                if gaps:
                    gaps.sort(key=lambda x: x[0])
                    tot = sum(h for h, _p in gaps[:DAILY_FILL_SUBJ])
                    if best is None or tot < best[0]:
                        best = (tot, gl, d, [p_ for _h, p_ in gaps[:DAILY_FILL_SUBJ]])
        if not best or not store.budget_take("dfill", DAILY_FILL_RUNS):
            return False
        _tot, gl, d, plan = best
        avoid = {k: list(v) for k, v in store.recent_stems().items()}
        _DFILL["running"] = True
    except Exception:
        return False

    def run():
        try:
            fill_bank(plan, gl, d, cur.scope_label(scope), avoid=avoid)
        except Exception:
            pass
        finally:
            _DFILL["running"] = False
    threading.Thread(target=run, daemon=True).start()
    return True


def _diff_counts(store):
    c = {}
    for h in store.history()[-40:]:
        d = h.get("difficulty")
        if d:
            c[d] = c.get(d, 0) + 1
    return c


def fill_bank(plan, grade_label, difficulty, scope_label, avoid=None, on_progress=None):
    """Soruları KULLANMADAN üretip bankaya koyar (sonraki sınav anında açılsın). -> (eklenen, hatalar)"""
    difficulty = _bump_diff(difficulty)
    if demo_mode():
        return 0, []
    from . import store
    qs, errs = generate_mc(plan, grade_label, difficulty, scope_label, avoid=avoid, on_progress=on_progress, use_bank=False, deposit=False, verify=True, count=False, _nb=True)
    added = 0
    for p in plan:
        mine = [q for q in qs if q.get("subject") == p["subject"]]
        added += store.bank_put(bank_key_for(p, grade_label, difficulty), _bank_meta(p, grade_label, difficulty), mine)
    return added, errs


def _valid_oyss(q):
    if not isinstance(q, dict):
        return False
    if len(str(q.get("question", "")).strip()) < 8 or not str(q.get("answer", "")).strip():
        return False
    rub = q.get("rubric")
    return isinstance(rub, list) and any(isinstance(r, dict) for r in rub)


def generate_oyss(subject_tables, grade_label, difficulty, avoid=None, on_progress=None):
    """subject_tables: [{subject, rows:[{code,topic,unit,n}]}] -> (questions, errors).
    Dersler paralel; her kazanım-soru 'yuvası' ayrı takip edilir, eksik yuvalar küçük gruplar hâlinde yeniden istenir:
    kazanım dağılımı ve soru sayısı TAM tutar."""
    from . import oyss as oy
    from . import visuals as _v
    avoid = avoid or {}
    gk, mk = load_keys() if not demo_mode() else ([], [])
    if not demo_mode() and not gk and not mk and not extra_keys():
        return [], ["API anahtarı bulunamadı"]
    seen = set(s for v in avoid.values() for s in v)
    seen_lock = threading.Lock()
    T0 = time.time()
    E = ThreadPoolExecutor(max_workers=WORKERS)

    def run_subject(si):
        st_ = subject_tables[si]
        subj, rows = st_["subject"], st_["rows"]
        total = sum(r["n"] for r in rows)
        labels = oy.difficulty_labels(total)
        random.shuffle(labels)
        slots, pos = [], 0
        for r in rows:
            for j in range(r["n"]):
                slots.append({"kazanim": f"{r['code']} – {r['topic']}", "code": str(r["code"]), "label": labels[pos + j]})
            pos += r["n"]
        errs = []
        if demo_mode():
            qs = []
            for j, sl in enumerate(slots):
                qs.append({"kazanim": sl["kazanim"], "type": "Açık uçlu" if j % 3 else "Kısa cevaplı", "difficulty": sl["label"],
                           "passage": "", "question": f"[{subj}] Demo açık uçlu soru {uuid.uuid4().hex[:4]}", "shape": None,
                           "answer": "Demo cevap", "rubric": [{"step": "Adım 1", "points": 5}, {"step": "Adım 2", "points": 5}]})
        else:
            filled = [None] * total
            av = list(avoid.get(subj, []))
            last_err, fails = None, 0

            def ask(batch):
                items = []
                for i in batch:
                    sl = slots[i]
                    if items and items[-1]["kazanim"] == sl["kazanim"]:
                        items[-1]["n"] += 1
                        items[-1]["labels"].append(sl["label"])
                    else:
                        items.append({"kazanim": sl["kazanim"], "n": 1, "labels": [sl["label"]]})
                done_stems = [_stem(q) for q in filled if q]
                return _ask_questions(oyss_prompt(grade_label, subj, items, difficulty, av + done_stems), gk, mk, next(_UID),
                                      lambda its: [q for q in its if _valid_oyss(q)], reasoning=GEN_REASONING.get(subj))

            for rnd in range(MAX_ROUNDS):
                missing = [i for i, f in enumerate(filled) if f is None]
                if not missing:
                    break
                if rnd > 0 and (time.time() - T0 > GEN_BUDGET or fails >= 3):
                    break
                batches = [missing[i:i + OYSS_CHUNK] for i in range(0, len(missing), OYSS_CHUNK)]
                futs = [(b, E.submit(ask, b)) for b in batches]
                progress = False
                for b, f in futs:
                    try:
                        got, err = f.result()
                    except Exception as e:
                        got, err = [], f"{type(e).__name__}: {str(e)[:80]}"
                    if err and not got:
                        last_err = err
                    free = list(b)
                    for q in got:
                        if not free:
                            break
                        s = _stem(q)
                        with seen_lock:
                            if not s or s in seen:
                                continue
                            j = next((i for i in free if slots[i]["code"] and slots[i]["code"] in str(q.get("kazanim", ""))), free[0])
                            free.remove(j)
                            seen.add(s)
                        q["kazanim"], q["difficulty"] = slots[j]["kazanim"], slots[j]["label"]
                        if q.get("type") not in ("Açık uçlu", "Kısa cevaplı"):
                            q["type"] = "Açık uçlu"
                        filled[j] = q
                        progress = True
                fails = 0 if progress else fails + 1
            qs = [q for q in filled if q is not None]
            if not qs:
                errs.append(f"{subj}: {last_err or 'geçersiz yanıt'}")
            elif len(qs) < total:
                errs.append(f"{subj}: {len(qs)}/{total} soru üretilebildi")
        pts = oy.point_split(len(qs))
        for q, p in zip(qs, pts):
            q["subject"] = subj
            q["points"] = p
            rub = [r for r in (q.get("rubric") or []) if isinstance(r, dict)]
            tot = sum(float(r.get("points", 0) or 0) for r in rub) or 1
            acc = 0
            for i, r in enumerate(rub):
                v = round(p * float(r.get("points", 0) or 0) / tot) if i < len(rub) - 1 else p - acc
                r["points"] = max(0, v)
                acc += r["points"]
            q["rubric"] = rub
            q["passage"] = q.get("passage") if str(q.get("passage")).lower() not in ("none", "null", "") else ""
            _sh = _v.normalize_shape(q.get("shape"))
            _sh = _sh if _sh and _sh.get("type") in ALLOWED_SHAPES.get(subj, {"table"}) else None
            q["shape"], _ = coherent_shape(_sh, f"{q.get('kazanim', '')} {q.get('question', '')} {q.get('passage', '')}")
            q["answer"] = str(q.get("answer", ""))
        return qs, errs

    questions, errors = [], []
    try:
        with ThreadPoolExecutor(max_workers=max(1, len(subject_tables))) as SX:
            outs = list(SX.map(lambda si: _safe_subject(run_subject, si, subject_tables[si]["subject"]), range(len(subject_tables))))
    finally:
        E.shutdown(wait=False)
    for si, (qs, errs) in enumerate(outs):
        questions += qs
        errors += errs
        if on_progress:
            on_progress(si + 1, len(subject_tables), subject_tables[si]["subject"])
    for i, q in enumerate(questions, 1):
        q["id"] = i
    return questions, errors


def _safe_subject(fn, si, subj):
    try:
        return fn(si)
    except Exception as e:  # bir dersin çökmesi diğerlerini etkilemesin
        return [], [f"{subj}: {type(e).__name__}: {str(e)[:80]}"]



# ---------------------------------------------------------------- yapay zekâ öğretmen: açık uçlu değerlendirme
TEACHER_SYSTEM = ("Sen deneyimli, adil ve gerçekçi bir Türkiye ortaokul öğretmenisin. MEB yazılı sınavı kâğıdı okur gibi puanlarsın: "
                  "puanlama anahtarındaki her adımı ayrı ayrı kontrol eder, öğrencinin yazdığı bilgiyi/işlemi görürsen o adımın puanını verir, "
                  "kısmen doğruysa kısmi puan verir. Boş ya da konu dışı cevaba 0 verirsin. Cömert de acımasız da olma; yazım hatası için puan kırma. "
                  "Geri bildirimin samimi, öğretmen ağzıyla, öğrenciye 'sen' diye hitap eden, kısa ve yol göstericidir. Yalnızca geçerli JSON döndür.")


def _teacher_prompt(items, grade_label):
    blocks = []
    for k, (i, q, ans) in enumerate(items, 1):
        rub = "; ".join(f"{r.get('step', '')} ({r.get('points', '')} p)" for r in (q.get("rubric") or []) if isinstance(r, dict))
        blocks.append(f"### Soru {k} (id={i}) — en çok {q.get('points')} puan\nKazanım: {q.get('kazanim', '')}\n"
                      f"Metin: {q.get('passage') or '-'}\nSoru: {q.get('question')}\nBeklenen cevap: {q.get('answer')}\n"
                      f"Puanlama anahtarı: {rub or 'yok'}\nÖĞRENCİ CEVABI: {ans or '(boş)'}")
    return (f"{grade_label} öğrencisinin yazılı sınav cevaplarını değerlendir.\n\n" + "\n\n".join(blocks) +
            '\n\nYalnızca şu JSON: {"results":[{"id":<soru id>,"points":<0 ile en çok puan arası sayı, 0.5 adımlı>,'
            '"verdict":"Tam|Kısmi|Yetersiz|Boş","feedback":"2-3 cümle öğretmen yorumu: neyi doğru yaptı, neyi eksik bıraktı","tip":"1 cümle somut çalışma önerisi"}]}')


def _words(t):
    return {w for w in re.sub(r"[^\w\s]", " ", str(t).lower()).split() if len(w) > 3}


def _demo_grade(q, ans):
    mx = float(q.get("points", 0))
    if not str(ans).strip():
        return {"points": 0.0, "verdict": "Boş", "feedback": "Bu soruyu boş bırakmışsın. Bilmesen bile bildiğin kısmı yazmak kısmi puan getirir.", "tip": "Kazanımı tekrar oku."}
    ref = _words(q.get("answer", ""))
    got = len(ref & _words(ans)) / max(1, len(ref))
    p = round(mx * min(1, got * 1.3) * 2) / 2
    return {"points": p, "verdict": "Tam" if p >= mx * .9 else "Kısmi" if p > 0 else "Yetersiz",
            "feedback": "Cevabındaki anahtar kavramları beklenen cevapla karşılaştırdım (demo değerlendirme).", "tip": "Beklenen cevabı oku ve eksik adımları tamamla."}


def grade_open(questions, open_answers, grade_label):
    """Açık uçlu cevapları yapay zekâ öğretmenle puanlar. -> ({idx: {points, verdict, feedback, tip}}, hatalar)"""
    from concurrent.futures import ThreadPoolExecutor
    out, errs = {}, []
    todo = []
    for i, q in enumerate(questions):
        ans = str(open_answers.get(i, "")).strip()
        if not ans:
            out[i] = {"points": 0.0, "verdict": "Boş", "feedback": "Bu soruyu boş bırakmışsın. Bilmediğin soruda bile bildiğin kısmı yazmak kısmi puan getirir.",
                      "tip": "Kazanımı tekrar edip beklenen cevapla karşılaştır."}
        else:
            todo.append((i, q, ans))
    if demo_mode():
        for i, q, a in todo:
            out[i] = _demo_grade(q, a)
        return out, errs
    gk, mk = load_keys()
    chunks = [todo[k:k + 4] for k in range(0, len(todo), 4)]

    def work(arg):
        n, ch = arg
        raw, err = multi_pool_generate(_teacher_prompt(ch, grade_label), gk, mk, offset=n, temperature=0.2)
        data = parse_json(raw) if raw else None
        return ch, data, err

    with ThreadPoolExecutor(max_workers=min(4, max(1, len(chunks)))) as ex:
        for ch, data, err in ex.map(work, list(enumerate(chunks))):
            res = {}
            for r in ((data or {}).get("results") or []) if isinstance(data, dict) else []:
                try:
                    res[int(r.get("id"))] = r
                except Exception:
                    pass
            for i, q, a in ch:
                r = res.get(i)
                if not r:
                    errs.append(f"Soru {i + 1} yapay zekâ ile puanlanamadı" + (f" ({err})" if err else ""))
                    continue
                mx = float(q.get("points", 0))
                try:
                    pts = max(0.0, min(mx, round(float(r.get("points", 0)) * 2) / 2))
                except Exception:
                    pts = 0.0
                out[i] = {"points": pts, "verdict": str(r.get("verdict") or ""), "feedback": str(r.get("feedback") or ""), "tip": str(r.get("tip") or "")}
    return out, errs


try:
    from . import store as _pst
    for _pn in ("generate_mc", "generate_oyss"):  # sınav hazırlama süresi ?admin=1 ekranında görünür
        if _pn in globals():
            globals()[_pn] = _pst.perf_timed("ai." + _pn)(globals()[_pn])
except Exception:
    pass
